// Package merkle verifies sorted-pair SHA-256 Merkle proofs with domain-separated leaves.
package merkle

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strings"
)

const MaxDepth = 32

type Hash = [32]byte

var ErrHash = errors.New("launchpad/merkle: hash must be 64 hex characters")

func Leaf(data []byte) Hash {
	buf := make([]byte, 0, len(data)+1)
	buf = append(buf, 0x00)
	buf = append(buf, data...)
	return sha256.Sum256(buf)
}

func node(a, b Hash) Hash {
	if bytes.Compare(a[:], b[:]) > 0 {
		a, b = b, a
	}
	buf := make([]byte, 0, 65)
	buf = append(buf, 0x01)
	buf = append(buf, a[:]...)
	buf = append(buf, b[:]...)
	return sha256.Sum256(buf)
}

func Root(leaves []Hash) Hash {
	if len(leaves) == 0 {
		panic("launchpad/merkle: no leaves")
	}
	level := append([]Hash{}, leaves...)
	for len(level) > 1 {
		next := make([]Hash, 0, (len(level)+1)/2)
		for i := 0; i < len(level); i += 2 {
			if i+1 == len(level) {
				next = append(next, level[i])
			} else {
				next = append(next, node(level[i], level[i+1]))
			}
		}
		level = next
	}
	return level[0]
}

func Proof(leaves []Hash, index int) []Hash {
	if index < 0 || index >= len(leaves) {
		panic("launchpad/merkle: index out of range")
	}
	level := append([]Hash{}, leaves...)
	proof := []Hash{}
	for len(level) > 1 {
		next := make([]Hash, 0, (len(level)+1)/2)
		for i := 0; i < len(level); i += 2 {
			if i+1 == len(level) {
				next = append(next, level[i])
				continue
			}
			if i == index {
				proof = append(proof, level[i+1])
			} else if i+1 == index {
				proof = append(proof, level[i])
			}
			next = append(next, node(level[i], level[i+1]))
		}
		index /= 2
		level = next
	}
	return proof
}

func Verify(root, leaf Hash, proof []Hash) bool {
	if len(proof) > MaxDepth {
		return false
	}
	h := leaf
	for _, p := range proof {
		h = node(h, p)
	}
	return h == root
}

func ParseHash(s string) (Hash, error) {
	var h Hash
	if len(s) != 64 {
		return h, ErrHash
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		return h, ErrHash
	}
	copy(h[:], b)
	return h, nil
}

func ParseProof(s string) ([]Hash, error) {
	if s == "" {
		return []Hash{}, nil
	}
	parts := strings.Split(s, ",")
	if len(parts) > MaxDepth {
		return nil, errors.New("launchpad/merkle: proof too long")
	}
	out := make([]Hash, len(parts))
	for i, p := range parts {
		h, err := ParseHash(p)
		if err != nil {
			return nil, err
		}
		out[i] = h
	}
	return out, nil
}

func FormatHash(h Hash) string { return hex.EncodeToString(h[:]) }

// Package meta validates launch metadata and addresses, and encodes text
// safely for JSON and Markdown.
package meta

import (
	"errors"
	"strings"
	"unicode"
	"unicode/utf8"
)

var (
	ErrName        = errors.New("launchpad/meta: name must be 1-32 bytes of printable text without markup characters")
	ErrTicker      = errors.New("launchpad/meta: ticker must be 1-10 characters A-Z or 0-9")
	ErrDescription = errors.New("launchpad/meta: description must be at most 280 bytes of printable text without markup characters")
	ErrImage       = errors.New("launchpad/meta: image must be an ipfs:// or https:// URI of at most 200 bytes")
	ErrWebsite     = errors.New("launchpad/meta: website must be an https:// URL of at most 200 bytes")
	ErrHandle      = errors.New("launchpad/meta: handle must be 1-32 characters A-Z, a-z, 0-9 or _")
)

const hexDigits = "0123456789abcdef"

// The chain decodes four texts to the same address: the bech32 form it gives
// a caller, that form in capitals, and the bech32m checksum in either case.
// State keyed by the text, such as a token balance or a role, recorded under
// any of the other three is something no caller can ever reach.

// bech32Value holds, for each character of the bech32 alphabet
// "qpzry9x8gf2tvdw0s3jn54khce6mua7l", its 5-bit value plus one. Zero marks
// every other byte, capitals included.
var bech32Value = [256]byte{
	'q': 1, 'p': 2, 'z': 3, 'r': 4, 'y': 5, '9': 6, 'x': 7, '8': 8,
	'g': 9, 'f': 10, '2': 11, 't': 12, 'v': 13, 'd': 14, 'w': 15, '0': 16,
	's': 17, '3': 18, 'j': 19, 'n': 20, '5': 21, '4': 22, 'k': 23, 'h': 24,
	'c': 25, 'e': 26, '6': 27, 'm': 28, 'u': 29, 'a': 30, '7': 31, 'l': 32,
}

// bech32Gen[t] is the XOR of the BIP-173 generators selected by the five
// bits of t: one table read per character instead of five tests.
var bech32Gen = [32]uint32{
	0x00000000, 0x3b6a57b2, 0x26508e6d, 0x1d3ad9df,
	0x1ea119fa, 0x25cb4e48, 0x38f19797, 0x039bc025,
	0x3d4233dd, 0x0628646f, 0x1b12bdb0, 0x2078ea02,
	0x23e32a27, 0x18897d95, 0x05b3a44a, 0x3ed9f3f8,
	0x2a1462b3, 0x117e3501, 0x0c44ecde, 0x372ebb6c,
	0x34b57b49, 0x0fdf2cfb, 0x12e5f524, 0x298fa296,
	0x1756516e, 0x2c3c06dc, 0x3106df03, 0x0a6c88b1,
	0x09f74894, 0x329d1f26, 0x2fa7c6f9, 0x14cd914b,
}

// The checksum state once the address prefix "g" has been absorbed, which
// BIP-173 expands to the values 3, 0, 7.
const bech32PrefixState uint32 = 0x8c07

// ValidAddress reports whether a is an account or realm address written the
// one way the chain gives it to a caller: "g1", then 38 lowercase bech32
// characters whose checksum is the original bech32 one. It reads the text
// itself: decoding and re-encoding it costs far more gas.
func ValidAddress(a address) bool {
	s := string(a)
	if len(s) != 40 || s[0] != 'g' || s[1] != '1' {
		return false
	}
	chk := bech32PrefixState
	for i := 2; i < 40; i++ {
		v := bech32Value[s[i]]
		if v == 0 {
			return false
		}
		chk = (chk&0x1ffffff)<<5 ^ uint32(v-1) ^ bech32Gen[chk>>25]
	}
	return chk == 1 // 1 is bech32; bech32m ends on 0x2bc830a3
}

func printable(s string) bool {
	if !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		if !unicode.IsPrint(r) {
			return false
		}
	}
	return true
}

func Name(s string) error {
	if len(s) < 1 || len(s) > 32 || !printable(s) || strings.ContainsAny(s, "[]()*#<>`|\\") || strings.TrimSpace(s) != s {
		return ErrName
	}
	return nil
}

func Ticker(s string) error {
	if len(s) < 1 || len(s) > 10 {
		return ErrTicker
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') {
			return ErrTicker
		}
	}
	return nil
}

func Description(s string) error {
	if len(s) > 280 || !printable(s) || strings.ContainsAny(s, "[]()<>") {
		return ErrDescription
	}
	return nil
}

func safeURI(s string, schemes []string) bool {
	if len(s) > 200 {
		return false
	}
	matched := false
	for _, p := range schemes {
		if strings.HasPrefix(s, p) && len(s) > len(p) {
			matched = true
		}
	}
	if !matched {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c <= 0x20 || c >= 0x7f || strings.IndexByte("\"'<>\\`()[]{}|^", c) >= 0 {
			return false
		}
	}
	return true
}

func Image(s string) error {
	if s == "" || safeURI(s, []string{"ipfs://", "https://"}) {
		return nil
	}
	return ErrImage
}

func Website(s string) error {
	if s == "" || safeURI(s, []string{"https://"}) {
		return nil
	}
	return ErrWebsite
}

func Handle(s string) error {
	if s == "" {
		return nil
	}
	if len(s) > 32 {
		return ErrHandle
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') && c != '_' {
			return ErrHandle
		}
	}
	return nil
}

// JSONString quotes s as a JSON string. Control bytes become \u00XX so the
// value survives the frontend's qeval double decode.
func JSONString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte(hexDigits[c>>4])
			b.WriteByte(hexDigits[c&0xf])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// EscapeMarkdown backslash-escapes every Markdown control character.
func EscapeMarkdown(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if strings.IndexByte("\\`*_{}[]()#+-.!|<>~", c) >= 0 {
			b.WriteByte('\\')
		}
		b.WriteByte(c)
	}
	return b.String()
}

// Package safemath is checked, non-negative int64 arithmetic for launchpad amounts.
package safemath

import "math/bits"

const (
	MaxInt64       int64 = 1<<63 - 1
	BPSDenominator int64 = 10_000
)

func mustNonNegative(v int64) {
	if v < 0 {
		panic("launchpad/safemath: negative value")
	}
}

func Add(a, b int64) int64 {
	mustNonNegative(a)
	mustNonNegative(b)
	if a > MaxInt64-b {
		panic("launchpad/safemath: overflow")
	}
	return a + b
}

func Sub(a, b int64) int64 {
	mustNonNegative(a)
	mustNonNegative(b)
	if b > a {
		panic("launchpad/safemath: underflow")
	}
	return a - b
}

func Mul(a, b int64) int64 {
	mustNonNegative(a)
	mustNonNegative(b)
	if a != 0 && b > MaxInt64/a {
		panic("launchpad/safemath: overflow")
	}
	return a * b
}

// MulDiv returns floor(a*b/d) using a 128-bit intermediate.
func MulDiv(a, b, d int64) int64 {
	q, _ := mulDivRem(a, b, d)
	return q
}

// MulDivUp returns ceil(a*b/d) using a 128-bit intermediate.
func MulDivUp(a, b, d int64) int64 {
	q, rem := mulDivRem(a, b, d)
	if rem {
		if q == MaxInt64 {
			panic("launchpad/safemath: overflow")
		}
		q++
	}
	return q
}

func mulDivRem(a, b, d int64) (int64, bool) {
	mustNonNegative(a)
	mustNonNegative(b)
	if d <= 0 {
		panic("launchpad/safemath: division by zero")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	if hi >= uint64(d) {
		panic("launchpad/safemath: overflow")
	}
	q, r := bits.Div64(hi, lo, uint64(d))
	if q > uint64(MaxInt64) {
		panic("launchpad/safemath: overflow")
	}
	return int64(q), r != 0
}

// BPS returns floor(amount*bps/10000) for 0 <= bps <= 10000.
func BPS(amount, bps int64) int64 {
	if bps < 0 || bps > BPSDenominator {
		panic("launchpad/safemath: basis points out of range")
	}
	return MulDiv(amount, bps, BPSDenominator)
}

func Min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

// Package currency moves launchpad payments in native ugnot or any GRC20 token.
//
// Every function takes the calling realm's own cur as rlm, so funds always move
// to or from that realm and never from a realm the caller can name.
package currency

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/samcrew/launchpad/meta/v1"
)

const NativeDenom = "ugnot"

// CollectNative accepts exactly amount ugnot attached by the user who called
// the realm directly, and returns that user. Coins attached to a call that
// reaches the realm through another realm belong to that other realm and are
// refused.
func CollectNative(_ int, rlm realm, amount int64) address {
	if !rlm.IsCurrent() {
		panic("launchpad/currency: rlm is not the current realm")
	}
	prev := rlm.Previous()
	if !prev.IsUserCall() {
		panic("launchpad/currency: native payment must be attached to a direct user call")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != NativeDenom || sent[0].Amount != amount {
		panic("launchpad/currency: attached coins do not match the amount due")
	}
	return prev.Address()
}

// AssertNoCoins refuses coins attached by a user who calls the realm directly:
// they would land in the realm, which keeps no account of them. Coins attached
// to a call that reaches the realm through another realm went to that other
// realm and are its business. The pinned chain also fails a call whose coins
// no code reads; this check does not depend on that.
func AssertNoCoins(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("launchpad/currency: rlm is not the current realm")
	}
	if rlm.Previous().IsUserCall() && len(unsafe.OriginSend()) != 0 {
		panic("launchpad/currency: this call does not accept coins")
	}
}

// A token ledger keys balances by the receiver's text, so a receiver in any
// spelling but the one the chain gives a caller would be paid into a balance
// no caller can reach.
func assertReceiver(to address) {
	if !meta.ValidAddress(to) {
		panic("launchpad/currency: invalid receiver")
	}
}

// PayNative sends amount ugnot from the calling realm.
func PayNative(_ int, rlm realm, to address, amount int64) {
	if !rlm.IsCurrent() {
		panic("launchpad/currency: rlm is not the current realm")
	}
	assertReceiver(to)
	banker.NewBanker(banker.BankerTypeRealmSend, rlm).
		SendCoins(rlm.Address(), to, chain.Coins{{NativeDenom, amount}})
}

// CollectToken pulls amount of tok from the realm's direct caller, who must have
// approved the calling realm, and returns that caller.
func CollectToken(_ int, rlm realm, tok *grc20.Token, amount int64) address {
	if !rlm.IsCurrent() {
		panic("launchpad/currency: rlm is not the current realm")
	}
	AssertNoCoins(0, rlm)
	payer := rlm.Previous().Address()
	if err := tok.RealmTeller(0, rlm).TransferFrom(0, rlm, payer, rlm.Address(), amount); err != nil {
		panic(err.Error())
	}
	return payer
}

// PayToken sends amount of tok from the calling realm's own balance.
func PayToken(_ int, rlm realm, tok *grc20.Token, to address, amount int64) {
	if !rlm.IsCurrent() {
		panic("launchpad/currency: rlm is not the current realm")
	}
	assertReceiver(to)
	if err := tok.RealmTeller(0, rlm).Transfer(0, rlm, to, amount); err != nil {
		panic(err.Error())
	}
}

// Package fairmath prices whole-lot fair-sale commitments without holding
// funds. No sale is active until a separate realm accounts for custody and
// exit rights. All amounts are token or quote base units.
package fairmath

import sm "gno.land/p/samcrew/launchpad/safemath/v1"

const MaxWindowSeconds int64 = 365 * 24 * 60 * 60

// Schedule defines quote atoms per lot. A zero decrement is a fixed-price
// sale; otherwise the price falls by Decrement every IntervalSeconds, never
// below FloorPrice. End is the scheduled close instant. An inventory or hard-
// cap close must pass its recorded transaction time to PriceAt instead.
type Schedule struct {
	Start           int64
	End             int64
	StartPrice      int64
	FloorPrice      int64
	Decrement       int64
	IntervalSeconds int64
}

func (s Schedule) Validate() {
	if s.Start < 0 || s.End <= s.Start || s.End-s.Start > MaxWindowSeconds ||
		s.StartPrice <= 0 || s.FloorPrice <= 0 || s.FloorPrice > s.StartPrice ||
		s.Decrement < 0 || s.IntervalSeconds <= 0 ||
		(s.Decrement == 0 && s.FloorPrice != s.StartPrice) {
		panic("launchpad/fairmath: invalid schedule")
	}
}

func (s Schedule) PriceAt(at int64) int64 {
	s.Validate()
	if at < s.Start || at > s.End {
		panic("launchpad/fairmath: time outside sale")
	}
	if s.Decrement == 0 {
		return s.StartPrice
	}
	steps := (at - s.Start) / s.IntervalSeconds
	gap := sm.Sub(s.StartPrice, s.FloorPrice)
	stepsToFloor := sm.MulDivUp(gap, 1, s.Decrement)
	if steps >= stepsToFloor {
		return s.FloorPrice
	}
	return sm.Sub(s.StartPrice, sm.Mul(steps, s.Decrement))
}

// MaxLots requires the escrowed sale allocation to consist of whole lots.
// No token dust is created by dividing the allocation between buyers.
func MaxLots(allocation, lotSize int64) int64 {
	if allocation <= 0 || lotSize <= 0 || allocation%lotSize != 0 {
		panic("launchpad/fairmath: invalid lot allocation")
	}
	return allocation / lotSize
}

type Order struct {
	Lots    int64
	Tokens  int64
	Deposit int64
}

// Caps snapshots the sale's hard cap in whole lots and soft cap in quote
// atoms actually spent at the final clearing price. Entry deposits and later
// refunds do not count toward the soft cap.
type Caps struct {
	HardLots  int64
	SoftQuote int64
}

func (c Caps) Validate(allocation, lotSize, highestPrice int64) {
	maxLots := MaxLots(allocation, lotSize)
	if c.HardLots <= 0 || c.HardLots > maxLots || c.SoftQuote <= 0 ||
		highestPrice <= 0 {
		panic("launchpad/fairmath: invalid caps")
	}
	if c.SoftQuote > sm.Mul(c.HardLots, highestPrice) {
		panic("launchpad/fairmath: unreachable soft cap")
	}
}

// AddLots rejects an order that would exceed the hard cap. Equality signals
// an early close at the contribution transaction's block time.
func (c Caps) AddLots(current, order int64) (int64, bool) {
	if c.HardLots <= 0 || current < 0 || current > c.HardLots || order <= 0 {
		panic("launchpad/fairmath: invalid cap state")
	}
	next := sm.Add(current, order)
	if next > c.HardLots {
		panic("launchpad/fairmath: hard cap exceeded")
	}
	return next, next == c.HardLots
}

// QuoteOrder gives the exact token and quote amounts for a whole-lot order.
func QuoteOrder(lots, lotSize, entryPrice int64) Order {
	if lots <= 0 || lotSize <= 0 || entryPrice <= 0 {
		panic("launchpad/fairmath: invalid order")
	}
	return Order{
		Lots: lots, Tokens: sm.Mul(lots, lotSize),
		Deposit: sm.Mul(lots, entryPrice),
	}
}

type Settlement struct {
	Succeeded     bool
	SoldTokens    int64
	GrossQuote    int64
	RefundQuote   int64
	UnsoldTokens  int64
}

// Clear partitions all whole-lot commitments at one pinned clearing price.
// A missed soft cap returns all deposits and all tokens. On success,
// deposits above the clearing-price gross remain buyer refund liabilities.
func Clear(c Caps, allocation, lotSize, totalLots, totalDeposits, closePrice int64) Settlement {
	maxLots := MaxLots(allocation, lotSize)
	if c.HardLots <= 0 || c.HardLots > maxLots || c.SoftQuote <= 0 ||
		totalLots < 0 || totalLots > c.HardLots || totalDeposits < 0 || closePrice <= 0 {
		panic("launchpad/fairmath: invalid settlement")
	}
	sold := sm.Mul(totalLots, lotSize)
	gross := sm.Mul(totalLots, closePrice)
	if totalDeposits < gross {
		panic("launchpad/fairmath: unfunded settlement")
	}
	if gross < c.SoftQuote {
		return Settlement{RefundQuote: totalDeposits, UnsoldTokens: allocation}
	}
	return Settlement{
		Succeeded: true,
		SoldTokens: sold, GrossQuote: gross,
		RefundQuote: sm.Sub(totalDeposits, gross),
		UnsoldTokens: sm.Sub(allocation, sold),
	}
}

type BuyerClaim struct {
	Tokens      int64
	SpentQuote  int64
	RefundQuote int64
}

// Claim computes one buyer's exact rights after Clear. Claims over the same
// orders telescope to its aggregate settlement, regardless of claim order.
func Claim(success bool, lots, deposit, lotSize, closePrice int64) BuyerClaim {
	if lots <= 0 || deposit <= 0 || lotSize <= 0 || closePrice <= 0 {
		panic("launchpad/fairmath: invalid claim")
	}
	if !success {
		return BuyerClaim{RefundQuote: deposit}
	}
	spent := sm.Mul(lots, closePrice)
	if deposit < spent {
		panic("launchpad/fairmath: unfunded claim")
	}
	return BuyerClaim{
		Tokens: sm.Mul(lots, lotSize), SpentQuote: spent,
		RefundQuote: sm.Sub(deposit, spent),
	}
}

// Package vesting computes cliff-then-linear token release.
package vesting

import sm "gno.land/p/samcrew/launchpad/safemath/v1"

type Schedule struct {
	Total    int64
	Start    int64 // unix seconds
	Cliff    int64 // seconds after Start before anything vests
	Duration int64 // seconds after Start when everything has vested
}

func (s Schedule) Validate() {
	if s.Total <= 0 || s.Start < 0 || s.Duration <= 0 || s.Cliff < 0 || s.Cliff > s.Duration {
		panic("launchpad/vesting: invalid schedule")
	}
	sm.Add(s.Start, s.Duration)
}

func (s Schedule) VestedAt(now int64) int64 {
	s.Validate()
	if now < sm.Add(s.Start, s.Cliff) {
		return 0
	}
	elapsed := now - s.Start
	if elapsed >= s.Duration {
		return s.Total
	}
	return sm.MulDiv(s.Total, elapsed, s.Duration)
}

func (s Schedule) Releasable(now, released int64) int64 {
	return sm.Sub(s.VestedAt(now), released)
}

// Package config is the versioned, governed configuration for Memba Launchpad.
// Its admin is the account that published it until a two-step handoff moves
// the role. Every lane starts paused and without terms.
package config

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime/unsafe"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	LaneDirect     = "direct"
	LaneFairSale   = "fairsale"
	LaneAirdrop    = "airdrop"
	LaneCollection = "collection"
	LaneNFTDrops   = "nft_drops"
	LaneNFTMarket  = "nft_market"
	NativeCurrency = "ugnot"
	LedgerTokens   = "tokens"
	LedgerNFT      = "nft"
	maxCurrencies  = 16
	maxIssuers     = 32
	issuerPrefix   = "gno.land/r/samcrew/"
	maxCreationFee = sm.MaxInt64 / 12
)

// CurrencyParams holds the terms of one quote currency. A fee of -1 closes
// the lane that charges it.
type CurrencyParams struct {
	Key                 string
	DirectCreationFee   int64
	FairSaleCreationFee int64 // never below DirectCreationFee: cancelling a sale returns its allocation
	FairSaleRaiseCap    int64 // most quote one fair sale may hold in escrow; 0 closes fair sales
	CollectionFee       int64
}

// Params is one immutable snapshot of launch terms. A rate of -1 closes the
// lane that charges it.
type Params struct {
	PrimaryFeeBPS      int64 // share of settled fair-sale proceeds
	NFTPrimaryFeeBPS   int64
	NFTSecondaryFeeBPS int64
	Treasury           address
	Currencies         []CurrencyParams
}

var (
	lanes = []string{LaneDirect, LaneFairSale, LaneAirdrop, LaneCollection, LaneNFTDrops, LaneNFTMarket}
	// No function of these realms can pay out a balance sent to their address.
	unspendable = []string{
		"gno.land/r/samcrew/launchpad/config/v1",
		"gno.land/r/samcrew/launchpad/tokens/v1",
		"gno.land/r/samcrew/launchpad/sales/v1",
		"gno.land/r/samcrew/launchpad/nft/v1",
		"gno.land/r/samcrew/launchpad/drops/v1",
		"gno.land/r/samcrew/launchpad/market/v1",
		"gno.land/r/samcrew/launchpad/curation/v1",
		"gno.land/r/samcrew/memba_dao",
		// The governance core and its bridge to the legacy apps hold no
		// treasury and no generic call: nothing there could pay a fee out.
		"gno.land/r/samcrew/memba_gov",
		"gno.land/r/samcrew/memba_bridge_v1",
	}

	admin        address
	pendingAdmin address
	pauser       address
	issuers      = map[string]bool{} // "<ledger>:<realm address>"
	versions     []Params
	allowed      = map[string]bool{}
	paused       = map[string]bool{}
	verified     = map[string]bool{}
	reserved     = map[string]bool{}
	owedCeilings = map[string]int64{} // absent: no ceiling
)

func init() {
	admin = unsafe.OriginCaller()
	versions = []Params{{PrimaryFeeBPS: -1, NFTPrimaryFeeBPS: -1, NFTSecondaryFeeBPS: -1}}
	for _, lane := range lanes {
		paused[lane] = true
	}
	for _, ticker := range []string{"MEMBA", "GNOT", "UGNOT", "WUGNOT", "GNS", "USDC", "USDT", "ATOM", "BTC", "ETH", "SAMCREW"} {
		reserved[ticker] = true
	}
}

// caller is the immediate user or realm. Coins attached to a direct call
// would land in this realm, which has no way to return them.
func caller(cur realm) address {
	// The pinned VM already refuses a realm context that is not the live one
	// before this line runs. Published code outlives a VM release, so the
	// check stays.
	if !cur.IsCurrent() {
		panic("launchpad/config: stale realm context")
	}
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) != 0 {
		panic("launchpad/config: this call does not accept coins")
	}
	return cur.Previous().Address()
}

func requireAdmin(cur realm) {
	if caller(cur) != admin {
		panic("launchpad/config: admin only")
	}
}

func unspendableRealm(who address) bool {
	for _, path := range unspendable {
		if who == chain.PackageAddress(path) {
			return true
		}
	}
	return false
}

// IsUnspendable reports whether a fee or a royalty paid to who could never
// be paid out again: who is one of the realms listed above, which have no
// function for that, or it is not an address as the chain writes one, so no
// caller can ever present it. It is a check for such receivers only, not for
// the recipient of a transfer: the sales realm is on the list and rightly
// holds and moves ledger balances of its own.
func IsUnspendable(who address) bool {
	return !meta.ValidAddress(who) || unspendableRealm(who)
}

func validLane(lane string) bool {
	for _, l := range lanes {
		if l == lane {
			return true
		}
	}
	return false
}

func versionString() string { return strconv.FormatInt(GetCurrentVersion(), 10) }

func validAssetID(id string) bool {
	if len(id) < 2 || len(id) > 20 || (id[0] != 'T' && id[0] != 'C') || id[1] < '1' || id[1] > '9' {
		return false
	}
	for i := 2; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return false
		}
	}
	n, err := strconv.ParseInt(id[1:], 10, 64)
	return err == nil && n > 0
}

// ProposeAdmin stages a handoff to a user account or a realm. Nothing changes
// until that exact address accepts, so a target that cannot call is harmless.
func ProposeAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !meta.ValidAddress(next) || next == admin {
		panic("launchpad/config: invalid next admin")
	}
	pendingAdmin = next
	chain.Emit("AdminProposed", "admin", admin.String(), "pending", next.String())
}

func CancelAdminProposal(cur realm) {
	requireAdmin(cur)
	if pendingAdmin == "" {
		panic("launchpad/config: no pending admin")
	}
	pendingAdmin = ""
	chain.Emit("AdminProposalCancelled", "admin", admin.String())
}

func AcceptAdmin(cur realm) {
	who := caller(cur)
	if pendingAdmin == "" || who != pendingAdmin {
		panic("launchpad/config: pending admin only")
	}
	previous := admin
	admin = who
	pendingAdmin = ""
	chain.Emit("AdminAccepted", "admin", who.String(), "previous", previous.String())
}

// validIssuerPath accepts a realm path below the samcrew namespace whose
// segments are plain lowercase names: nothing that could resolve elsewhere.
func validIssuerPath(path string) bool {
	if len(path) > 200 || !strings.HasPrefix(path, issuerPrefix) {
		return false
	}
	for _, segment := range strings.Split(path[len(issuerPrefix):], "/") {
		if segment == "" {
			return false
		}
		for i := 0; i < len(segment); i++ {
			c := segment[i]
			if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '_' {
				return false
			}
		}
	}
	return true
}

// AllowIssuer lists a realm under gno.land/r/samcrew/ as an issuer for one
// ledger to read. The list only grows, so a ledger can bind what an issuer
// created to that issuer for good.
func AllowIssuer(cur realm, ledger, pkgPath string) {
	requireAdmin(cur)
	if (ledger != LedgerTokens && ledger != LedgerNFT) || !validIssuerPath(pkgPath) ||
		len(issuers) >= maxIssuers {
		panic("launchpad/config: invalid issuer")
	}
	issuer := chain.PackageAddress(pkgPath)
	if issuer == cur.Address() {
		panic("launchpad/config: invalid issuer")
	}
	key := ledger + ":" + issuer.String()
	if issuers[key] {
		panic("launchpad/config: issuer already allowed")
	}
	issuers[key] = true
	chain.Emit("IssuerAllowed", "ledger", ledger, "path", pkgPath, "issuer", issuer.String(), "actor", admin.String())
}

func IsIssuer(ledger string, who address) bool { return issuers[ledger+":"+who.String()] }

func GetAdmin() address        { return admin }
func GetPendingAdmin() address { return pendingAdmin }
func GetPauser() address       { return pauser }

func copyParams(p Params) Params {
	copyP := p
	copyP.Currencies = make([]CurrencyParams, len(p.Currencies))
	copy(copyP.Currencies, p.Currencies)
	return copyP
}

func GetCurrentVersion() int64 { return int64(len(versions)) }

func GetVersion(version int64) Params {
	if version < 1 || version > int64(len(versions)) {
		panic("launchpad/config: unknown version")
	}
	return copyParams(versions[version-1])
}

// One value of the current terms each, so a check can compare its text: the
// publisher's manual flow reads one before and after each setter. A rate or a
// fee of -1 is not set; so is every fee of a currency without terms.
func GetTreasury() address         { return versions[len(versions)-1].Treasury }
func GetPrimaryFeeBPS() int64      { return versions[len(versions)-1].PrimaryFeeBPS }
func GetNFTPrimaryFeeBPS() int64   { return versions[len(versions)-1].NFTPrimaryFeeBPS }
func GetNFTSecondaryFeeBPS() int64 { return versions[len(versions)-1].NFTSecondaryFeeBPS }

// GetTokenTerms is "<direct creation fee>,<fair-sale creation fee>,<raise cap>"
// in a currency.
func GetTokenTerms(key string) string {
	c, ok := findCurrency(versions[len(versions)-1], key)
	if !ok {
		return "-1,-1,0"
	}
	return strconv.FormatInt(c.DirectCreationFee, 10) + "," + strconv.FormatInt(c.FairSaleCreationFee, 10) + "," + strconv.FormatInt(c.FairSaleRaiseCap, 10)
}

func GetCollectionFee(key string) int64 {
	c, ok := findCurrency(versions[len(versions)-1], key)
	if !ok {
		return -1
	}
	return c.CollectionFee
}

func AssertExpectedVersion(expected int64) {
	if expected != GetCurrentVersion() {
		panic("config changed")
	}
}

func validateParams(p Params) {
	if p.PrimaryFeeBPS < -1 || p.PrimaryFeeBPS > 500 ||
		p.NFTPrimaryFeeBPS < -1 || p.NFTPrimaryFeeBPS > 500 ||
		p.NFTSecondaryFeeBPS < -1 || p.NFTSecondaryFeeBPS > 200 {
		panic("launchpad/config: parameter out of range")
	}
	if p.Treasury != "" {
		if !meta.ValidAddress(p.Treasury) {
			panic("launchpad/config: invalid treasury")
		}
		if unspendableRealm(p.Treasury) {
			panic("launchpad/config: treasury cannot spend")
		}
	}
	if len(p.Currencies) > maxCurrencies {
		panic("launchpad/config: too many currencies")
	}
	seen := map[string]bool{}
	for _, c := range p.Currencies {
		if c.Key == "" || len(c.Key) > 200 || seen[c.Key] ||
			(c.Key != NativeCurrency && grc20reg.Get(c.Key) == nil) ||
			c.DirectCreationFee < -1 || c.DirectCreationFee > maxCreationFee ||
			c.FairSaleCreationFee < -1 || c.FairSaleCreationFee > maxCreationFee ||
			c.CollectionFee < -1 || c.CollectionFee > maxCreationFee ||
			c.FairSaleRaiseCap < 0 {
			panic("launchpad/config: invalid currency terms")
		}
		if c.FairSaleCreationFee >= 0 &&
			(c.DirectCreationFee < 0 || c.FairSaleCreationFee < c.DirectCreationFee) {
			panic("launchpad/config: fair-sale fee below direct fee")
		}
		// With direct <= fair < cap, and no cap while fair sales are closed,
		// no two of the three can be swapped unnoticed.
		if c.FairSaleRaiseCap != 0 &&
			(c.FairSaleCreationFee < 0 || c.FairSaleRaiseCap <= c.FairSaleCreationFee) {
			panic("launchpad/config: raise cap not above fair-sale fee")
		}
		seen[c.Key] = true
	}
}

// Terms change only through the setters below. Each takes scalar arguments,
// so a user account can call it, and appends one snapshot that passed the
// whole validation; earlier snapshots never change. A launch pins the version
// it was created under, and an action signed against an older version fails.

func latest() Params { return copyParams(versions[len(versions)-1]) }

func appendVersion(next Params, change string) int64 {
	validateParams(next)
	versions = append(versions, next)
	chain.Emit("ConfigVersionAdded", "version", versionString(), "change", change, "actor", admin.String())
	return GetCurrentVersion()
}

func findCurrency(p Params, key string) (CurrencyParams, bool) {
	for _, c := range p.Currencies {
		if c.Key == key {
			return c, true
		}
	}
	return CurrencyParams{}, false
}

// currencyTerms returns the index of key's terms in p, adding them with every
// lane closed when the currency is new.
func currencyTerms(p *Params, key string) int {
	for i, c := range p.Currencies {
		if c.Key == key {
			return i
		}
	}
	p.Currencies = append(p.Currencies, CurrencyParams{
		Key: key, DirectCreationFee: -1, FairSaleCreationFee: -1, CollectionFee: -1,
	})
	return len(p.Currencies) - 1
}

// SetTreasury names the receiver of protocol fees. Once named it can be
// replaced, not removed.
func SetTreasury(cur realm, treasury address) int64 {
	requireAdmin(cur)
	if treasury == "" {
		panic("launchpad/config: invalid treasury")
	}
	next := latest()
	next.Treasury = treasury
	return appendVersion(next, "treasury")
}

func SetPrimaryFeeBPS(cur realm, bps int64) int64 {
	requireAdmin(cur)
	next := latest()
	next.PrimaryFeeBPS = bps
	return appendVersion(next, "primary_fee")
}

func SetNFTPrimaryFeeBPS(cur realm, bps int64) int64 {
	requireAdmin(cur)
	next := latest()
	next.NFTPrimaryFeeBPS = bps
	return appendVersion(next, "nft_primary_fee")
}

func SetNFTSecondaryFeeBPS(cur realm, bps int64) int64 {
	requireAdmin(cur)
	next := latest()
	next.NFTSecondaryFeeBPS = bps
	return appendVersion(next, "nft_secondary_fee")
}

// SetTokenTerms prices token creation in one currency and bounds what a
// single fair sale may raise in it.
func SetTokenTerms(cur realm, key string, directCreationFee, fairSaleCreationFee, fairSaleRaiseCap int64) int64 {
	requireAdmin(cur)
	next := latest()
	i := currencyTerms(&next, key)
	next.Currencies[i].DirectCreationFee = directCreationFee
	next.Currencies[i].FairSaleCreationFee = fairSaleCreationFee
	next.Currencies[i].FairSaleRaiseCap = fairSaleRaiseCap
	return appendVersion(next, "token_terms")
}

func SetCollectionFee(cur realm, key string, fee int64) int64 {
	requireAdmin(cur)
	next := latest()
	i := currencyTerms(&next, key)
	next.Currencies[i].CollectionFee = fee
	return appendVersion(next, "collection_fee")
}

// RemoveCurrency drops a currency's terms, its allowlist entry and its owed
// ceiling, so adding terms again later neither reopens it nor brings back an
// old ceiling by itself.
func RemoveCurrency(cur realm, key string) int64 {
	requireAdmin(cur)
	current := latest()
	next := current
	next.Currencies = nil
	for _, c := range current.Currencies {
		if c.Key != key {
			next.Currencies = append(next.Currencies, c)
		}
	}
	if len(next.Currencies) == len(current.Currencies) {
		panic("launchpad/config: unknown currency")
	}
	delete(allowed, key)
	delete(owedCeilings, key)
	return appendVersion(next, "currency_removed")
}

// IsLaneReady checks only immutable terms. The immediate allowlist is checked
// at action time so delisting cannot prevent an old launch's exits.
func IsLaneReady(lane, currency string) bool {
	p := versions[len(versions)-1]
	c, ok := findCurrency(p, currency)
	if !ok || p.Treasury == "" {
		return false
	}
	switch lane {
	// A direct fee is what opens a currency to the token lanes: a fair sale
	// cannot be priced without one, and an airdrop, which is free, needs it too.
	case LaneDirect, LaneAirdrop:
		return c.DirectCreationFee >= 0
	case LaneFairSale:
		return c.FairSaleCreationFee >= 0 && c.FairSaleRaiseCap > 0 && p.PrimaryFeeBPS >= 0
	// A collection fee is what opens a currency to the NFT lanes.
	case LaneCollection:
		return c.CollectionFee >= 0
	case LaneNFTDrops:
		return c.CollectionFee >= 0 && p.NFTPrimaryFeeBPS >= 0
	case LaneNFTMarket:
		return c.CollectionFee >= 0 && p.NFTSecondaryFeeBPS >= 0
	}
	return false
}

// Pause closes a lane to new launches and contributions. Claims, refunds and
// settlements never read the gate, so nothing here can hold funds back.
func Pause(cur realm, lane string) {
	who := caller(cur)
	if !validLane(lane) {
		panic("launchpad/config: invalid lane")
	}
	if who != admin && who != pauser {
		panic("launchpad/config: pauser or admin only")
	}
	paused[lane] = true
	chain.Emit("LanePaused", "lane", lane, "actor", who.String())
}

// Unpause opens a lane. It needs a pauser in place and one listed currency
// whose terms for the lane are complete.
func Unpause(cur realm, lane, currency string) {
	requireAdmin(cur)
	if !validLane(lane) {
		panic("launchpad/config: invalid lane")
	}
	if pauser == "" || !allowed[currency] || !IsLaneReady(lane, currency) {
		panic("launchpad/config: lane is incomplete")
	}
	paused[lane] = false
	chain.Emit("LaneUnpaused", "lane", lane, "currency", currency, "version", versionString(), "actor", admin.String())
}

func IsPaused(lane string) bool {
	if !validLane(lane) {
		return true
	}
	return paused[lane]
}

// AssertLaneOpen gates a new inflow: the lane is open and the currency is
// listed with complete terms. A caller that charges the terms in force reads
// them in the same transaction, as the NFT realms do; one that charges at the
// version its user signed for checks that version with AssertNewAction, as
// token creations and fair-sale launches do. The token lanes' exits use the
// terms recorded at launch and pass no gate.
func AssertLaneOpen(lane, currency string) {
	if IsPaused(lane) || !allowed[currency] || !IsLaneReady(lane, currency) {
		panic("launchpad/config: new action unavailable")
	}
}

// AssertNewAction also pins the version whose prices the caller signed for.
func AssertNewAction(lane, currency string, expectedVersion int64) {
	AssertExpectedVersion(expectedVersion)
	AssertLaneOpen(lane, currency)
}

// SetPauser names the one address, besides the admin, that may close lanes.
func SetPauser(cur realm, next address) {
	requireAdmin(cur)
	if !meta.ValidAddress(next) {
		panic("launchpad/config: invalid pauser")
	}
	pauser = next
	chain.Emit("PauserChanged", "pauser", next.String(), "actor", admin.String())
}

func SetCurrencyAllowed(cur realm, key string, value bool) {
	requireAdmin(cur)
	if !value {
		delete(allowed, key)
	} else if _, ok := findCurrency(versions[len(versions)-1], key); ok {
		allowed[key] = true
	} else {
		panic("launchpad/config: currency terms missing")
	}
	chain.Emit("CurrencyAllowed", "currency", key, "allowed", strconv.FormatBool(value), "version", versionString(), "actor", admin.String())
}

func IsCurrencyAllowed(key string) bool { return allowed[key] }

// SetSalesOwedCeiling bounds what the sales realm may owe in one currency,
// its fees, escrow, refunds and proceeds together, for a fair-sale
// contribution to be accepted. Nothing else reads it: settlements, claims,
// releases and sweeps go through at any ceiling, and a ceiling below what is
// already owed only stops new contributions. Unlike a pause, it lets running
// sales take orders while there is room. MaxInt64, the default, is no
// ceiling. It is not a term a launch signs for, so it adds no version.
func SetSalesOwedCeiling(cur realm, key string, ceiling int64) {
	requireAdmin(cur)
	if _, ok := findCurrency(versions[len(versions)-1], key); !ok {
		panic("launchpad/config: currency terms missing")
	}
	if ceiling < 0 {
		panic("launchpad/config: invalid ceiling")
	}
	if ceiling == sm.MaxInt64 {
		delete(owedCeilings, key)
	} else {
		owedCeilings[key] = ceiling
	}
	chain.Emit("SalesOwedCeiling", "currency", key, "ceiling", strconv.FormatInt(ceiling, 10), "actor", admin.String())
}

func GetSalesOwedCeiling(key string) int64 {
	if ceiling, ok := owedCeilings[key]; ok {
		return ceiling
	}
	return sm.MaxInt64
}

func SetVerified(cur realm, assetID string, value bool) {
	requireAdmin(cur)
	if !validAssetID(assetID) {
		panic("launchpad/config: invalid asset ID")
	}
	verified[assetID] = value
	chain.Emit("Verified", "asset", assetID, "verified", strconv.FormatBool(value), "actor", admin.String())
}

func IsVerified(assetID string) bool { return verified[assetID] }

func SetReserved(cur realm, ticker string, value bool) {
	requireAdmin(cur)
	if meta.Ticker(ticker) != nil {
		panic("launchpad/config: invalid ticker")
	}
	reserved[ticker] = value
	chain.Emit("Reserved", "ticker", ticker, "reserved", strconv.FormatBool(value), "actor", admin.String())
}

func IsReserved(ticker string) bool { return reserved[ticker] }

package config

import (
	"strconv"

	"gno.land/p/samcrew/launchpad/meta/v1"
)

// ActionStatusJSON reports only the current config gate for a new action.
// Other realm, custody and publication requirements are separate.
func ActionStatusJSON(lane, currency string) string {
	if !validLane(lane) || currency == "" || len(currency) > 200 {
		panic("launchpad/config: invalid action status query")
	}
	blocked := IsPaused(lane)
	allowlisted := IsCurrencyAllowed(currency)
	ready := IsLaneReady(lane, currency)
	return "{" +
		`"schema":"launchpad-config-action-v1"` +
		`,"lane":` + meta.JSONString(lane) +
		`,"currency":` + meta.JSONString(currency) +
		`,"version":` + meta.JSONString(strconv.FormatInt(GetCurrentVersion(), 10)) +
		`,"paused":` + strconv.FormatBool(blocked) +
		`,"allowlisted":` + strconv.FormatBool(allowlisted) +
		`,"laneReady":` + strconv.FormatBool(ready) +
		`,"configGateOpen":` + strconv.FormatBool(!blocked && allowlisted && ready) + "}"
}

package nft

import (
	"chain"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/samcrew/launchpad/meta/v1"
)

const (
	MetadataStatic  = "static"  // base URI fixed at creation
	MetadataReveal  = "reveal"  // placeholder until one committed reveal
	MetadataMutable = "mutable" // creator may change the base URI until frozen
)

// metadata decides what TokenURI answers. Once frozen, the base URI can never
// change again; only then can traits be committed.
type metadata struct {
	mode           string
	baseURI        string  // empty until a reveal
	placeholderURI string  // reveal: served for every token until Reveal
	commitment     string  // reveal: RevealCommitment of the base URI to come
	committer      address // reveal: the creator who made the commitment
	provenance     string  // reveal: SHA-256 of the ordered metadata manifest
	frozen         bool
	revision       int64 // base URI changes since creation
}

// contentAddressed accepts an IPFS path that resolves to the same files for
// good: a server behind any other scheme could change them at will, and an
// empty CID, a "." or ".." segment, an escape, a query or a fragment could
// make a gateway resolve it elsewhere, a mutable IPNS name included.
func contentAddressed(s string) bool {
	return strings.HasPrefix(s, "ipfs://") && len(s) > 7 && s[7] != '/' &&
		!strings.Contains(s, "/.") && !strings.ContainsAny(s, "%?#") && meta.Image(s) == nil
}

// A base URI is a directory: token n resolves to <base><n>.json.
func validBaseURI(s string) bool {
	return contentAddressed(s) && s[len(s)-1] == '/'
}

func validHash(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if c := s[i]; !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// RevealCommitment is what a creator commits to at creation and opens at
// Reveal: sha256("launchpad-reveal-v1|<creator>|<salt>|<base URI>"), with a
// salt of 64 hex digits the creator keeps secret until then. The salt keeps a
// guessed URI from being confirmed before the reveal. The creator's address
// keeps another account from reusing the commitment: a collection's ID does
// not exist yet when its creator commits, so the account stands in for it.
func RevealCommitment(creator address, salt, baseURI string) string {
	h := sha256.Sum256([]byte("launchpad-reveal-v1|" + creator.String() + "|" + salt + "|" + baseURI))
	return hex.EncodeToString(h[:])
}

func newMetadata(mode, baseURI, placeholderURI, commitment, provenance string, creator address) metadata {
	ok := false
	switch mode {
	case MetadataStatic, MetadataMutable:
		ok = validBaseURI(baseURI) && placeholderURI == "" && commitment == "" && provenance == ""
	case MetadataReveal:
		// What is hidden must be content-addressed, or the commitment would
		// say nothing about the files behind it.
		ok = baseURI == "" && contentAddressed(placeholderURI) &&
			strings.HasSuffix(placeholderURI, ".json") &&
			validHash(commitment) && commitment != strings.Repeat("0", 64) &&
			validHash(provenance)
	}
	if !ok {
		panic("launchpad/nft: invalid metadata terms")
	}
	m := metadata{mode: mode, baseURI: baseURI, placeholderURI: placeholderURI,
		commitment: commitment, provenance: provenance, frozen: mode == MetadataStatic}
	if mode == MetadataReveal {
		m.committer = creator
	}
	return m
}

func (m metadata) tokenURI(number int64) string {
	if m.baseURI == "" {
		return m.placeholderURI
	}
	return m.baseURI + strconv.FormatInt(number, 10) + ".json"
}

func emitMetadata(id string, m metadata) {
	chain.Emit("MetadataChanged", "collection", id, "base_uri", m.baseURI,
		"revision", strconv.FormatInt(m.revision, 10),
		"frozen", strconv.FormatBool(m.frozen))
}

// Reveal publishes the base URI committed at creation, with the salt that
// opens the commitment, and fixes it for good. The commitment stays bound to
// the account that created the collection, whoever holds the creator role now.
func Reveal(cur realm, id, baseURI, salt string) {
	m := &creatorOf(cur, id).metadata
	if m.mode != MetadataReveal || m.frozen {
		panic("launchpad/nft: nothing to reveal")
	}
	if !validBaseURI(baseURI) || !validHash(salt) ||
		RevealCommitment(m.committer, salt, baseURI) != m.commitment {
		panic("launchpad/nft: reveal does not match the commitment")
	}
	m.baseURI, m.frozen, m.revision = baseURI, true, 1
	emitMetadata(id, *m)
}

func mutable(cur realm, id string) *metadata {
	m := &creatorOf(cur, id).metadata
	if m.mode != MetadataMutable || m.frozen {
		panic("launchpad/nft: metadata is fixed")
	}
	return m
}

// SetBaseURI points a mutable collection at new metadata. Every change is
// announced with its revision number.
func SetBaseURI(cur realm, id, baseURI string) {
	m := mutable(cur, id)
	if !validBaseURI(baseURI) || baseURI == m.baseURI {
		panic("launchpad/nft: invalid base URI")
	}
	m.baseURI = baseURI
	m.revision++
	emitMetadata(id, *m)
}

// FreezeMetadata gives up the right to change a mutable collection's base URI.
func FreezeMetadata(cur realm, id string) {
	m := mutable(cur, id)
	m.frozen = true
	emitMetadata(id, *m)
}

// CommitTraits records, once, the Merkle root of the collection's traits. It
// waits for frozen metadata so the root cannot outlive the files it describes.
// A leaf is sha256(0x00 || "launchpad-trait-v1|<collection>|<number>|<type>=<value>")
// in a p/samcrew/launchpad/merkle/v1 tree, where neither the type nor the
// value contains "=" or "|": a leaf has then one reading only, and a leaf
// that breaks the rule matches no trait offer. The ledger cannot check the
// root against the files; whoever relies on it must recompute it from them.
func CommitTraits(cur realm, id, root string) {
	c := creatorOf(cur, id)
	if !c.metadata.frozen || c.traitsRoot != "" || !validHash(root) {
		panic("launchpad/nft: traits cannot be committed")
	}
	c.traitsRoot = root
	chain.Emit("TraitsCommitted", "collection", id, "root", root)
}

// TraitsRoot is empty until the creator commits one.
func TraitsRoot(id string) string { return mustCollection(id).traitsRoot }

// Package nft is the Launchpad collection ledger. Each collection is a GRC721
// token whose transfer mode, royalties and metadata rules are fixed at
// creation. Collections are created, and their tokens minted, only by issuer
// realms: the Launchpad drops realm and any realm the config admin adds.
// Holders move, approve and burn their own tokens. The ledger has no admin of
// its own: nothing here can move a holder's token or change a collection's
// terms, and a paused lane stops only new collections and new mints.
package nft

import (
	"chain"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
)

const (
	dropsPath            = "gno.land/r/samcrew/launchpad/drops/v1"
	marketPath           = "gno.land/r/samcrew/launchpad/market/v1"
	ModeOpen             = "open"
	ModeRoyaltyProtected = "royalty_protected"
	ModeSoulbound        = "soulbound"
	StatusActive         = "active"
	StatusBurned         = "burned"
	StatusRevoked        = "revoked"
)

// Info is a collection's public record. The creator may edit the profile
// fields until FreezeProfile, hand the creator role over and seal the supply;
// everything else is immutable.
type Info struct {
	ID             string // "C<n>"
	GRC721ID       string
	Issuer         address // the only realm that mints into the collection
	Creator        address
	Originator     address // the creator at creation, whoever holds the role now
	PendingCreator address
	Name           string
	Symbol         string
	Description    string
	Image          string
	Banner         string
	Website        string
	Mode           string
	Revocable      bool  // soulbound only: the creator may revoke a token
	MaxSupply      int64 // zero means an uncapped open edition
	Sealed         bool  // no token can ever be minted again
	Minted         int64 // includes retired tokens; numbers are never reused
	ProfileFrozen  bool
}

type collection struct {
	key        string // tree key: fixed width, in creation order
	info       Info
	token      *grc721.Token
	ledger     *grc721.PrivateLedger
	metadata   metadata
	traitsRoot string    // Merkle root of the token traits, set once
	royalties  []royalty // at most maxRoyaltyReceivers
	royaltyBPS int64
	markets    []address // royalty-protected only, at most maxMarkets
	retired    avl.Tree  // token number -> StatusBurned | StatusRevoked
}

var (
	lastID      seqid.ID
	collections avl.Tree // collection key -> *collection
	holdings    avl.Tree // owner -> *avl.Tree of "<collection key>/<number key>" -> custody ID
	lastCustody seqid.ID // the last custody ID given
)

// isIssuer reports whether a realm may create collections and mint into its
// own: the drops realm always, and every realm on config's add-only list.
func isIssuer(who address) bool {
	return who == chain.PackageAddress(dropsPath) || config.IsIssuer(config.LedgerNFT, who)
}

// gate stops a new collection or a new mint while its lane is paused, so the
// pauser is a brake on every issuer config may add, whatever that issuer
// checks. The drops realm is not asked twice: it applies the same gate itself,
// with the currency it charges, before it calls here.
func gate(issuer address, lane string) {
	if issuer != chain.PackageAddress(dropsPath) && config.IsPaused(lane) {
		panic("launchpad/nft: lane paused")
	}
}

// callingRealm returns the realm that called; a wallet is refused.
func callingRealm(cur realm) address {
	if !cur.IsCurrent() || cur.Previous().IsUserCall() {
		panic("launchpad/nft: issuer realm only")
	}
	return cur.Previous().Address()
}

// actor returns the immediate caller. Coins a wallet attaches to a direct call
// would stay in this realm, so they are refused; a calling realm keeps whatever
// its own caller sent.
func actor(cur realm) address {
	if !cur.IsCurrent() {
		panic("launchpad/nft: stale realm context")
	}
	if cur.Previous().IsUserCall() {
		currency.AssertNoCoins(0, cur)
	}
	return cur.Previous().Address()
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

func checkProfile(description, image, banner, website string) {
	check(meta.Description(description))
	check(meta.Image(image))
	check(meta.Image(banner))
	check(meta.Website(website))
}

func mustCollection(id string) *collection {
	if len(id) >= 2 && len(id) <= 21 && id[0] == 'C' && id[1] != '0' {
		if n, err := strconv.ParseUint(id[1:], 10, 64); err == nil {
			if c := collections.Get(seqid.ID(n).String()); c != nil {
				return c.(*collection)
			}
		}
	}
	panic("launchpad/nft: unknown collection")
}

func tokenID(number int64) grc721.TokenID {
	if number <= 0 {
		panic("launchpad/nft: invalid token number")
	}
	return grc721.TokenID(strconv.FormatInt(number, 10))
}

func holdingKey(c *collection, number int64) string {
	return c.key + "/" + seqid.ID(number).String()
}

// hold and release keep the holdings index equal to ownership: one tree per
// owner, so a page of an account's tokens costs the same wherever it starts.
func hold(owner address, c *collection, number int64) {
	mine, _ := holdings.Get(owner.String()).(*avl.Tree)
	if mine == nil {
		mine = avl.NewTree()
		holdings.Set(owner.String(), mine)
	}
	mine.Set(holdingKey(c, number), int64(lastCustody.Next()))
}

// renew gives a held token a new custody ID, as a move does: a change of its
// single-token approval starts a new custody too.
func renew(owner address, c *collection, number int64) {
	holdings.Get(owner.String()).(*avl.Tree).Set(holdingKey(c, number), int64(lastCustody.Next()))
}

func release(owner address, c *collection, number int64) {
	mine := holdings.Get(owner.String()).(*avl.Tree)
	mine.Remove(holdingKey(c, number))
	if mine.Size() == 0 {
		holdings.Remove(owner.String())
	}
}

// Create registers a collection for a creator the calling issuer realm has
// authenticated and charged. The issuer is recorded on the collection and no
// other realm can mint into it. royalties is "address:bps;address:bps" with
// addresses in strictly ascending order, or empty; the metadata arguments are
// those of newMetadata.
func Create(cur realm, creator address, name, symbol, description, image,
	banner, website, mode string, revocable bool, maxSupply int64,
	metadataMode, baseURI, placeholderURI, commitment, provenance,
	royalties string) string {
	issuer := callingRealm(cur)
	if !isIssuer(issuer) {
		panic("launchpad/nft: issuer realm only")
	}
	gate(issuer, config.LaneCollection)
	if !meta.ValidAddress(creator) || maxSupply < 0 ||
		(mode != ModeOpen && mode != ModeRoyaltyProtected && mode != ModeSoulbound) ||
		(revocable && mode != ModeSoulbound) {
		panic("launchpad/nft: invalid collection terms")
	}
	check(meta.Name(name))
	check(meta.Ticker(symbol))
	if config.IsReserved(symbol) {
		panic("launchpad/nft: reserved symbol")
	}
	checkProfile(description, image, banner, website)
	c := &collection{metadata: newMetadata(metadataMode, baseURI, placeholderURI,
		commitment, provenance, creator)}
	c.royalties, c.royaltyBPS = parseRoyalties(royalties, mode)
	if mode == ModeRoyaltyProtected {
		c.markets = []address{chain.PackageAddress(marketPath)}
	}
	n := lastID.Next()
	id := "C" + strconv.FormatUint(uint64(n), 10)
	c.key = n.String()
	c.token, c.ledger = grc721.NewToken(name, symbol, n, cur)
	c.info = Info{
		ID: id, GRC721ID: c.token.ID(), Issuer: issuer, Creator: creator,
		Originator: creator, Name: name, Symbol: symbol, Description: description, Image: image,
		Banner: banner, Website: website, Mode: mode, Revocable: revocable,
		MaxSupply: maxSupply,
	}
	collections.Set(c.key, c)
	chain.Emit("CollectionCreated", "collection", id, "token", c.token.ID(),
		"issuer", issuer.String(), "creator", creator.String(),
		"name", name, "symbol", symbol, "mode", mode,
		"revocable", strconv.FormatBool(revocable),
		"max_supply", strconv.FormatInt(maxSupply, 10),
		"metadata", metadataMode, "base_uri", baseURI,
		"placeholder_uri", placeholderURI, "base_uri_commitment", commitment,
		"provenance", provenance, "royalties", royalties,
		"description", description, "image", image, "banner", banner,
		"website", website)
	return id
}

// MintTo issues the next token number. Only the collection's issuer calls it,
// after its own accounting of stages and payment. The ledger mints to whoever
// the issuer names: it is the issuer's duty to mint a soulbound token only to
// the wallet that asked for it.
func MintTo(cur realm, id string, recipient address) int64 {
	issuer := callingRealm(cur)
	c := mustCollection(id)
	if issuer != c.info.Issuer {
		panic("launchpad/nft: the collection's issuer only")
	}
	gate(issuer, config.LaneNFTDrops)
	if !meta.ValidAddress(recipient) || c.info.Sealed ||
		(c.info.MaxSupply > 0 && c.info.Minted >= c.info.MaxSupply) {
		panic("launchpad/nft: mint denied")
	}
	number := sm.Add(c.info.Minted, 1)
	check(c.ledger.Mint(recipient, tokenID(number)))
	c.info.Minted = number
	hold(recipient, c, number)
	return number
}

// operator reports whether who may be approved for, or move, a token of c.
// Soulbound tokens never move. A royalty-protected token moves only through a
// realm on the collection's market list. The ledger cannot make a realm pay:
// the creator who lists one vouches that it pays the collection's royalties.
func operator(c *collection, who address) bool {
	switch c.info.Mode {
	case ModeOpen:
		return true
	case ModeRoyaltyProtected:
		for _, market := range c.markets {
			if who == market {
				return true
			}
		}
	}
	return false
}

func denied(c *collection) {
	if c.info.Mode == ModeSoulbound {
		panic("launchpad/nft: soulbound tokens cannot move")
	}
	panic("launchpad/nft: royalty-protected tokens move only through an allowed market")
}

// TransferFrom moves a token when the collection's mode lets the caller move
// one, and the caller owns it or is approved for it.
func TransferFrom(cur realm, id string, from, to address, number int64) {
	who := actor(cur)
	c := mustCollection(id)
	if !operator(c, who) {
		denied(c)
	}
	if !meta.ValidAddress(to) {
		panic("launchpad/nft: invalid recipient")
	}
	check(c.ledger.TransferFrom(who, from, to, tokenID(number)))
	release(from, c, number)
	hold(to, c, number)
}

// Approve lets one account move one token; an empty address clears it. A
// soulbound token takes no approval at all, a royalty-protected one only a
// listed market.
func Approve(cur realm, id string, to address, number int64) {
	who := actor(cur)
	c := mustCollection(id)
	if c.info.Mode == ModeSoulbound || (to != "" && !operator(c, to)) {
		denied(c)
	}
	if to != "" && !meta.ValidAddress(to) {
		panic("launchpad/nft: invalid operator")
	}
	before := GetApproved(id, number)
	check(c.ledger.Approve(who, to, tokenID(number)))
	if to != before {
		renew(ownerOf(c, number), c, number)
	}
}

// SetApprovalForAll lets, or stops letting, one account move every token the
// caller holds in the collection.
func SetApprovalForAll(cur realm, id string, to address, approved bool) {
	who := actor(cur)
	c := mustCollection(id)
	if !operator(c, to) {
		denied(c)
	}
	if !meta.ValidAddress(to) {
		panic("launchpad/nft: invalid operator")
	}
	check(c.ledger.SetApprovalForAll(who, to, approved))
}

func ownerOf(c *collection, number int64) address {
	owner, err := c.token.OwnerOf(tokenID(number))
	check(err)
	return owner
}

func retire(c *collection, owner address, number int64, status string) {
	tid := tokenID(number)
	check(c.ledger.Burn(tid))
	c.retired.Set(tid.String(), status)
	release(owner, c, number)
}

// Burn is the holder's alone, in every mode. No creator, operator or admin
// can destroy a token somebody else holds, except through Revoke.
func Burn(cur realm, id string, number int64) {
	who := actor(cur)
	c := mustCollection(id)
	if who != ownerOf(c, number) {
		panic("launchpad/nft: holder only")
	}
	retire(c, who, number, StatusBurned)
}

// Revoke retires a credential. It exists only for soulbound collections
// created as revocable, a term every holder could read before claiming. A
// holder who burns first leaves a burned token, not a revoked one.
func Revoke(cur realm, id string, number int64, reason string) {
	c := creatorOf(cur, id)
	if c.info.Mode != ModeSoulbound || !c.info.Revocable {
		panic("launchpad/nft: not a revocable collection")
	}
	switch reason {
	case "expired", "fraud", "eligibility_lost", "issuer_error", "other":
	default:
		panic("launchpad/nft: invalid revocation reason")
	}
	holder := ownerOf(c, number)
	retire(c, holder, number, StatusRevoked)
	chain.Emit("Revoked", "collection", id,
		"number", strconv.FormatInt(number, 10), "holder", holder.String(),
		"reason", reason)
}

// creatorOf returns the collection when the caller is its creator.
func creatorOf(cur realm, id string) *collection {
	who := actor(cur)
	c := mustCollection(id)
	if who != c.info.Creator {
		panic("launchpad/nft: creator only")
	}
	return c
}

// ProposeCreator starts handing the creator role to another account. Nothing
// changes until that account accepts; an empty address withdraws the offer.
func ProposeCreator(cur realm, id string, next address) {
	c := creatorOf(cur, id)
	if next != "" && (!meta.ValidAddress(next) || next == c.info.Creator) {
		panic("launchpad/nft: invalid next creator")
	}
	c.info.PendingCreator = next
	chain.Emit("CreatorProposed", "collection", id, "next", next.String())
}

// AcceptCreator makes the caller the creator it was proposed as.
func AcceptCreator(cur realm, id string) {
	who := actor(cur)
	c := mustCollection(id)
	if c.info.PendingCreator == "" || who != c.info.PendingCreator {
		panic("launchpad/nft: proposed creator only")
	}
	c.info.Creator, c.info.PendingCreator = who, ""
	chain.Emit("CreatorChanged", "collection", id, "creator", who.String())
}

// SetIssuer moves the collection's minting to another issuer realm, for
// instance a later version of the one that created it. Only the creator can
// choose it, and only among realms allowed to issue.
func SetIssuer(cur realm, id, pkgPath string) {
	c := creatorOf(cur, id)
	if len(pkgPath) < 12 || len(pkgPath) > 200 || pkgPath[:11] != "gno.land/r/" {
		panic("launchpad/nft: invalid issuer")
	}
	next := chain.PackageAddress(pkgPath)
	if !isIssuer(next) || next == c.info.Issuer {
		panic("launchpad/nft: invalid issuer")
	}
	c.info.Issuer = next
	chain.Emit("IssuerChanged", "collection", id, "issuer", next.String(),
		"path", pkgPath)
}

// SealSupply ends minting for good, whatever the cap was.
func SealSupply(cur realm, id string) {
	c := creatorOf(cur, id)
	if c.info.Sealed {
		panic("launchpad/nft: supply already sealed")
	}
	c.info.Sealed = true
	chain.Emit("SupplySealed", "collection", id,
		"minted", strconv.FormatInt(c.info.Minted, 10))
}

func profileOwner(cur realm, id string) *collection {
	c := creatorOf(cur, id)
	if c.info.ProfileFrozen {
		panic("launchpad/nft: profile frozen")
	}
	return c
}

func SetProfile(cur realm, id, description, image, banner, website string) {
	c := profileOwner(cur, id)
	checkProfile(description, image, banner, website)
	c.info.Description, c.info.Image = description, image
	c.info.Banner, c.info.Website = banner, website
	chain.Emit("ProfileChanged", "collection", id, "description", description,
		"image", image, "banner", banner, "website", website)
}

func FreezeProfile(cur realm, id string) {
	profileOwner(cur, id).info.ProfileFrozen = true
	chain.Emit("ProfileFrozen", "collection", id)
}

func GetInfo(id string) Info { return mustCollection(id).info }
func Count() int64           { return int64(collections.Size()) }

func BalanceOf(id string, owner address) int64 {
	if !meta.ValidAddress(owner) {
		panic("launchpad/nft: invalid owner")
	}
	n, err := mustCollection(id).token.BalanceOf(owner)
	check(err)
	return n
}

func OwnerOf(id string, number int64) address { return ownerOf(mustCollection(id), number) }

func TotalSupply(id string) int64 { return mustCollection(id).token.TotalSupply() }

// GetApproved returns the empty address when nobody is approved.
func GetApproved(id string, number int64) address {
	a, err := mustCollection(id).token.GetApproved(tokenID(number))
	if err == grc721.ErrTokenIdNotApproved {
		return ""
	}
	check(err)
	return a
}

func IsApprovedForAll(id string, owner, operator address) bool {
	if !meta.ValidAddress(owner) {
		panic("launchpad/nft: invalid owner")
	}
	if !meta.ValidAddress(operator) {
		panic("launchpad/nft: invalid operator")
	}
	return mustCollection(id).token.IsApprovedForAll(owner, operator)
}

func statusOf(c *collection, number int64) string {
	if number <= 0 || number > c.info.Minted {
		panic("launchpad/nft: invalid token number")
	}
	if status := c.retired.Get(strconv.FormatInt(number, 10)); status != nil {
		return status.(string)
	}
	return StatusActive
}

// Epoch returns the ID of a token's current custody: a new one at every move
// and every change of its single-token approval (the same approval again
// changes nothing), never one given before; 0 for a retired token. A market
// binds an order to it, so the order dies with the custody it was made under.
func Epoch(id string, number int64) int64 {
	c := mustCollection(id)
	if statusOf(c, number) != StatusActive {
		return 0
	}
	return holdings.Get(ownerOf(c, number).String()).(*avl.Tree).Get(holdingKey(c, number)).(int64)
}

func StatusOf(id string, number int64) string { return statusOf(mustCollection(id), number) }

// TokenURI answers for every minted number, retired or not: the metadata of a
// burned token is still part of the collection's public record.
func TokenURI(id string, number int64) string {
	c := mustCollection(id)
	statusOf(c, number)
	return c.metadata.tokenURI(number)
}

func Render(path string) string {
	if path == "" {
		return "# Launchpad NFT collections\n\n" +
			strconv.Itoa(collections.Size()) + " collections.\n"
	}
	c := mustCollection(path)
	return "# " + meta.EscapeMarkdown(c.info.Name) + "\n\n" +
		"Mode: " + c.info.Mode + "\n\n" +
		"Minted: " + strconv.FormatInt(c.info.Minted, 10) + "\n"
}

package nft

import (
	"chain"
	"strings"

	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
)

// Hard limits, fixed for the life of this realm.
const (
	maxRoyaltyReceivers = 10
	maxRoyaltyBPS       = 1000 // 10% of a sale, across all receivers
	maxMarkets          = 5
)

// royalty is one receiver's share of every sale, in basis points.
type royalty struct {
	Account address
	BPS     int64
}

type RoyaltyPayout struct {
	Account address
	Amount  int64
}

// parseBPS reads a positive decimal with no sign, space or leading zero.
func parseBPS(s string) int64 {
	if s == "" || len(s) > 4 || s[0] == '0' {
		panic("launchpad/nft: invalid royalty share")
	}
	var n int64
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			panic("launchpad/nft: invalid royalty share")
		}
		n = n*10 + int64(s[i]-'0')
	}
	return n
}

// parseRoyalties reads "address:bps;address:bps". Strictly ascending addresses
// give every split exactly one encoding and rule out duplicates.
func parseRoyalties(encoded, mode string) ([]royalty, int64) {
	if encoded == "" {
		if mode == ModeRoyaltyProtected {
			panic("launchpad/nft: a royalty-protected collection needs royalties")
		}
		return nil, 0
	}
	if mode == ModeSoulbound {
		panic("launchpad/nft: soulbound tokens are never sold")
	}
	records := strings.Split(encoded, ";")
	if len(records) > maxRoyaltyReceivers {
		panic("launchpad/nft: too many royalty receivers")
	}
	out := make([]royalty, 0, len(records))
	previous := ""
	var total int64
	for _, record := range records {
		fields := strings.Split(record, ":")
		if len(fields) != 2 || fields[0] <= previous {
			panic("launchpad/nft: invalid royalty list")
		}
		who := address(fields[0])
		// Unspendable covers every text but the chain's spelling of an account.
		if config.IsUnspendable(who) {
			panic("launchpad/nft: invalid royalty receiver")
		}
		bps := parseBPS(fields[1])
		if total = sm.Add(total, bps); total > maxRoyaltyBPS {
			panic("launchpad/nft: royalties exceed 10%")
		}
		out = append(out, royalty{Account: who, BPS: bps})
		previous = fields[0]
	}
	return out, total
}

// validName is the chain's rule for one segment of a package path: a letter
// first, then letters and digits, joined by single "_" or "-".
func validName(s string) bool {
	if s == "" || s[0] < 'a' || s[0] > 'z' {
		return false
	}
	joined := false // the previous character joins two runs
	for i := 1; i < len(s); i++ {
		switch c := s[i]; {
		case (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'):
			joined = false
		case (c == '_' || c == '-') && !joined:
			joined = true
		default:
			return false
		}
	}
	return !joined
}

// A market may be any realm the chain can host, a third party's included, so
// its path follows the chain's own rule for a realm path: "gno.land/r/", then
// names separated by "/", none ending in "_test", in at most 200 bytes. A slot
// is permanent: none is given to a path no realm can have. The rule for
// issuers is config's and is narrower (plain segments in our own namespace):
// an issuer is one of ours, a market need not be.
func validMarketPath(path string) bool {
	if len(path) > 200 || !strings.HasPrefix(path, "gno.land/r/") || strings.HasSuffix(path, "_test") {
		return false
	}
	for _, name := range strings.Split(path[len("gno.land/r/"):], "/") {
		if !validName(name) {
			return false
		}
	}
	return true
}

func RoyaltyBPS(id string) int64 { return mustCollection(id).royaltyBPS }

// RoyaltyQuote floors each receiver's share of price. The seller keeps the
// rounding remainder.
func RoyaltyQuote(id string, price int64) []RoyaltyPayout {
	royalties := mustCollection(id).royalties
	out := make([]RoyaltyPayout, len(royalties))
	for i, r := range royalties {
		out[i] = RoyaltyPayout{Account: r.Account, Amount: sm.BPS(price, r.BPS)}
	}
	return out
}

// AllowMarket adds a realm through which a royalty-protected collection's
// tokens may be sold. The list starts with the Launchpad market and only
// grows: a holder's way out can be widened, never taken away. The ledger
// cannot make a realm pay: the creator vouches that the market it lists pays
// this collection's royalties, and every holder can read the list.
func AllowMarket(cur realm, id, pkgPath string) {
	c := creatorOf(cur, id)
	if c.info.Mode != ModeRoyaltyProtected || !validMarketPath(pkgPath) ||
		len(c.markets) >= maxMarkets ||
		operator(c, chain.PackageAddress(pkgPath)) {
		panic("launchpad/nft: market cannot be added")
	}
	market := chain.PackageAddress(pkgPath)
	c.markets = append(c.markets, market)
	chain.Emit("MarketAllowed", "collection", id, "market", pkgPath,
		"address", market.String())
}

package nft

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/meta/v1"
)

// Lists are paged: a zero-based page of 1 to maxPage entries.
const maxPage = 50

// int64 values are decimal strings so a JSON client cannot round them.
func num(n int64) string { return meta.JSONString(strconv.FormatInt(n, 10)) }

// listJSON renders one page of a tree in key order. The tree seeks the first
// entry by subtree sizes, so a deep page costs what the first one does.
func listJSON(tree *avl.Tree, page, size int64, render func(key string, value any) string) string {
	if page < 0 || size < 1 || size > maxPage {
		panic("launchpad/nft: invalid page")
	}
	var b strings.Builder
	b.WriteByte('[')
	// A page past the end cannot overflow: nothing is multiplied before this.
	if tree != nil && page <= int64(tree.Size())/size {
		tree.IterateByOffset(int(page*size), int(size), func(key string, value any) bool {
			if b.Len() > 1 {
				b.WriteByte(',')
			}
			b.WriteString(render(key, value))
			return false
		})
	}
	b.WriteByte(']')
	return b.String()
}

func CollectionJSON(id string) string {
	c := mustCollection(id)
	i := c.info
	return "{" +
		`"id":` + meta.JSONString(i.ID) +
		`,"grc721Id":` + meta.JSONString(i.GRC721ID) +
		`,"issuer":` + meta.JSONString(i.Issuer.String()) +
		`,"creator":` + meta.JSONString(i.Creator.String()) +
		`,"originator":` + meta.JSONString(i.Originator.String()) +
		`,"pendingCreator":` + meta.JSONString(i.PendingCreator.String()) +
		`,"name":` + meta.JSONString(i.Name) +
		`,"symbol":` + meta.JSONString(i.Symbol) +
		`,"description":` + meta.JSONString(i.Description) +
		`,"image":` + meta.JSONString(i.Image) +
		`,"banner":` + meta.JSONString(i.Banner) +
		`,"website":` + meta.JSONString(i.Website) +
		`,"mode":` + meta.JSONString(i.Mode) +
		`,"revocable":` + strconv.FormatBool(i.Revocable) +
		`,"maxSupply":` + num(i.MaxSupply) +
		`,"sealed":` + strconv.FormatBool(i.Sealed) +
		`,"minted":` + num(i.Minted) +
		`,"totalSupply":` + num(c.token.TotalSupply()) +
		`,"profileFrozen":` + strconv.FormatBool(i.ProfileFrozen) +
		`,"metadataMode":` + meta.JSONString(c.metadata.mode) +
		`,"metadataFrozen":` + strconv.FormatBool(c.metadata.frozen) +
		`,"metadataRevision":` + num(c.metadata.revision) +
		`,"baseURI":` + meta.JSONString(c.metadata.baseURI) +
		`,"placeholderURI":` + meta.JSONString(c.metadata.placeholderURI) +
		`,"baseURICommitment":` + meta.JSONString(c.metadata.commitment) +
		`,"committer":` + meta.JSONString(c.metadata.committer.String()) +
		`,"provenanceHash":` + meta.JSONString(c.metadata.provenance) +
		`,"traitsRoot":` + meta.JSONString(c.traitsRoot) +
		`,"royaltyBPS":` + num(c.royaltyBPS) +
		`,"royalties":` + royaltiesJSON(c.royalties) +
		`,"markets":` + addressesJSON(c.markets) + "}"
}

func royaltiesJSON(royalties []royalty) string {
	var b strings.Builder
	b.WriteByte('[')
	for i, r := range royalties {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"account":` + meta.JSONString(r.Account.String()) +
			`,"bps":` + num(r.BPS) + "}")
	}
	b.WriteByte(']')
	return b.String()
}

func addressesJSON(list []address) string {
	var b strings.Builder
	b.WriteByte('[')
	for i, a := range list {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(meta.JSONString(a.String()))
	}
	b.WriteByte(']')
	return b.String()
}

// CapabilitiesJSON tells a wallet or a market what a holder of this
// collection can do, without it knowing the modes. "markets" is empty when
// any operator may be approved. Royalties are paid by markets at sale.
// "royaltyEnforcement" is "none" without royalties; "market_sales" for an open
// collection, where the ledger enforces nothing: a market that honours
// royalties pays them at a sale, and a direct transfer or any other realm
// pays none; "listed_markets" when the ledger lets a token move only through
// the realms in "markets". Whether a listed realm pays is the word of the
// creator who listed it. "creatorRevoke" is the creator's right to revoke
// a token of a revocable soulbound collection.
func CapabilitiesJSON(id string) string {
	c := mustCollection(id)
	i := c.info
	enforcement := "none"
	if c.royaltyBPS > 0 {
		enforcement = "market_sales"
		if i.Mode == ModeRoyaltyProtected {
			enforcement = "listed_markets"
		}
	}
	return "{" +
		`"schema":"launchpad-nft-capabilities/v1"` +
		`,"collection":` + meta.JSONString(id) +
		`,"standard":"grc721"` +
		`,"mode":` + meta.JSONString(i.Mode) +
		`,"holderTransfer":` + strconv.FormatBool(i.Mode == ModeOpen) +
		`,"marketSale":` + strconv.FormatBool(i.Mode != ModeSoulbound) +
		`,"markets":` + addressesJSON(c.markets) +
		`,"holderBurn":true` +
		`,"creatorRevoke":` + strconv.FormatBool(i.Revocable) +
		`,"maxSupply":` + num(i.MaxSupply) +
		`,"metadataMode":` + meta.JSONString(c.metadata.mode) +
		`,"metadataFrozen":` + strconv.FormatBool(c.metadata.frozen) +
		`,"traitsCommitted":` + strconv.FormatBool(c.traitsRoot != "") +
		`,"royaltyBPS":` + num(c.royaltyBPS) +
		`,"royaltyEnforcement":` + meta.JSONString(enforcement) + "}"
}

// ListCollectionsJSON pages through a summary of every collection, in
// creation order. CollectionJSON has the full record.
func ListCollectionsJSON(page, size int64) string {
	return listJSON(&collections, page, size, func(_ string, value any) string {
		i := value.(*collection).info
		return "{" +
			`"id":` + meta.JSONString(i.ID) +
			`,"creator":` + meta.JSONString(i.Creator.String()) +
			`,"name":` + meta.JSONString(i.Name) +
			`,"symbol":` + meta.JSONString(i.Symbol) +
			`,"image":` + meta.JSONString(i.Image) +
			`,"mode":` + meta.JSONString(i.Mode) +
			`,"maxSupply":` + num(i.MaxSupply) +
			`,"sealed":` + strconv.FormatBool(i.Sealed) +
			`,"minted":` + num(i.Minted) + "}"
	})
}

func tokenJSON(c *collection, number int64) string {
	status := statusOf(c, number)
	var owner address
	if status == StatusActive {
		owner = ownerOf(c, number)
	}
	return "{" +
		`"collection":` + meta.JSONString(c.info.ID) +
		`,"number":` + num(number) +
		`,"owner":` + meta.JSONString(owner.String()) +
		`,"status":` + meta.JSONString(status) +
		`,"uri":` + meta.JSONString(c.metadata.tokenURI(number)) + "}"
}

// TokenJSON describes one minted number. A retired token has no owner.
func TokenJSON(id string, number int64) string { return tokenJSON(mustCollection(id), number) }

// ApprovalJSON answers, in one read, whether operator may move an active
// token: by a single-token approval or by the owner's collection-wide one.
func ApprovalJSON(id string, number int64, operator string) string {
	c := mustCollection(id)
	owner := ownerOf(c, number)
	who := address(operator)
	if !meta.ValidAddress(who) {
		panic("launchpad/nft: invalid operator")
	}
	return "{" +
		`"collection":` + meta.JSONString(id) +
		`,"number":` + num(number) +
		`,"owner":` + meta.JSONString(owner.String()) +
		`,"operator":` + meta.JSONString(operator) +
		`,"tokenApproved":` + strconv.FormatBool(GetApproved(id, number) == who) +
		`,"collectionApproved":` + strconv.FormatBool(c.token.IsApprovedForAll(owner, who)) + "}"
}

// TokensJSON pages through a collection's minted numbers in order, retired
// ones included.
func TokensJSON(id string, page, size int64) string {
	if page < 0 || size < 1 || size > maxPage {
		panic("launchpad/nft: invalid page")
	}
	c := mustCollection(id)
	var b strings.Builder
	b.WriteByte('[')
	if page <= c.info.Minted/size {
		for number := page*size + 1; number <= c.info.Minted && size > 0; number, size = number+1, size-1 {
			if b.Len() > 1 {
				b.WriteByte(',')
			}
			b.WriteString(tokenJSON(c, number))
		}
	}
	b.WriteByte(']')
	return b.String()
}

// HoldingsJSON pages through the tokens an account holds, across every
// collection, in collection then number order.
func HoldingsJSON(owner string, page, size int64) string {
	if !meta.ValidAddress(address(owner)) {
		panic("launchpad/nft: invalid owner")
	}
	mine, _ := holdings.Get(owner).(*avl.Tree)
	return listJSON(mine, page, size, func(key string, _ any) string {
		parts := strings.Split(key, "/")
		c := collections.Get(parts[0]).(*collection)
		number, _ := seqid.FromString(parts[1])
		return "{" +
			`"collection":` + meta.JSONString(c.info.ID) +
			`,"number":` + num(int64(number)) +
			`,"uri":` + meta.JSONString(c.metadata.tokenURI(int64(number))) + "}"
	})
}

// Package tokens creates registered Launchpad GRC20 ledgers for the issuer
// realms listed in config. A token belongs to the issuer that created it: no
// other realm, and no admin, can mint into it.
package tokens

import (
	"chain"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/samcrew/launchpad/config/v1"
)

const (
	ModeDirectFixed = "direct_fixed"
	ModeDirectCap   = "direct_capped"
	ModeFairSale    = "fairsale"
	maxPublicID     = 9_999_999_999 // T plus ten decimal digits: GRC20 MaxSymbolLen is 11.
)

// Metadata is editable only by the original creator until frozen.
type Metadata struct {
	Description string
	Image       string
	Website     string
	XHandle     string
	Telegram    string
}

// createSpec is assembled within this realm: a foreign Gno realm cannot
// allocate a struct declared here, so the crossing interface uses scalars.
type createSpec struct {
	Creator         address
	Mode            string
	Name            string
	Ticker          string
	Decimals        int
	InitialSupply   int64
	MaxSupply       int64
	CurrencyKey     string
	ExpectedVersion int64
	Metadata        Metadata
}

// Info excludes the private ledger capability and can be returned safely.
type Info struct {
	ID              string
	RegistryKey     string
	GRC20ID         string
	Issuer          address
	Creator         address
	Mode            string
	Name            string
	Ticker          string
	Decimals        int
	InitialSupply   int64
	MaxSupply       int64
	ConfigVersion   int64
	CurrencyKey     string
	Metadata        Metadata
	MetadataFrozen  bool
	MintAuthority   address
	PendingMintAuth address
	MintRenounced   bool
}

type entry struct {
	info   Info
	token  *grc20.Token
	ledger *grc20.PrivateLedger
}

// Tokens live in an AVL tree: creating one touches its own entry and the path
// to it, whatever the number of tokens. A Go map, or a slice of their ids,
// would be rewritten whole on every creation. Ids are T1, T2, ... in creation
// order and no token is ever removed, so a page of the list is a range of ids.
var (
	nextID  seqid.ID
	entries = avl.NewTree() // token id -> *entry
)

// requireIssuer returns the immediate caller, which config must list as a
// token issuer. Only a realm's own address is ever listed, so an account or a
// script never passes.
func requireIssuer(cur realm) address {
	if !cur.IsCurrent() {
		panic("launchpad/tokens: stale realm context")
	}
	issuer := cur.Previous().Address()
	if !config.IsIssuer(config.LedgerTokens, issuer) {
		panic("launchpad/tokens: token issuer only")
	}
	return issuer
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// caller is the immediate user or realm. Coins a user attaches to a direct
// call would land in this realm, which has no way to return them.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("launchpad/tokens: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	return cur.Previous().Address()
}

// The ledger keys balances and allowances by the address text, so an address
// in any spelling but the one the chain gives a caller would hold something
// no caller can reach.
func requireAddress(a address) {
	if !meta.ValidAddress(a) {
		panic("launchpad/tokens: invalid address")
	}
}

func validateMetadata(m Metadata) {
	check(meta.Description(m.Description))
	check(meta.Image(m.Image))
	check(meta.Website(m.Website))
	check(meta.Handle(m.XHandle))
	check(meta.Handle(m.Telegram))
}

// The founding names remain unavailable even if governance globally clears a
// config reservation. A creator-specific grant needs its own reviewed proof.
func protectedTicker(ticker string) bool {
	switch ticker {
	case "MEMBA", "GNOT", "UGNOT", "WUGNOT", "GNS", "USDC", "USDT", "ATOM", "BTC", "ETH", "SAMCREW":
		return true
	}
	return false
}

func validateSpec(s createSpec) {
	requireAddress(s.Creator)
	check(meta.Name(s.Name))
	check(meta.Ticker(s.Ticker))
	validateMetadata(s.Metadata)
	if s.Decimals < 0 || s.Decimals > grc20.MaxDecimals ||
		s.InitialSupply <= 0 || s.MaxSupply < s.InitialSupply ||
		protectedTicker(s.Ticker) || config.IsReserved(s.Ticker) {
		panic("launchpad/tokens: invalid launch terms")
	}
	switch s.Mode {
	case ModeFairSale:
		if s.Decimals > 12 || s.MaxSupply != s.InitialSupply {
			panic("launchpad/tokens: invalid fair-sale terms")
		}
	case ModeDirectFixed:
		if s.Decimals > 12 || s.MaxSupply != s.InitialSupply {
			panic("launchpad/tokens: invalid direct terms")
		}
	case ModeDirectCap:
		if s.Decimals > 12 || s.MaxSupply <= s.InitialSupply {
			panic("launchpad/tokens: invalid capped terms")
		}
	default:
		panic("launchpad/tokens: invalid mode")
	}
}

func laneForMode(mode string) string {
	switch mode {
	case ModeDirectFixed, ModeDirectCap:
		return config.LaneDirect
	case ModeFairSale:
		return config.LaneFairSale
	}
	panic("launchpad/tokens: invalid mode")
}

func nextPublicID() (string, seqid.ID) {
	if uint64(nextID) >= maxPublicID {
		panic("launchpad/tokens: token ID exhausted")
	}
	idNumber := nextID.Next()
	return "T" + strconv.FormatUint(uint64(idNumber), 10), idNumber
}

// Create registers exactly one new GRC20 for a listed issuer, which must
// authenticate the creator, reserve the launch terms and collect payment
// before this crossing call. The currency key names the config action
// currency: creation-fee currency for a direct token, quote currency for a
// fair sale; the issuer binds it to the corresponding payment route. The
// public symbol T<n> is distinct from the nonunique creator-selected ticker.
// The whole initial mint lands in the issuer's custody for atomic allocation
// and escrow setup, and the token stays bound to that issuer.
func Create(cur realm, creator address, mode, name, ticker string,
	decimals int, initialSupply, maxSupply int64,
	currencyKey string, expectedVersion int64,
	description, image, website, xHandle, telegram string) string {
	issuer := requireIssuer(cur)
	s := createSpec{
		Creator: creator, Mode: mode, Name: name, Ticker: ticker,
		Decimals: decimals, InitialSupply: initialSupply, MaxSupply: maxSupply,
		CurrencyKey: currencyKey,
		ExpectedVersion: expectedVersion,
		Metadata: Metadata{
			Description: description, Image: image, Website: website,
			XHandle: xHandle, Telegram: telegram,
		},
	}
	validateSpec(s)
	config.AssertNewAction(laneForMode(s.Mode), s.CurrencyKey, s.ExpectedVersion)
	id, idNumber := nextPublicID()
	token, ledger := grc20.NewToken(s.Name, id, s.Decimals, idNumber, cur)
	check(ledger.Mint(issuer, s.InitialSupply))
	registryKey := grc20reg.Register(cross(cur), token, id)
	info := Info{
		ID: id, RegistryKey: registryKey, GRC20ID: token.ID(),
		Issuer: issuer, Creator: s.Creator,
		Mode: s.Mode, Name: s.Name, Ticker: s.Ticker, Decimals: s.Decimals,
		InitialSupply: s.InitialSupply, MaxSupply: s.MaxSupply,
		ConfigVersion: s.ExpectedVersion, CurrencyKey: s.CurrencyKey,
		Metadata: s.Metadata,
	}
	if s.Mode == ModeDirectCap {
		info.MintAuthority = s.Creator
	}
	entries.Set(id, &entry{info: info, token: token, ledger: ledger})
	chain.Emit("LaunchpadTokenCreated", "id", id, "registry_key", registryKey,
		"grc20_id", token.ID(), "issuer", issuer.String(),
		"creator", s.Creator.String(),
		"mode", s.Mode, "ticker", s.Ticker, "currency_key", s.CurrencyKey)
	return id
}

func mustEntry(id string) *entry {
	e, ok := entries.Get(id).(*entry)
	if !ok || e.info.ID != id {
		panic("launchpad/tokens: unknown token")
	}
	return e
}

func GetInfo(id string) Info { return mustEntry(id).info }

// Count is the number of tokens created: ids are T1 to T<Count>, none removed.
func Count() int64 { return int64(nextID) }

func RegistryKeyOf(id string) string { return mustEntry(id).info.RegistryKey }

func BalanceOf(id string, owner address) int64 {
	requireAddress(owner)
	return mustEntry(id).token.BalanceOf(owner)
}

func TotalSupply(id string) int64 { return mustEntry(id).token.TotalSupply() }

// MintCapped can only be reached through the issuer that created the token.
// That issuer authenticates the live caller as the current mint authority
// and must partition the newly minted balance into recorded allocations in
// this same transaction. The ledger independently rechecks the authority and
// the immutable cap, and takes no mint while the direct lane is closed: the
// pauser stops every issuer here, whatever each one checks by itself.
func MintCapped(cur realm, id string, authority address, amount int64) {
	issuer := requireIssuer(cur)
	e := mustEntry(id)
	config.AssertLaneOpen(config.LaneDirect, e.info.CurrencyKey)
	if e.info.Issuer != issuer || e.info.Mode != ModeDirectCap || e.info.MintRenounced ||
		e.info.MintAuthority != authority || amount <= 0 ||
		sm.Add(e.token.TotalSupply(), amount) > e.info.MaxSupply {
		panic("launchpad/tokens: capped mint denied")
	}
	check(e.ledger.Mint(issuer, amount))
	chain.Emit("LaunchpadTokenCappedMinted", "id", id,
		"authority", authority.String(), "amount", strconv.FormatInt(amount, 10))
}

func Allowance(id string, owner, spender address) int64 {
	requireAddress(owner)
	requireAddress(spender)
	return mustEntry(id).token.Allowance(owner, spender)
}

// Standard wrappers operate only on the immediate caller's balance or
// allowance, accept no coins, and take an address only as the chain writes
// one. A realm can also move its own balance, or an allowance it holds,
// through the token in the registry, where the GRC20 library alone checks the
// receiver. A script an account runs is such a realm with the account's
// address, so these wrappers are an account's only way in only while the
// chain does not let that account submit scripts.
func Transfer(cur realm, id string, to address, amount int64) {
	caller(cur)
	requireAddress(to)
	check(mustEntry(id).ledger.CallerTeller().Transfer(0, cur, to, amount))
}

func Approve(cur realm, id string, spender address, amount int64) {
	caller(cur)
	requireAddress(spender)
	check(mustEntry(id).ledger.CallerTeller().Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, id string, from, to address, amount int64) {
	caller(cur)
	requireAddress(from)
	requireAddress(to)
	check(mustEntry(id).ledger.CallerTeller().TransferFrom(0, cur, from, to, amount))
}

func Burn(cur realm, id string, amount int64) {
	who := caller(cur)
	if amount <= 0 {
		panic("launchpad/tokens: invalid burn")
	}
	check(mustEntry(id).ledger.Burn(who, amount))
}

func SetMetadata(cur realm, id, description, image, website, xHandle, telegram string) {
	who := caller(cur)
	e := mustEntry(id)
	if e.info.MetadataFrozen || who != e.info.Creator {
		panic("launchpad/tokens: creator metadata only")
	}
	m := Metadata{
		Description: description, Image: image, Website: website,
		XHandle: xHandle, Telegram: telegram,
	}
	validateMetadata(m)
	e.info.Metadata = m
	chain.Emit("TokenMetadataChanged", "id", id, "creator", e.info.Creator.String())
}

func FreezeMetadata(cur realm, id string) {
	who := caller(cur)
	e := mustEntry(id)
	if e.info.MetadataFrozen || who != e.info.Creator {
		panic("launchpad/tokens: creator metadata only")
	}
	e.info.MetadataFrozen = true
	chain.Emit("TokenMetadataFrozen", "id", id, "creator", e.info.Creator.String())
}

// A capped token's authority moves only through its own two-step handoff.
// The issuer checks this live authority before each later mint.
func ProposeMintAuthority(cur realm, id string, next address) {
	who := caller(cur)
	e := mustEntry(id)
	if e.info.Mode != ModeDirectCap || e.info.MintRenounced ||
		who != e.info.MintAuthority ||
		!meta.ValidAddress(next) || next == e.info.MintAuthority {
		panic("launchpad/tokens: mint authority only")
	}
	e.info.PendingMintAuth = next
	chain.Emit("MintAuthorityProposed", "id", id, "next", next.String())
}

func CancelMintAuthority(cur realm, id string) {
	who := caller(cur)
	e := mustEntry(id)
	if e.info.Mode != ModeDirectCap || e.info.MintRenounced ||
		who != e.info.MintAuthority || e.info.PendingMintAuth == "" {
		panic("launchpad/tokens: no mint authority proposal")
	}
	e.info.PendingMintAuth = ""
	chain.Emit("MintAuthorityCancelled", "id", id)
}

func AcceptMintAuthority(cur realm, id string) {
	who := caller(cur)
	e := mustEntry(id)
	if e.info.Mode != ModeDirectCap || e.info.MintRenounced ||
		e.info.PendingMintAuth == "" || who != e.info.PendingMintAuth {
		panic("launchpad/tokens: pending mint authority only")
	}
	e.info.MintAuthority = who
	e.info.PendingMintAuth = ""
	chain.Emit("MintAuthorityAccepted", "id", id, "authority", who.String())
}

func RenounceMintAuthority(cur realm, id string) {
	who := caller(cur)
	e := mustEntry(id)
	if e.info.Mode != ModeDirectCap || e.info.MintRenounced ||
		who != e.info.MintAuthority {
		panic("launchpad/tokens: mint authority only")
	}
	e.info.MintAuthority = ""
	e.info.PendingMintAuth = ""
	e.info.MintRenounced = true
	chain.Emit("MintAuthorityRenounced", "id", id)
}

func Render(path string) string {
	if path == "" {
		return "# Launchpad tokens\n\nRegistered GRC20 ledgers created by the issuers listed in config.\n"
	}
	e := mustEntry(path)
	return "# " + meta.EscapeMarkdown(e.info.Name) + "\n\nTicker: " +
		meta.EscapeMarkdown(e.info.Ticker) + "\n"
}

package tokens

import (
	"strconv"
	"strings"

	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
)

// int64 amounts and versions are decimal strings so JSON clients cannot round
// a valid value above JavaScript's exact integer range.
func infoJSON(e *entry) string {
	i := e.info
	return "{" +
		`"id":` + meta.JSONString(i.ID) +
		`,"registryKey":` + meta.JSONString(i.RegistryKey) +
		`,"grc20Id":` + meta.JSONString(i.GRC20ID) +
		`,"issuer":` + meta.JSONString(i.Issuer.String()) +
		`,"creator":` + meta.JSONString(i.Creator.String()) +
		`,"mode":` + meta.JSONString(i.Mode) +
		`,"name":` + meta.JSONString(i.Name) +
		`,"ticker":` + meta.JSONString(i.Ticker) +
		`,"decimals":` + strconv.Itoa(i.Decimals) +
		`,"initialSupply":` + meta.JSONString(strconv.FormatInt(i.InitialSupply, 10)) +
		`,"maxSupply":` + meta.JSONString(strconv.FormatInt(i.MaxSupply, 10)) +
		`,"totalSupply":` + meta.JSONString(strconv.FormatInt(e.token.TotalSupply(), 10)) +
		`,"configVersion":` + meta.JSONString(strconv.FormatInt(i.ConfigVersion, 10)) +
		`,"currencyKey":` + meta.JSONString(i.CurrencyKey) +
		`,"description":` + meta.JSONString(i.Metadata.Description) +
		`,"image":` + meta.JSONString(i.Metadata.Image) +
		`,"website":` + meta.JSONString(i.Metadata.Website) +
		`,"xHandle":` + meta.JSONString(i.Metadata.XHandle) +
		`,"telegram":` + meta.JSONString(i.Metadata.Telegram) +
		`,"metadataFrozen":` + strconv.FormatBool(i.MetadataFrozen) +
		`,"mintAuthority":` + meta.JSONString(i.MintAuthority.String()) +
		`,"pendingMintAuthority":` + meta.JSONString(i.PendingMintAuth.String()) +
		`,"mintRenounced":` + strconv.FormatBool(i.MintRenounced) + "}"
}

func TokenJSON(id string) string { return infoJSON(mustEntry(id)) }

// ListTokensJSON returns a zero-based page; page size is strictly 1..100.
func ListTokensJSON(page, size int64) string {
	if page < 0 || size < 1 || size > 100 {
		panic("launchpad/tokens: invalid page")
	}
	offset := sm.Mul(page, size)
	if offset >= Count() {
		return "[]"
	}
	end := offset + size
	if end > Count() {
		end = Count()
	}
	var b strings.Builder
	b.WriteByte('[')
	for i := offset; i < end; i++ {
		if i > offset {
			b.WriteByte(',')
		}
		// Entry i of the list is the token created (i+1)th.
		b.WriteString(infoJSON(mustEntry("T" + strconv.FormatInt(i+1, 10))))
	}
	b.WriteByte(']')
	return b.String()
}

// Package curation records who curates the Launchpad marketplace and what
// they decided about a collection: applications, feature slots, temporary
// holds, verification and appeals. It holds no coins and no tokens, never
// changes a collection's terms and never blocks a transfer, sale, refund or
// claim: a client reads these records and decides what to show.
package curation

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

const (
	maxSeats = 5
	maxTerm  = 90 * 24 * 60 * 60 // seconds

	StatusSubmitted        = "submitted"
	StatusChangesRequested = "changes_requested"
	StatusRecommended      = "recommended"
	StatusDeclined         = "declined"
)

// A seat is active strictly before until. Lead is a public label and grants
// nothing.
type seat struct {
	lead  bool
	until int64
}

// An Application is a founder's request for review and the latest decision on
// it. Earlier revisions and decisions stay in the event log.
type Application struct {
	Founder       address // who filed the latest revision
	StatementHash string
	StatementCID  string
	Revision      int64 // 0: nobody applied
	Status        string
	Reviewer      address
	ReasonHash    string
	ReasonCID     string
	UpdatedAt     int64
}

var (
	admin        address
	pendingAdmin address
	seats        avl.Tree // manager address -> seat; at most maxSeats entries
	conflicts    avl.Tree // "<collection>/<address>" -> true; never removed
	applications avl.Tree // collection -> *Application
	lastFiling   seqid.ID
	filings      avl.Tree // seqid key -> collection, in order of first filing
)

// The account that publishes the package is the first admin.
func init() { admin = unsafe.OriginCaller() }

func now() int64 { return time.Now().Unix() }

// caller returns the immediate caller. Nothing here takes payment: coins a
// wallet attaches to a direct call would stay in this realm, so they are
// refused. A calling realm keeps whatever its own caller sent.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("launchpad/curation: stale realm context")
	}
	if cur.Previous().IsUserCall() {
		currency.AssertNoCoins(0, cur)
	}
	return cur.Previous().Address()
}

// direct returns the wallet that called this realm itself. Founders and
// managers act in person: no realm can apply, review or recuse for them.
func direct(cur realm) address {
	who := caller(cur)
	if !cur.Previous().IsUserCall() {
		panic("launchpad/curation: direct user call required")
	}
	return who
}

func requireAdmin(cur realm) {
	if caller(cur) != admin {
		panic("launchpad/curation: admin only")
	}
}

var zeroHash = strings.Repeat("0", 64)

// commitment checks a pointer to public text: the SHA-256 of its exact bytes
// as 64 lowercase hex digits, not all zero, and a bounded IPFS CID it can be
// fetched from (CIDv1 "bafy..." or "bafk..." in base32, or CIDv0 "Qm..." in
// base58). Clients must hash what they fetch before showing it. Private prose
// never goes on chain. Byte ranges, not alphabet lookups: this is most of the
// cost of a call that takes a pointer.
func commitment(hash, cid string) {
	ok := len(hash) == 64 && hash != zeroHash
	for i := 0; ok && i < len(hash); i++ {
		c := hash[i]
		ok = c >= '0' && c <= '9' || c >= 'a' && c <= 'f'
	}
	switch {
	case len(cid) >= 59 && len(cid) <= 90 && (cid[:4] == "bafy" || cid[:4] == "bafk"):
		for i := 4; ok && i < len(cid); i++ {
			c := cid[i]
			ok = c >= 'a' && c <= 'z' || c >= '2' && c <= '7'
		}
	case len(cid) == 46 && cid[:2] == "Qm":
		for i := 2; ok && i < len(cid); i++ {
			c := cid[i]
			ok = c >= '1' && c <= '9' || c >= 'A' && c <= 'H' || c >= 'J' && c <= 'N' ||
				c >= 'P' && c <= 'Z' || c >= 'a' && c <= 'k' || c >= 'm' && c <= 'z'
		}
	default:
		ok = false
	}
	if !ok {
		panic("launchpad/curation: invalid hash or CID")
	}
}

// ProposeAdmin starts a handoff to any account or realm. Nothing changes
// until that exact address accepts.
func ProposeAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !meta.ValidAddress(next) || next == admin {
		panic("launchpad/curation: invalid next admin")
	}
	pendingAdmin = next
	chain.Emit("AdminProposed", "admin", admin.String(), "pending", next.String())
}

func CancelAdminProposal(cur realm) {
	requireAdmin(cur)
	if pendingAdmin == "" {
		panic("launchpad/curation: no pending admin")
	}
	pendingAdmin = ""
	chain.Emit("AdminProposalCancelled", "admin", admin.String())
}

// AcceptAdmin completes the handoff. No caller has the empty address, so
// nobody accepts while nothing is proposed. The admin holds no seat: a
// manager who accepts gives its seat up.
func AcceptAdmin(cur realm) {
	who := caller(cur)
	if who != pendingAdmin {
		panic("launchpad/curation: pending admin only")
	}
	previous := admin
	admin, pendingAdmin = who, ""
	if _, held := seats.Remove(who.String()); held {
		chain.Emit("ManagerRemoved", "manager", who.String())
	}
	chain.Emit("AdminAccepted", "admin", who.String(), "previous", previous.String())
}

func GetAdmin() address        { return admin }
func GetPendingAdmin() address { return pendingAdmin }

// checkAccount refuses an address the chain never gives a caller: another
// spelling of an account would read as a stranger.
func checkAccount(who address) {
	if !meta.ValidAddress(who) {
		panic("launchpad/curation: invalid account")
	}
}

func active(who address) bool {
	s := seats.Get(who.String())
	return s != nil && now() < s.(seat).until
}

func ActiveManager(who address) bool {
	checkAccount(who)
	return active(who)
}

func ActiveManagerCount() int {
	n, at := 0, now()
	seats.Iterate("", "", func(_ string, v any) bool {
		if at < v.(seat).until {
			n++
		}
		return false
	})
	return n
}

// AppointManager seats a manager until a time at most 90 days ahead, or
// replaces the term of one already seated. Expired seats are dropped first,
// so the tree never holds more than maxSeats entries.
func AppointManager(cur realm, who address, lead bool, until int64) {
	requireAdmin(cur)
	at := now()
	if !meta.ValidAddress(who) || who == admin || until <= at || until > at+maxTerm {
		panic("launchpad/curation: invalid manager term")
	}
	var expired []string
	seats.Iterate("", "", func(key string, v any) bool {
		if v.(seat).until <= at {
			expired = append(expired, key)
		}
		return false
	})
	for _, key := range expired {
		seats.Remove(key)
	}
	if !seats.Has(who.String()) && seats.Size() >= maxSeats {
		panic("launchpad/curation: every seat is taken")
	}
	seats.Set(who.String(), seat{lead, until})
	chain.Emit("ManagerAppointed", "manager", who.String(),
		"lead", strconv.FormatBool(lead), "until", strconv.FormatInt(until, 10))
}

func RemoveManager(cur realm, who address) {
	requireAdmin(cur)
	if !ActiveManager(who) {
		panic("launchpad/curation: no active manager")
	}
	seats.Remove(who.String())
	chain.Emit("ManagerRemoved", "manager", who.String())
}

func conflictKey(collection string, who address) string {
	return collection + "/" + who.String()
}

func recorded(collection string, who address) bool {
	return conflicts.Has(conflictKey(collection, who))
}

// HasConflict reports a recorded conflict only: a filing, a recusal or an
// admin's mark. Conflicted is the full rule.
func HasConflict(collection string, who address) bool {
	checkAccount(who)
	return recorded(collection, who)
}

// Conflicted reports whether an account may not act as a manager on a
// collection: it created the collection, holds or is proposed for its
// creator role now, or has a recorded conflict. It aborts on an unknown
// collection.
func Conflicted(collection string, who address) bool {
	checkAccount(who)
	return conflicted(nft.GetInfo(collection), who)
}

func conflicted(info nft.Info, who address) bool {
	return info.Originator == who || info.Creator == who ||
		info.PendingCreator == who || recorded(info.ID, who)
}

func seated(cur realm) address {
	who := direct(cur)
	if !active(who) {
		panic("launchpad/curation: active manager only")
	}
	return who
}

// manager returns the calling manager, who must hold an active seat and have
// no conflict on the collection.
func manager(cur realm, collection string) address {
	who := seated(cur)
	if conflicted(nft.GetInfo(collection), who) {
		panic("launchpad/curation: conflicted manager")
	}
	return who
}

// Resign gives up the calling manager's own seat at once.
func Resign(cur realm) {
	who := seated(cur)
	seats.Remove(who.String())
	chain.Emit("ManagerResigned", "manager", who.String())
}

// reopen voids the decision of a manager found conflicted after making it:
// the application awaits review again, so a conflict cannot be dodged by
// deciding first and disclosing later.
func reopen(collection string, who address) {
	a := applicationOf(collection)
	if a != nil && a.Reviewer == who {
		a.Status, a.Reviewer, a.ReasonHash, a.ReasonCID = StatusSubmitted, "", "", ""
		a.UpdatedAt = now()
		chain.Emit("ApplicationReopened", "collection", collection,
			"revision", strconv.FormatInt(a.Revision, 10), "reason", "conflict")
	}
}

// Recuse records the calling manager's own conflict on a collection and voids
// its decision there, if it made the latest one. A recorded conflict is
// permanent: nobody, the admin included, can clear it, and recusing again
// records and emits nothing.
func Recuse(cur realm, collection string) {
	who := seated(cur)
	nft.GetInfo(collection)
	if !recorded(collection, who) {
		conflicts.Set(conflictKey(collection, who), true)
		chain.Emit("ManagerRecused", "collection", collection, "manager", who.String())
		reopen(collection, who)
	}
}

// MarkConflict records a conflict the admin knows of, on a manager or on an
// account that may become one, and voids that account's latest decision on
// the collection as Recuse does. Marking a recorded conflict again records
// and emits nothing.
func MarkConflict(cur realm, collection string, who address) {
	requireAdmin(cur)
	nft.GetInfo(collection)
	checkAccount(who)
	if !recorded(collection, who) {
		conflicts.Set(conflictKey(collection, who), true)
		chain.Emit("ConflictMarked", "collection", collection, "account", who.String())
		reopen(collection, who)
	}
}

// founder returns the calling wallet, which must hold the collection's
// creator role.
func founder(cur realm, collection string) address {
	who := direct(cur)
	if nft.GetInfo(collection).Creator != who {
		panic("launchpad/curation: collection creator only")
	}
	return who
}

func applicationOf(collection string) *Application {
	if a := applications.Get(collection); a != nil {
		return a.(*Application)
	}
	return nil
}

// GetApplication returns a copy of a collection's application, the zero value
// (revision 0) when nobody applied, as ApplicationJSON answers null.
func GetApplication(collection string) Application {
	if a := applicationOf(collection); a != nil {
		return *a
	}
	return Application{}
}

// Apply files the founder's application for a collection. The founder may
// file again at any time before a recommendation, to correct a pointer or
// after a manager asked for changes or declined. Each filing is a new
// revision awaiting review. Filing records the filer's conflict on the
// collection for good. A realm that holds the creator role never applies: the
// founder calls in person.
func Apply(cur realm, collection, statementHash, statementCID string) {
	who := founder(cur, collection)
	commitment(statementHash, statementCID)
	a := applicationOf(collection)
	if a == nil {
		a = &Application{}
		applications.Set(collection, a)
		filings.Set(lastFiling.Next().String(), collection)
	} else if a.Status == StatusRecommended {
		panic("launchpad/curation: application recommended")
	}
	a.Founder = who // the creator role may have changed hands since the last filing
	if !recorded(collection, who) {
		conflicts.Set(conflictKey(collection, who), true)
	}
	a.Revision++
	a.StatementHash, a.StatementCID = statementHash, statementCID
	a.Status, a.Reviewer, a.ReasonHash, a.ReasonCID = StatusSubmitted, "", "", ""
	a.UpdatedAt = now()
	chain.Emit("ApplicationSubmitted", "collection", collection,
		"founder", who.String(), "revision", strconv.FormatInt(a.Revision, 10),
		"statement_hash", statementHash, "statement_cid", statementCID)
}

// Review records one manager's decision on the revision it read, which must
// still be the latest. Any unconflicted manager may decide again, whatever the
// latest decision. A recommendation is advice to the admin and gives the
// collection nothing by itself.
func Review(cur realm, collection string, revision int64, status, reasonHash, reasonCID string) {
	who := manager(cur, collection)
	a := applicationOf(collection)
	if a == nil {
		panic("launchpad/curation: no application open for review")
	}
	if revision != a.Revision {
		panic("launchpad/curation: application changed")
	}
	if status != StatusChangesRequested && status != StatusRecommended &&
		status != StatusDeclined {
		panic("launchpad/curation: invalid review status")
	}
	commitment(reasonHash, reasonCID)
	a.Status, a.Reviewer, a.ReasonHash, a.ReasonCID = status, who, reasonHash, reasonCID
	a.UpdatedAt = now()
	chain.Emit("ApplicationReviewed", "collection", collection,
		"manager", who.String(), "revision", strconv.FormatInt(a.Revision, 10),
		"status", status, "reason_hash", reasonHash, "reason_cid", reasonCID)
}

func Render(_ string) string {
	return "# Launchpad curation\n\n" + strconv.Itoa(ActiveManagerCount()) +
		" active managers, " + strconv.Itoa(applications.Size()) + " applications.\n"
}

package curation

import (
	"chain"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

const (
	maxFeature = 14 * 24 * 60 * 60 // seconds
	holdSpan   = 24 * 60 * 60
	maxHold    = 30 * 24 * 60 * 60
)

// What a founder may appeal: the decision on its application, a hold, the
// collection's verification, or a feature decision.
var subjects = [...]string{"application", "hold", "verification", "feature"}

// A feature slot exists only when one manager proposed it and another
// approved it. The admin can clear a slot and can never create one.
type feature struct {
	collection string
	proposer   address
	approver   address // empty until approved
	reasonHash string
	reasonCID  string
	until      int64
}

// A hold hides a collection from curated views until a time. It changes
// presentation only: nothing about the collection's tokens is frozen.
type hold struct {
	actor      address
	confirmer  address // empty until a second manager confirms
	extended   bool    // the admin set the term and its reason
	reasonHash string
	reasonCID  string
	until      int64
}

type verification struct {
	verified   bool
	reasonHash string
	reasonCID  string
	updatedAt  int64
}

type appeal struct {
	collection    string
	subject       string
	statementHash string
	statementCID  string
	filedAt       int64
	openKey       string // its key in openAppeals; empty once resolved
	upheld        bool
	reasonHash    string
	reasonCID     string
	resolvedAt    int64
}

var (
	features      avl.Tree // collection -> *feature
	holds         avl.Tree // collection -> *hold
	verifications avl.Tree // collection -> verification
	appeals       avl.Tree // "<collection>/<subject>" -> *appeal, the latest
	lastAppeal    seqid.ID
	openAppeals   avl.Tree // seqid key -> appeals key, in filing order
)

func featureOf(collection string) *feature {
	if f := features.Get(collection); f != nil {
		return f.(*feature)
	}
	return nil
}

func holdOf(collection string) *hold {
	if h := holds.Get(collection); h != nil {
		return h.(*hold)
	}
	return nil
}

func appealOf(key string) *appeal {
	if a := appeals.Get(key); a != nil {
		return a.(*appeal)
	}
	return nil
}

// standing reports whether who could act on the collection as a manager now.
// An unapproved slot's empty approver holds no seat.
func standing(collection string, who address) bool {
	return active(who) && !conflicted(nft.GetInfo(collection), who)
}

// pair enforces the two-manager rule when second completes what first began:
// two different managers, the first still seated and unconflicted. The second
// was checked as the caller.
func pair(collection string, first, second address) {
	if first == second || !standing(collection, first) {
		panic("launchpad/curation: a second unconflicted manager is required")
	}
}

// running reports a slot that runs, approved by two managers that both keep
// their standing: whether hidden or not, it is the collection's slot.
func running(collection string, f *feature) bool {
	return now() < f.until &&
		standing(collection, f.proposer) && standing(collection, f.approver)
}

// ProposeFeature opens a slot of at most 14 days. It features nothing until
// a second manager approves. It replaces a slot that is not running: one
// still unapproved, or one whose proposer or approver lost its standing.
func ProposeFeature(cur realm, collection, reasonHash, reasonCID string, until int64) {
	who := manager(cur, collection)
	commitment(reasonHash, reasonCID)
	at := now()
	if until <= at || until > at+maxFeature {
		panic("launchpad/curation: invalid feature term")
	}
	if f := featureOf(collection); f != nil && running(collection, f) {
		panic("launchpad/curation: feature slot running")
	}
	features.Set(collection, &feature{collection: collection, proposer: who,
		reasonHash: reasonHash, reasonCID: reasonCID, until: until})
	chain.Emit("FeatureProposed", "collection", collection,
		"manager", who.String(), "until", strconv.FormatInt(until, 10),
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

func ApproveFeature(cur realm, collection string) {
	who := manager(cur, collection)
	f := featureOf(collection)
	if f == nil || f.approver != "" || now() >= f.until {
		panic("launchpad/curation: no feature slot awaiting approval")
	}
	pair(collection, f.proposer, who)
	f.approver = who
	chain.Emit("FeatureApproved", "collection", collection,
		"proposer", f.proposer.String(), "manager", who.String(),
		"until", strconv.FormatInt(f.until, 10))
}

// IsFeatured holds only while the slot runs, both of its managers keep their
// standing and the collection is not hidden.
func IsFeatured(collection string) bool {
	f := featureOf(collection)
	return f != nil && running(collection, f) && !IsHidden(collection)
}

func ClearFeature(cur realm, collection, reasonHash, reasonCID string) {
	requireAdmin(cur)
	commitment(reasonHash, reasonCID)
	if _, had := features.Remove(collection); !had {
		panic("launchpad/curation: no feature slot")
	}
	chain.Emit("FeatureCleared", "collection", collection,
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

// HideTemporarily hides a collection for 24 hours on one manager's word. The
// record outlives the hold: no manager can start another until the admin
// clears it.
func HideTemporarily(cur realm, collection, reasonHash, reasonCID string) {
	who := manager(cur, collection)
	commitment(reasonHash, reasonCID)
	if holds.Has(collection) {
		panic("launchpad/curation: a hold is on record until the admin clears it")
	}
	until := now() + holdSpan
	holds.Set(collection, &hold{actor: who, reasonHash: reasonHash,
		reasonCID: reasonCID, until: until})
	chain.Emit("HideStarted", "collection", collection,
		"manager", who.String(), "until", strconv.FormatInt(until, 10),
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

// ConfirmHide lets a second manager keep a running hold for 24 hours from
// now, once. After that, or once the admin has set the term, only the admin
// changes it.
func ConfirmHide(cur realm, collection string) {
	who := manager(cur, collection)
	h := holdOf(collection)
	at := now()
	if h == nil || h.confirmer != "" || h.extended || at >= h.until {
		panic("launchpad/curation: no hold awaiting confirmation")
	}
	pair(collection, h.actor, who)
	h.confirmer, h.until = who, at+holdSpan
	chain.Emit("HideConfirmed", "collection", collection,
		"manager", who.String(), "until", strconv.FormatInt(h.until, 10))
}

// ExtendHide sets the term of a recorded hold, running or over, to a time at
// most 30 days ahead, and replaces its public reason.
func ExtendHide(cur realm, collection string, until int64, reasonHash, reasonCID string) {
	requireAdmin(cur)
	commitment(reasonHash, reasonCID)
	h := holdOf(collection)
	at := now()
	if h == nil || until <= at || until > at+maxHold {
		panic("launchpad/curation: invalid hold extension")
	}
	h.extended, h.until, h.reasonHash, h.reasonCID = true, until, reasonHash, reasonCID
	chain.Emit("HideExtended", "collection", collection,
		"until", strconv.FormatInt(until, 10),
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

func ClearHide(cur realm, collection, reasonHash, reasonCID string) {
	requireAdmin(cur)
	commitment(reasonHash, reasonCID)
	if _, had := holds.Remove(collection); !had {
		panic("launchpad/curation: no hold on record")
	}
	chain.Emit("HideCleared", "collection", collection,
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

// IsHidden holds while the hold runs and the manager whose word set its term
// keeps its standing: the starter, or the confirmer once it confirmed. A term
// the admin set rests on the admin alone.
func IsHidden(collection string) bool {
	h := holdOf(collection)
	switch {
	case h == nil || now() >= h.until:
		return false
	case h.extended:
		return true
	case h.confirmer != "":
		return standing(collection, h.confirmer)
	}
	return standing(collection, h.actor)
}

// SetVerified is the admin's statement that a collection is what it claims
// to be. It says nothing about price or future value.
func SetVerified(cur realm, collection string, value bool, reasonHash, reasonCID string) {
	requireAdmin(cur)
	nft.GetInfo(collection)
	commitment(reasonHash, reasonCID)
	if IsVerified(collection) == value {
		panic("launchpad/curation: verification unchanged")
	}
	verifications.Set(collection, verification{value, reasonHash, reasonCID, now()})
	chain.Emit("VerificationChanged", "collection", collection,
		"verified", strconv.FormatBool(value),
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

func IsVerified(collection string) bool {
	v := verifications.Get(collection)
	return v != nil && v.(verification).verified
}

// Appeal files the founder's objection on one subject. A collection has at
// most one open appeal per subject; a resolved one can be followed by another.
func Appeal(cur realm, collection, subject, statementHash, statementCID string) {
	who := founder(cur, collection)
	known := false
	for _, s := range subjects {
		known = known || s == subject
	}
	if !known {
		panic("launchpad/curation: invalid appeal subject")
	}
	commitment(statementHash, statementCID)
	key := collection + "/" + subject
	if a := appealOf(key); a != nil && a.openKey != "" {
		panic("launchpad/curation: appeal already open")
	}
	openKey := lastAppeal.Next().String()
	appeals.Set(key, &appeal{collection: collection, subject: subject,
		statementHash: statementHash, statementCID: statementCID,
		filedAt: now(), openKey: openKey})
	openAppeals.Set(openKey, key)
	chain.Emit("AppealFiled", "collection", collection, "subject", subject,
		"founder", who.String(),
		"statement_hash", statementHash, "statement_cid", statementCID)
}

// ResolveAppeal records the admin's answer and its public reason. It changes
// nothing else: the admin acts on an upheld appeal with the ordinary calls.
func ResolveAppeal(cur realm, collection, subject string, upheld bool, reasonHash, reasonCID string) {
	requireAdmin(cur)
	commitment(reasonHash, reasonCID)
	a := appealOf(collection + "/" + subject)
	if a == nil || a.openKey == "" {
		panic("launchpad/curation: no open appeal")
	}
	openAppeals.Remove(a.openKey)
	a.openKey, a.upheld, a.resolvedAt = "", upheld, now()
	a.reasonHash, a.reasonCID = reasonHash, reasonCID
	chain.Emit("AppealResolved", "collection", collection, "subject", subject,
		"upheld", strconv.FormatBool(upheld),
		"reason_hash", reasonHash, "reason_cid", reasonCID)
}

package curation

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/samcrew/launchpad/meta/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

// int64 values are decimal strings so a JSON client cannot round them.
func jsonInt(n int64) string { return meta.JSONString(strconv.FormatInt(n, 10)) }

func StateJSON() string {
	return "{" +
		`"admin":` + meta.JSONString(admin.String()) +
		`,"pendingAdmin":` + meta.JSONString(pendingAdmin.String()) +
		`,"activeManagers":` + strconv.Itoa(ActiveManagerCount()) +
		`,"maxSeats":` + strconv.Itoa(maxSeats) + "}"
}

// ManagersJSON lists the active seats, ordered by account.
func ManagersJSON() string {
	var b strings.Builder
	b.WriteByte('[')
	at := now()
	seats.Iterate("", "", func(account string, v any) bool {
		s := v.(seat)
		if at < s.until {
			if b.Len() > 1 {
				b.WriteByte(',')
			}
			b.WriteString(`{"account":` + meta.JSONString(account) +
				`,"lead":` + strconv.FormatBool(s.lead) +
				`,"until":` + jsonInt(s.until) + "}")
		}
		return false
	})
	b.WriteByte(']')
	return b.String()
}

// ApplicationJSON returns null for a collection nobody applied for.
func ApplicationJSON(collection string) string {
	a := applicationOf(collection)
	if a == nil {
		return "null"
	}
	return "{" +
		`"collection":` + meta.JSONString(collection) +
		`,"founder":` + meta.JSONString(a.Founder.String()) +
		`,"statementHash":` + meta.JSONString(a.StatementHash) +
		`,"statementCID":` + meta.JSONString(a.StatementCID) +
		`,"revision":` + jsonInt(a.Revision) +
		`,"status":` + meta.JSONString(a.Status) +
		`,"reviewer":` + meta.JSONString(a.Reviewer.String()) +
		`,"reasonHash":` + meta.JSONString(a.ReasonHash) +
		`,"reasonCID":` + meta.JSONString(a.ReasonCID) +
		`,"updatedAt":` + jsonInt(a.UpdatedAt) + "}"
}

// pageJSON renders a zero-based page of a tree in key order; the page size is
// 1..50.
func pageJSON(tree *avl.Tree, page, size int64, item func(v any) string) string {
	if page < 0 || size < 1 || size > 50 {
		panic("launchpad/curation: invalid page")
	}
	var b strings.Builder
	b.WriteByte('[')
	// page < total comes first so that page*size cannot overflow.
	if total := int64(tree.Size()); page < total && page*size < total {
		tree.IterateByOffset(int(page*size), int(size), func(_ string, v any) bool {
			if b.Len() > 1 {
				b.WriteByte(',')
			}
			b.WriteString(item(v))
			return false
		})
	}
	b.WriteByte(']')
	return b.String()
}

// ApplicationsJSON pages through the applications in order of first filing.
func ApplicationsJSON(page, size int64) string {
	return pageJSON(&filings, page, size, func(v any) string {
		return ApplicationJSON(v.(string))
	})
}

// AccessJSON tells a private inbox what an account is to a collection right
// now: whether it holds the creator role ("founder"), an active manager, and
// whether Conflicted bars it from acting as one. It is public data to be read
// on every request, not a token.
//
// The answer also says where and when it was evaluated: the chain ID, the
// block height and the block time. The answer is not signed: checking them
// exposes an honest node on the wrong chain or behind it, and proves nothing
// against a node that lies. Its eight fields are a contract with that reader.
func AccessJSON(collection, who string) string {
	account := address(who)
	checkAccount(account)
	info := nft.GetInfo(collection)
	return "{" +
		`"chainId":` + meta.JSONString(runtime.ChainID()) +
		`,"height":` + jsonInt(runtime.ChainHeight()) +
		`,"time":` + jsonInt(now()) +
		`,"collection":` + meta.JSONString(collection) +
		`,"account":` + meta.JSONString(who) +
		`,"founder":` + strconv.FormatBool(info.Creator == account) +
		`,"manager":` + strconv.FormatBool(active(account)) +
		`,"conflicted":` + strconv.FormatBool(conflicted(info, account)) + "}"
}

func featureJSON(collection string) string {
	f := featureOf(collection)
	if f == nil {
		return "null"
	}
	return "{" +
		`"proposer":` + meta.JSONString(f.proposer.String()) +
		`,"approver":` + meta.JSONString(f.approver.String()) +
		`,"reasonHash":` + meta.JSONString(f.reasonHash) +
		`,"reasonCID":` + meta.JSONString(f.reasonCID) +
		`,"until":` + jsonInt(f.until) + "}"
}

func holdJSON(collection string) string {
	h := holdOf(collection)
	if h == nil {
		return "null"
	}
	return "{" +
		`"actor":` + meta.JSONString(h.actor.String()) +
		`,"confirmer":` + meta.JSONString(h.confirmer.String()) +
		`,"extended":` + strconv.FormatBool(h.extended) +
		`,"reasonHash":` + meta.JSONString(h.reasonHash) +
		`,"reasonCID":` + meta.JSONString(h.reasonCID) +
		`,"until":` + jsonInt(h.until) + "}"
}

func verificationJSON(collection string) string {
	v := verifications.Get(collection)
	if v == nil {
		return "null"
	}
	r := v.(verification)
	return "{" +
		`"verified":` + strconv.FormatBool(r.verified) +
		`,"reasonHash":` + meta.JSONString(r.reasonHash) +
		`,"reasonCID":` + meta.JSONString(r.reasonCID) +
		`,"updatedAt":` + jsonInt(r.updatedAt) + "}"
}

func appealJSON(key string) string {
	a := appealOf(key)
	if a == nil {
		return "null"
	}
	return "{" +
		`"collection":` + meta.JSONString(a.collection) +
		`,"subject":` + meta.JSONString(a.subject) +
		`,"statementHash":` + meta.JSONString(a.statementHash) +
		`,"statementCID":` + meta.JSONString(a.statementCID) +
		`,"filedAt":` + jsonInt(a.filedAt) +
		`,"open":` + strconv.FormatBool(a.openKey != "") +
		`,"upheld":` + strconv.FormatBool(a.upheld) +
		`,"reasonHash":` + meta.JSONString(a.reasonHash) +
		`,"reasonCID":` + meta.JSONString(a.reasonCID) +
		`,"resolvedAt":` + jsonInt(a.resolvedAt) + "}"
}

// CollectionJSON is a collection's editorial record: what a client may show
// now, then the records behind it and the latest appeal on each subject. A
// part with no record is null.
func CollectionJSON(collection string) string {
	nft.GetInfo(collection)
	var b strings.Builder
	b.WriteString("{" +
		`"collection":` + meta.JSONString(collection) +
		`,"verified":` + strconv.FormatBool(IsVerified(collection)) +
		`,"featured":` + strconv.FormatBool(IsFeatured(collection)) +
		`,"hidden":` + strconv.FormatBool(IsHidden(collection)) +
		`,"verification":` + verificationJSON(collection) +
		`,"feature":` + featureJSON(collection) +
		`,"hold":` + holdJSON(collection) +
		`,"appeals":{`)
	for i, subject := range subjects {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(meta.JSONString(subject) + ":" + appealJSON(collection+"/"+subject))
	}
	b.WriteString("}}")
	return b.String()
}

// AppealsJSON pages through the open appeals in filing order.
func AppealsJSON(page, size int64) string {
	return pageJSON(&openAppeals, page, size, func(v any) string {
		return appealJSON(v.(string))
	})
}

// FeaturesJSON pages through every collection that has a feature slot on
// record, in ID text order, saying whether it is featured right now.
func FeaturesJSON(page, size int64) string {
	return pageJSON(&features, page, size, func(v any) string {
		f := v.(*feature)
		return "{" +
			`"collection":` + meta.JSONString(f.collection) +
			`,"featured":` + strconv.FormatBool(IsFeatured(f.collection)) +
			`,"until":` + jsonInt(f.until) + "}"
	})
}

// Package drops creates Launchpad NFT collections and runs their primary
// mints. It charges the collection fee and each mint price, and pays the
// treasury and the creator inside the same transaction: it holds no funds
// between calls and has no admin.
package drops

import (
	"chain"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/merkle/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

const (
	KindFixed     = "fixed"     // one price, open to every wallet
	KindAllowlist = "allowlist" // only addresses under a Merkle root, each with its own allowance
	KindHolder    = "holder"    // one mint per token held in another collection
	KindDutch     = "dutch"     // the price falls in a straight line until the stage ends

	// Hard limits, fixed for the life of this realm.
	maxPrimaryFeeBPS = 500 // 5% of a mint price
	maxStages        = 10
	maxStageSeconds  = 365 * 24 * 60 * 60
	maxPerWallet     = 1_000_000
)

// stage is one mint window of a collection, open during [Start, End).
type stage struct {
	Kind      string
	Start     int64
	End       int64
	Price     int64 // per token; for a dutch stage, the price at Start
	Floor     int64 // dutch only: the price reached at End
	Currency  string
	FeeBPS    int64  // protocol fee on each mint, pinned when the creator signed
	SupplyCap int64  // 0 means no cap beyond the collection's
	PerWallet int64  // most one wallet may mint; an allowlist sets it per address
	Root      string // allowlist only
	Gate      string // holder only: the collection whose tokens each allow one mint
	// Holder only: the gate collection's tokens numbered up to it, all minted
	// when the stage was placed, open a mint; later ones do not, so no loop of
	// collections gated on each other mints its own gate tokens.
	GateLimit int64
	Minted    int64
}

var (
	stages avl.Tree // collection ID -> []stage, at most maxStages
	minted avl.Tree // "<collection>/<stage>/<address>" -> int64
	gated  avl.Tree // "<collection>/<stage>/<gate token number>" -> true
)

func directCaller(cur realm) address {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("launchpad/drops: direct user call required")
	}
	return cur.Previous().Address()
}

// CreateCollection registers the caller's collection in the NFT ledger and
// pays the collection fee to the treasury. maxFee is the highest fee the
// caller accepts: a fee above it aborts before anything is taken, whatever
// the caller's allowance. Native coins are attached for exactly the fee; a
// token is pulled for exactly the fee. The collection terms are documented
// on nft.Create.
func CreateCollection(cur realm, name, symbol, description, image, banner,
	website, mode string, revocable bool, maxSupply int64, metadataMode,
	baseURI, placeholderURI, commitment, provenance, royalties,
	currencyKey string, maxFee int64) string {
	creator := directCaller(cur)
	p := policy(config.LaneCollection, currencyKey)
	if p.collectionFee > maxFee {
		panic("launchpad/drops: collection fee above the accepted maximum")
	}
	held := take(cur, currencyKey, p.collectionFee, p.collectionFee)
	id := nft.Create(cross(cur), creator, name, symbol, description, image,
		banner, website, mode, revocable, maxSupply, metadataMode, baseURI,
		placeholderURI, commitment, provenance, royalties)
	pay(cur, currencyKey, p.treasury, p.collectionFee)
	settled(cur, currencyKey, held)
	chain.Emit("CollectionFeePaid", "collection", id, "creator", creator.String(),
		"currency", currencyKey, "fee", strconv.FormatInt(p.collectionFee, 10),
		"treasury", p.treasury.String())
	return id
}

func stagesOf(id string) []stage {
	if list := stages.Get(id); list != nil {
		return list.([]stage)
	}
	return nil
}

// requireCreator aborts unless the caller is the collection's creator. The
// creator may be a realm, a DAO for instance: what it signs here moves no
// funds. Coins attached to a user's call would stay in this realm, so they
// are refused; coins a realm's transaction carries belong to that realm.
func requireCreator(cur realm, id string) {
	if !cur.IsCurrent() || cur.Previous().Address() != nft.GetInfo(id).Creator {
		panic("launchpad/drops: creator only")
	}
	if cur.Previous().IsUserCall() {
		currency.AssertNoCoins(0, cur)
	}
}

// emitStage publishes every term of a stage, so a reader of events alone
// knows what each stage sells.
func emitStage(id string, index int, s stage) {
	chain.Emit("StageSet", "collection", id, "stage", strconv.Itoa(index),
		"kind", s.Kind, "start", strconv.FormatInt(s.Start, 10),
		"end", strconv.FormatInt(s.End, 10), "currency", s.Currency,
		"price", strconv.FormatInt(s.Price, 10),
		"floor", strconv.FormatInt(s.Floor, 10),
		"fee_bps", strconv.FormatInt(s.FeeBPS, 10),
		"supply_cap", strconv.FormatInt(s.SupplyCap, 10),
		"per_wallet", strconv.FormatInt(s.PerWallet, 10),
		"root", s.Root, "gate", s.Gate, "gate_limit", strconv.FormatInt(s.GateLimit, 10))
}

func validRoot(s string) bool {
	h, err := merkle.ParseHash(s)
	return err == nil && merkle.FormatHash(h) == s
}

// newStage validates a stage of collection id that has not started. Fields a
// kind does not use must be zero, so a stage reads the same to everyone. A
// holder stage is gated on another collection, and only on the tokens that
// collection had minted when the stage was placed: gated on its own, or on a
// collection gated on it in turn, every token minted would open one more mint.
func newStage(id, kind string, start, end, price, floor, supplyCap, perWallet int64,
	root, gate, currencyKey string) stage {
	ok := start >= time.Now().Unix() && end > start && end-start <= maxStageSeconds &&
		price >= 0 && supplyCap >= 0 && perWallet >= 0 && perWallet <= maxPerWallet
	var gateLimit int64
	switch kind {
	case KindFixed:
		ok = ok && perWallet > 0 && floor == 0 && root == "" && gate == ""
	case KindAllowlist:
		ok = ok && perWallet == 0 && floor == 0 && validRoot(root) && gate == ""
	case KindHolder:
		ok = ok && perWallet > 0 && floor == 0 && root == "" && gate != "" && gate != id
		if ok {
			gateLimit = nft.GetInfo(gate).Minted // an unknown gate collection aborts
		}
	case KindDutch:
		ok = ok && perWallet > 0 && floor >= 0 && floor < price && root == "" && gate == ""
	default:
		ok = false
	}
	if !ok {
		panic("launchpad/drops: invalid stage")
	}
	return stage{Kind: kind, Start: start, End: end, Price: price, Floor: floor,
		Currency: currencyKey, SupplyCap: supplyCap, PerWallet: perWallet,
		Root: root, Gate: gate, GateLimit: gateLimit}
}

// place writes s at index (len(list) appends) after checking that the caller
// is the collection's creator, the mint lane accepts the currency, the
// protocol fee is within what the creator accepts and no other stage
// overlaps. The fee is pinned on the stage: a later change does not reach it.
func place(cur realm, id string, index int, s stage, maxFeeBPS int64) {
	requireCreator(cur, id)
	s.FeeBPS = policy(config.LaneNFTDrops, s.Currency).primaryFeeBPS
	if s.FeeBPS > maxFeeBPS || s.FeeBPS > maxPrimaryFeeBPS {
		panic("launchpad/drops: protocol fee above the accepted maximum")
	}
	list := stagesOf(id)
	for i, other := range list {
		if i != index && s.Start < other.End && other.Start < s.End {
			panic("launchpad/drops: stages overlap")
		}
	}
	if index == len(list) {
		list = append(list, s)
	} else {
		list[index] = s
	}
	stages.Set(id, list)
	emitStage(id, index, s)
}

// AddStage schedules a mint window and returns its index. The arguments are
// the terms of the stage, then the highest protocol fee the creator accepts.
// A collection has ten stages for its whole life: a stage that ended keeps
// its slot.
func AddStage(cur realm, id, kind string, start, end, price, floor, supplyCap,
	perWallet int64, root, gate, currencyKey string, maxFeeBPS int64) int {
	index := len(stagesOf(id))
	if index >= maxStages {
		panic("launchpad/drops: too many stages")
	}
	place(cur, id, index, newStage(id, kind, start, end, price, floor, supplyCap,
		perWallet, root, gate, currencyKey), maxFeeBPS)
	return index
}

// EditStage replaces a stage that has not started. Once a stage has opened
// its terms are final, whatever the replacement would have been: it can only
// be ended.
func EditStage(cur realm, id string, index int, kind string, start, end, price,
	floor, supplyCap, perWallet int64, root, gate, currencyKey string,
	maxFeeBPS int64) {
	list := stagesOf(id)
	if index < 0 || index >= len(list) {
		panic("launchpad/drops: unknown stage")
	}
	if time.Now().Unix() >= list[index].Start {
		panic("launchpad/drops: stage already started")
	}
	place(cur, id, index, newStage(id, kind, start, end, price, floor, supplyCap,
		perWallet, root, gate, currencyKey), maxFeeBPS)
}

// EndStage closes an open stage at once and for good. It asks no lane: a
// creator stops its own sale whatever is paused.
func EndStage(cur realm, id string, index int) {
	requireCreator(cur, id)
	list := stagesOf(id)
	if index < 0 || index >= len(list) {
		panic("launchpad/drops: unknown stage")
	}
	s := &list[index]
	now := time.Now().Unix()
	if now < s.Start || now >= s.End {
		panic("launchpad/drops: stage closed")
	}
	s.End = now
	stages.Set(id, list)
	emitStage(id, index, *s)
}

// priceAt is the stage price at a time inside its window.
func priceAt(s stage, now int64) int64 {
	if s.Kind != KindDutch {
		return s.Price
	}
	return s.Price - sm.MulDiv(s.Price-s.Floor, now-s.Start, s.End-s.Start)
}

func stageKey(id string, index int) string { return id + "/" + strconv.Itoa(index) + "/" }

// AllowlistLeaf is the Merkle leaf that lets who mint up to allowance tokens
// in one stage: sha256(0x00 || "launchpad-drop-v1|<collection>|<stage>|<address>|<allowance>").
// Only the chain's spelling of an address makes a leaf: a list written in
// capitals would name accounts that can never claim.
func AllowlistLeaf(id string, index int, who address, allowance int64) merkle.Hash {
	if !meta.ValidAddress(who) {
		panic("launchpad/drops: invalid account")
	}
	return merkle.Leaf([]byte("launchpad-drop-v1|" + id + "|" + strconv.Itoa(index) +
		"|" + who.String() + "|" + strconv.FormatInt(allowance, 10)))
}

// entitled checks what the stage's kind requires of the buyer and returns how
// many tokens that wallet may mint in the stage. For a holder stage it also
// returns the key under which the gate token must be recorded as used.
func entitled(s stage, id string, index int, buyer address, allowance int64,
	proof string, gateNumber int64) (limit int64, gateKey string) {
	switch s.Kind {
	case KindAllowlist:
		root, _ := merkle.ParseHash(s.Root)
		path, err := merkle.ParseProof(proof)
		if err != nil || gateNumber != 0 || allowance > maxPerWallet ||
			!merkle.Verify(root, AllowlistLeaf(id, index, buyer, allowance), path) {
			panic("launchpad/drops: not on the allowlist")
		}
		return allowance, ""
	case KindHolder:
		gateKey = stageKey(id, index) + strconv.FormatInt(gateNumber, 10)
		if allowance != 0 || proof != "" || gated.Has(gateKey) ||
			nft.OwnerOf(s.Gate, gateNumber) != buyer {
			panic("launchpad/drops: gate token missing or already used")
		}
		if gateNumber > s.GateLimit {
			panic("launchpad/drops: gate token minted after the stage was scheduled")
		}
	default:
		if allowance != 0 || proof != "" || gateNumber != 0 {
			panic("launchpad/drops: this stage takes no allowance, proof or gate token")
		}
	}
	return s.PerWallet, gateKey
}

// Mint sells the caller one token of an open stage and returns its number.
// currencyKey and offered are what the caller accepts to pay: the stage must
// be priced in that currency, and offered is the most it will take. Native
// coins are attached for exactly offered and the difference with the price
// comes back, which is what makes a falling price payable; a token is pulled
// for exactly the price. The price is split between the treasury (the fee
// pinned on the stage) and the creator. allowance and proof are for an
// allowlist stage, gateNumber for a holder stage; elsewhere they are zero and
// empty.
func Mint(cur realm, id string, index int, currencyKey string, offered,
	allowance int64, proof string, gateNumber int64) int64 {
	buyer := directCaller(cur)
	list := stagesOf(id)
	if index < 0 || index >= len(list) {
		panic("launchpad/drops: unknown stage")
	}
	s := &list[index]
	if s.Currency != currencyKey {
		panic("launchpad/drops: stage priced in another currency")
	}
	now := time.Now().Unix()
	if now < s.Start || now >= s.End || (s.SupplyCap > 0 && s.Minted >= s.SupplyCap) {
		panic("launchpad/drops: stage closed")
	}
	p := policy(config.LaneNFTDrops, s.Currency)
	wallet := stageKey(id, index) + buyer.String()
	var count int64
	if v := minted.Get(wallet); v != nil {
		count = v.(int64)
	}
	limit, gateKey := entitled(*s, id, index, buyer, allowance, proof, gateNumber)
	if count >= limit {
		panic("launchpad/drops: wallet limit reached")
	}
	price := priceAt(*s, now)
	held := take(cur, s.Currency, price, offered)
	number := nft.MintTo(cross(cur), id, buyer)
	creator := nft.GetInfo(id).Creator
	fee := sm.BPS(price, s.FeeBPS)
	pay(cur, s.Currency, p.treasury, fee)
	pay(cur, s.Currency, creator, price-fee)
	settled(cur, s.Currency, held)
	s.Minted++
	stages.Set(id, list)
	minted.Set(wallet, count+1)
	if gateKey != "" {
		gated.Set(gateKey, true)
	}
	chain.Emit("Minted", "collection", id, "number", strconv.FormatInt(number, 10),
		"stage", strconv.Itoa(index), "buyer", buyer.String(),
		"currency", s.Currency, "price", strconv.FormatInt(price, 10),
		"fee", strconv.FormatInt(fee, 10), "treasury", p.treasury.String(),
		"creator", creator.String())
	return number
}

func Render(path string) string {
	return "# Launchpad NFT drops\n\n" + strconv.Itoa(stages.Size()) +
		" collections have mint stages.\n"
}

package drops

import (
	"chain/banker"

	"gno.land/p/samcrew/launchpad/currency/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/samcrew/launchpad/config/v1"
)

// terms is what this realm needs from config.
type terms struct {
	treasury      address
	primaryFeeBPS int64 // share of each mint price
	collectionFee int64 // in the currency asked for
}

// termsOf reads the terms in force. The collection fee is -1 for a currency
// that has none.
func termsOf(currencyKey string) terms {
	p := config.GetVersion(config.GetCurrentVersion())
	t := terms{treasury: p.Treasury, primaryFeeBPS: p.NFTPrimaryFeeBPS, collectionFee: -1}
	for _, c := range p.Currencies {
		if c.Key == currencyKey {
			t.collectionFee = c.CollectionFee
		}
	}
	return t
}

// policy returns the terms in force after checking that the lane is open for
// the currency. It is a variable only so that unit tests can stand in for the
// config realm, whose admin cannot be set from another package's tests.
var policy = func(lane, currencyKey string) terms {
	config.AssertLaneOpen(lane, currencyKey)
	return termsOf(currencyKey)
}

// balance reads one denomination, so coins of other denominations sent to
// the realm never add to the cost of a payment.
func balance(cur realm, key string) int64 {
	if key == config.NativeCurrency {
		return banker.NewReadonlyBanker().GetCoin(cur.Address(), key)
	}
	return grc20reg.MustGet(key).BalanceOf(cur.Address())
}

// take collects price from the direct caller and returns what the realm held
// before. Native coins come attached: the caller attaches exactly offered, at
// least the price, and the difference goes straight back. A token is pulled
// for exactly the price.
func take(cur realm, key string, price, offered int64) int64 {
	if offered < price {
		panic("launchpad/drops: price above the amount offered")
	}
	if key != config.NativeCurrency {
		held := balance(cur, key)
		if price == 0 {
			currency.AssertNoCoins(0, cur)
		} else {
			currency.CollectToken(0, cur, grc20reg.MustGet(key), price)
		}
		return held
	}
	if offered == 0 {
		currency.AssertNoCoins(0, cur)
		return balance(cur, key)
	}
	buyer := currency.CollectNative(0, cur, offered)
	held := sm.Sub(balance(cur, key), offered)
	pay(cur, key, buyer, offered-price)
	return held
}

func pay(cur realm, key string, to address, amount int64) {
	if amount == 0 {
		return
	}
	if key == config.NativeCurrency {
		currency.PayNative(0, cur, to, amount)
	} else {
		currency.PayToken(0, cur, grc20reg.MustGet(key), to, amount)
	}
}

// settled aborts the transaction unless everything taken has been paid out:
// the realm must hold exactly what it held before the call.
func settled(cur realm, key string, held int64) {
	if balance(cur, key) != held {
		panic("launchpad/drops: payment not fully settled")
	}
}

package drops

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/samcrew/launchpad/meta/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

func num(n int64) string { return meta.JSONString(strconv.FormatInt(n, 10)) }

// StagesJSON lists a collection's stages in index order. "currentPrice" is
// the price a mint would pay now, and is only meaningful while "open" is true.
func StagesJSON(id string) string {
	nft.GetInfo(id) // an unknown collection aborts
	now := time.Now().Unix()
	var b strings.Builder
	b.WriteByte('[')
	for i, s := range stagesOf(id) {
		if i > 0 {
			b.WriteByte(',')
		}
		open := now >= s.Start && now < s.End
		current := s.Price
		if open {
			current = priceAt(s, now)
		}
		b.WriteString("{" +
			`"index":` + strconv.Itoa(i) +
			`,"kind":` + meta.JSONString(s.Kind) +
			`,"start":` + num(s.Start) +
			`,"end":` + num(s.End) +
			`,"open":` + strconv.FormatBool(open) +
			`,"price":` + num(s.Price) +
			`,"floor":` + num(s.Floor) +
			`,"currentPrice":` + num(current) +
			`,"currency":` + meta.JSONString(s.Currency) +
			`,"feeBPS":` + num(s.FeeBPS) +
			`,"supplyCap":` + num(s.SupplyCap) +
			`,"perWallet":` + num(s.PerWallet) +
			`,"root":` + meta.JSONString(s.Root) +
			`,"gate":` + meta.JSONString(s.Gate) +
			`,"gateLimit":` + num(s.GateLimit) +
			`,"minted":` + num(s.Minted) + "}")
	}
	b.WriteByte(']')
	return b.String()
}

// MintedBy is how many tokens who has minted in a stage. Only the chain's
// spelling of an address is an account: any other is refused, never read as 0.
func MintedBy(id string, index int, who string) int64 {
	if !meta.ValidAddress(address(who)) {
		panic("launchpad/drops: invalid account")
	}
	if v := minted.Get(stageKey(id, index) + who); v != nil {
		return v.(int64)
	}
	return 0
}

// GateUsed reports whether a gate token has already paid for a mint in a
// holder stage.
func GateUsed(id string, index int, gateNumber int64) bool {
	return gated.Has(stageKey(id, index) + strconv.FormatInt(gateNumber, 10))
}

// TermsJSON is what creating a collection and scheduling a stage cost now:
// the collection fee in a currency and the protocol fee a new stage would
// pin. A value of -1 means the lane is closed; config's ActionStatusJSON tells
// whether a lane accepts new actions right now.
func TermsJSON(currencyKey string) string {
	t := termsOf(currencyKey)
	return "{" +
		`"currency":` + meta.JSONString(currencyKey) +
		`,"collectionFee":` + num(t.collectionFee) +
		`,"primaryFeeBPS":` + num(t.primaryFeeBPS) +
		`,"maxPrimaryFeeBPS":` + num(maxPrimaryFeeBPS) +
		`,"treasury":` + meta.JSONString(t.treasury.String()) + "}"
}

// Package market trades Launchpad NFTs: fixed-price listings and funded
// offers. A sale pays the seller, the treasury and the collection's royalty
// receivers inside the same transaction. The realm holds only the escrow of
// open offers, which their buyers can always take back, and has no admin. It
// keeps open orders only: a closed one is deleted, so its storage deposit is
// released, and its history is the event log.
package market

import (
	"chain"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

const (
	marketPath = "gno.land/r/samcrew/launchpad/market/v1"

	// Why an order closed, as its closing event says.
	StatusFilled    = "filled"
	StatusCancelled = "cancelled"
	StatusReplaced  = "replaced"
	StatusExpired   = "expired"

	// Hard limits, fixed for the life of this realm.
	maxSecondaryFeeBPS = 200 // 2% of a sale price
	maxLifetime        = 90 * 24 * 60 * 60
	// How long after its expiry an order is still its owner's alone to close.
	// The chain returns the storage deposit of the bytes a call frees to that
	// call's sender (while ugnot is not a restricted denomination): the grace
	// keeps a stranger from taking a closed order's deposit at the very second
	// it expires, and leaves abandoned orders to whoever cleans them up.
	graceToClose = 7 * 24 * 60 * 60
	maxOrders    = 9_999_999_999
)

// Listing offers one token at a fixed price. The seller keeps the token and
// approves this realm; nothing is held here. A listing exists while it is
// open and no longer, and can be bought only within the token's custody epoch
// it was made in.
type Listing struct {
	ID         string // "L<n>"
	Collection string
	Number     int64
	Seller     address
	Price      int64
	Currency   string
	CreatedAt  int64
	ExpiresAt  int64
	FeeBPS     int64  // protocol fee, pinned when the seller signed
	key        string // its key in listings
	epoch      int64  // the token's custody epoch when it was listed
}

var (
	lastListing seqid.ID
	listings    avl.Tree // listing key -> *Listing, in creation order
	listed      avl.Tree // "<collection>/<token number key>" -> *Listing
	bySeller    avl.Tree // "<seller>/<listing key>" -> *Listing
)

func directCaller(cur realm) address {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("launchpad/market: direct user call required")
	}
	return cur.Previous().Address()
}

// orderKey reads an order ID, its prefix ('L' listing, 'O' offer) then its
// number, as its tree key.
func orderKey(prefix byte, id string) (string, bool) {
	if len(id) < 2 || len(id) > 11 || id[0] != prefix || id[1] == '0' {
		return "", false
	}
	n, err := strconv.ParseUint(id[1:], 10, 64)
	if err != nil {
		return "", false
	}
	return seqid.ID(n).String(), true
}

func nextOrder(last *seqid.ID, prefix string) (string, string) {
	if uint64(*last) >= maxOrders {
		panic("launchpad/market: order ID exhausted")
	}
	n := last.Next()
	return prefix + strconv.FormatUint(uint64(n), 10), n.String()
}

// findListing returns an open listing, or nil: a closed one is gone.
func findListing(id string) *Listing {
	if key, ok := orderKey('L', id); ok {
		if l := listings.Get(key); l != nil {
			return l.(*Listing)
		}
	}
	return nil
}

func mustListing(id string) *Listing {
	if l := findListing(id); l != nil {
		return l
	}
	panic("launchpad/market: unknown listing")
}

// tokenKey sorts a collection's tokens in number order.
func tokenKey(collection string, number int64) string {
	return collection + "/" + seqid.ID(number).String()
}

// listingOf returns the open listing of a token, or nil.
func listingOf(collection string, number int64) *Listing {
	if l := listed.Get(tokenKey(collection, number)); l != nil {
		return l.(*Listing)
	}
	return nil
}

// sellable reports whether seller owns the active token and has approved this
// realm for that token. Only a single-token approval counts, as an approval
// for all would outlive the token's moves.
func sellable(collection string, number int64, seller address) bool {
	return nft.StatusOf(collection, number) == nft.StatusActive &&
		nft.OwnerOf(collection, number) == seller &&
		nft.GetApproved(collection, number) == chain.PackageAddress(marketPath)
}

// pinned checks what every new order needs (a collection that can be sold, a
// price, a lifetime of at most 90 days) and returns the protocol fee to pin
// on it: the current one, which must not exceed what its owner accepts nor
// this realm's cap.
func pinned(collection string, price, expiresAt int64, currencyKey string, maxFeeBPS int64) int64 {
	fee := policy(currencyKey).feeBPS
	if fee > maxFeeBPS || fee > maxSecondaryFeeBPS {
		panic("launchpad/market: protocol fee above the accepted maximum")
	}
	now := time.Now().Unix()
	if nft.GetInfo(collection).Mode == nft.ModeSoulbound || price <= 0 ||
		expiresAt <= now || expiresAt > now+maxLifetime {
		panic("launchpad/market: invalid order")
	}
	return fee
}

// List offers the caller's token for sale and returns the listing ID. The
// caller must first approve this realm in the NFT ledger, and names the
// highest protocol fee it accepts; the fee in force is pinned on the listing.
// A new listing replaces the token's previous one.
func List(cur realm, collection string, number, price, expiresAt int64,
	currencyKey string, maxFeeBPS int64) string {
	seller := directCaller(cur)
	currency.AssertNoCoins(0, cur)
	fee := pinned(collection, price, expiresAt, currencyKey, maxFeeBPS)
	if !sellable(collection, number, seller) {
		panic("launchpad/market: not the owner, or the market is not approved")
	}
	if old := listingOf(collection, number); old != nil {
		closeListing(old, StatusReplaced)
	}
	id, treeKey := nextOrder(&lastListing, "L")
	l := &Listing{ID: id, Collection: collection, Number: number, Seller: seller,
		Price: price, Currency: currencyKey, CreatedAt: time.Now().Unix(),
		ExpiresAt: expiresAt, FeeBPS: fee, key: treeKey,
		epoch: nft.Epoch(collection, number)}
	listings.Set(treeKey, l)
	listed.Set(tokenKey(collection, number), l)
	bySeller.Set(seller.String()+"/"+treeKey, l)
	chain.Emit("Listed", "listing", id, "collection", collection,
		"number", strconv.FormatInt(number, 10), "seller", seller.String(),
		"currency", currencyKey, "price", strconv.FormatInt(price, 10),
		"fee_bps", strconv.FormatInt(fee, 10),
		"expires_at", strconv.FormatInt(expiresAt, 10))
	return id
}

// closeListing deletes a listing and says why in its closing event.
func closeListing(l *Listing, status string) {
	listings.Remove(l.key)
	listed.Remove(tokenKey(l.Collection, l.Number))
	bySeller.Remove(l.Seller.String() + "/" + l.key)
	chain.Emit("ListingClosed", "listing", l.ID, "status", status)
}

// live reports whether a listing can be bought right now. A move or an
// approval change starts a new custody epoch, so a listing never comes back to
// life when a token that left the seller returns or the market is approved
// again: the seller lists anew.
func live(l *Listing) bool {
	return time.Now().Unix() < l.ExpiresAt && sellable(l.Collection, l.Number, l.Seller) &&
		nft.Epoch(l.Collection, l.Number) == l.epoch
}

// Cancel withdraws a listing. The seller can always do it, paused market or
// not. Anyone can clear a listing whose seller no longer owns the token, or
// one that expired more than graceToClose ago; the chain returns the storage
// deposit of what a call frees to its caller, so clearing pays whoever does
// it.
func Cancel(cur realm, id string) {
	who := directCaller(cur)
	currency.AssertNoCoins(0, cur)
	l := mustListing(id)
	stale := time.Now().Unix() >= l.ExpiresAt+graceToClose ||
		nft.StatusOf(l.Collection, l.Number) != nft.StatusActive ||
		nft.OwnerOf(l.Collection, l.Number) != l.Seller
	switch {
	case who == l.Seller:
		closeListing(l, StatusCancelled)
	case stale:
		closeListing(l, StatusExpired)
	default:
		panic("launchpad/market: seller only")
	}
}

// Buy pays a listing's exact price and moves the token to the caller.
// currencyKey and price are the terms the buyer read: a listing on other
// terms, such as an ID the buyer never saw, takes nothing.
func Buy(cur realm, id, currencyKey string, price int64) {
	buyer := directCaller(cur)
	l := mustListing(id)
	if l.Currency != currencyKey || l.Price != price {
		panic("launchpad/market: order terms differ from those signed")
	}
	p := policy(l.Currency)
	if buyer == l.Seller || !live(l) {
		panic("launchpad/market: listing unavailable")
	}
	before := take(cur, l.Currency, l.Price)
	closeListing(l, StatusFilled)
	nft.TransferFrom(cross(cur), l.Collection, l.Seller, buyer, l.Number)
	settle(cur, l.Currency, l.Collection, l.Price, l.FeeBPS, l.Seller, p.treasury)
	settled(cur, l.Currency, before)
	chain.Emit("Sold", "listing", id, "collection", l.Collection,
		"number", strconv.FormatInt(l.Number, 10), "buyer", buyer.String(),
		"seller", l.Seller.String(), "currency", l.Currency,
		"price", strconv.FormatInt(l.Price, 10))
}

// GetListing returns an open listing; a closed or unknown ID aborts.
func GetListing(id string) Listing { return *mustListing(id) }

func Render(path string) string {
	return "# Launchpad NFT market\n\n" + strconv.Itoa(listings.Size()) +
		" open listings, " + strconv.Itoa(offers.Size()) + " open offers.\n"
}

package market

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/merkle/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

const (
	OfferToken      = "token"      // one named token
	OfferCollection = "collection" // any token of the collection
	OfferTrait      = "trait"      // any token proven to carry a trait
	StatusAccepted  = "accepted"
	// The token's own listing, closed because the token was sold to an offer.
	StatusSuperseded = "superseded"
	maxTraitBytes    = 100
)

// Offer is a bid whose full price sits in this realm until it is accepted,
// cancelled by its buyer or returned after expiry. An offer exists while it
// is open and no longer.
type Offer struct {
	ID         string // "O<n>"
	Kind       string
	Collection string
	Number     int64  // token offers only
	Trait      string // trait offers only: "<type>=<value>"
	Buyer      address
	Price      int64
	Currency   string
	CreatedAt  int64
	ExpiresAt  int64
	FeeBPS     int64 // protocol fee, pinned when the buyer funded the offer
}

var (
	lastOffer seqid.ID
	offers    avl.Tree // offer key -> *Offer, in creation order
	open      avl.Tree // "<collection>/<offer key>" -> *Offer
	byBuyer   avl.Tree // "<buyer>/<offer key>" -> *Offer
)

// findOffer returns an open offer and its key, or nil: a closed one is gone.
func findOffer(id string) (*Offer, string) {
	if key, ok := orderKey('O', id); ok {
		if o := offers.Get(key); o != nil {
			return o.(*Offer), key
		}
	}
	return nil, ""
}

func mustOffer(id string) (*Offer, string) {
	o, key := findOffer(id)
	if o == nil {
		panic("launchpad/market: unknown offer")
	}
	return o, key
}

// TraitLeaf is the Merkle leaf that proves a token carries a trait, as
// committed by the collection's creator in the NFT ledger.
func TraitLeaf(collection string, number int64, trait string) merkle.Hash {
	return merkle.Leaf([]byte("launchpad-trait-v1|" + collection + "|" +
		strconv.FormatInt(number, 10) + "|" + trait))
}

// MakeOffer escrows price and returns the offer ID. kind selects what the
// offer is for: number is set for a token offer, trait for a trait offer, and
// both are zero and empty otherwise. A trait offer needs a collection whose
// creator committed its traits. The protocol fee in force is pinned on the
// offer; it comes out of what the seller receives, never on top of the price,
// and maxFeeBPS is the highest the buyer lets a seller be charged.
func MakeOffer(cur realm, kind, collection string, number int64, trait string,
	price, expiresAt int64, currencyKey string, maxFeeBPS int64) string {
	buyer := directCaller(cur)
	fee := pinned(collection, price, expiresAt, currencyKey, maxFeeBPS)
	ok := false
	switch kind {
	case OfferToken:
		ok = trait == "" && nft.StatusOf(collection, number) == nft.StatusActive &&
			nft.OwnerOf(collection, number) != buyer
	case OfferCollection:
		ok = trait == "" && number == 0
	case OfferTrait:
		ok = number == 0 && len(trait) <= maxTraitBytes && strings.Count(trait, "=") == 1 &&
			!strings.HasPrefix(trait, "=") && !strings.HasSuffix(trait, "=") &&
			!strings.Contains(trait, "|") && nft.TraitsRoot(collection) != ""
	}
	if !ok {
		panic("launchpad/market: invalid offer")
	}
	before := take(cur, currencyKey, price)
	escrow[currencyKey] = sm.Add(escrow[currencyKey], price)
	id, key := nextOrder(&lastOffer, "O")
	o := &Offer{ID: id, Kind: kind, Collection: collection, Number: number,
		Trait: trait, Buyer: buyer, Price: price, Currency: currencyKey,
		CreatedAt: time.Now().Unix(), ExpiresAt: expiresAt, FeeBPS: fee}
	offers.Set(key, o)
	open.Set(collection+"/"+key, o)
	byBuyer.Set(buyer.String()+"/"+key, o)
	settled(cur, currencyKey, before)
	chain.Emit("OfferMade", "offer", id, "kind", kind, "collection", collection,
		"number", strconv.FormatInt(number, 10), "trait", trait,
		"buyer", buyer.String(), "currency", currencyKey,
		"price", strconv.FormatInt(price, 10), "fee_bps", strconv.FormatInt(fee, 10),
		"expires_at", strconv.FormatInt(expiresAt, 10))
	return id
}

// release deletes an offer, takes its price out of escrow and says why in its
// closing event; the caller then pays the price out. Every exit goes through
// here, and an offer leaves escrow once, by its own key: with `settled`, an
// exit pays out exactly the price of the one offer it closed, so a fault in
// one offer's exit can never spend another offer's escrow.
func release(o *Offer, key, status string) {
	if v := offers.Get(key); v == nil || v.(*Offer) != o {
		panic("launchpad/market: offer already closed")
	}
	offers.Remove(key)
	open.Remove(o.Collection + "/" + key)
	byBuyer.Remove(o.Buyer.String() + "/" + key)
	escrow[o.Currency] = sm.Sub(escrow[o.Currency], o.Price)
	chain.Emit("OfferClosed", "offer", o.ID, "status", status)
}

// refund returns an open offer's escrow to its buyer. Refunds never consult
// the config realm: no pause or policy change can hold a buyer's funds.
func refund(cur realm, o *Offer, key, status string) {
	before := untouched(cur, o.Currency)
	release(o, key, status)
	pay(cur, o.Currency, o.Buyer, o.Price)
	settled(cur, o.Currency, before)
}

// CancelOffer takes back the caller's own open offer, expired or not.
func CancelOffer(cur realm, id string) {
	who := directCaller(cur)
	o, key := mustOffer(id)
	if who != o.Buyer {
		panic("launchpad/market: buyer only")
	}
	refund(cur, o, key, StatusCancelled)
}

// ExpireOffer returns to its buyer the escrow of an offer that expired more
// than graceToClose ago. Anyone may call it: the price goes to the buyer, and
// the chain pays the caller the storage deposit of the bytes the offer
// occupied, so for a week after expiry only the buyer, with CancelOffer,
// takes its own offer back.
func ExpireOffer(cur realm, id string) {
	directCaller(cur)
	o, key := mustOffer(id)
	if time.Now().Unix() < o.ExpiresAt+graceToClose {
		panic("launchpad/market: only its buyer closes this offer yet")
	}
	refund(cur, o, key, StatusExpired)
}

// AcceptOffer sells the caller's token number to an open offer. proof is the
// comma-separated Merkle path of the token's trait for a trait offer, and
// empty otherwise. currencyKey and price are the terms the seller read: an
// offer on other terms, such as an ID the seller never saw, buys nothing. The
// caller must first approve this realm in the NFT ledger.
func AcceptOffer(cur realm, id string, number int64, proof, currencyKey string, price int64) {
	seller := directCaller(cur)
	o, key := mustOffer(id)
	if o.Currency != currencyKey || o.Price != price {
		panic("launchpad/market: order terms differ from those signed")
	}
	before := untouched(cur, o.Currency)
	p := policy(o.Currency)
	ok := time.Now().Unix() < o.ExpiresAt && seller != o.Buyer &&
		sellable(o.Collection, number, seller)
	switch {
	case !ok:
	case o.Kind == OfferToken:
		ok = number == o.Number && proof == ""
	case o.Kind == OfferCollection:
		ok = proof == ""
	default:
		root, _ := merkle.ParseHash(nft.TraitsRoot(o.Collection))
		path, err := merkle.ParseProof(proof)
		ok = err == nil && merkle.Verify(root, TraitLeaf(o.Collection, number, o.Trait), path)
	}
	if !ok {
		panic("launchpad/market: offer unavailable for this token")
	}
	release(o, key, StatusAccepted)
	if l := listingOf(o.Collection, number); l != nil {
		closeListing(l, StatusSuperseded)
	}
	nft.TransferFrom(cross(cur), o.Collection, seller, o.Buyer, number)
	settle(cur, o.Currency, o.Collection, o.Price, o.FeeBPS, seller, p.treasury)
	settled(cur, o.Currency, before)
	chain.Emit("OfferAccepted", "offer", id, "collection", o.Collection,
		"number", strconv.FormatInt(number, 10), "buyer", o.Buyer.String(),
		"seller", seller.String(), "currency", o.Currency,
		"price", strconv.FormatInt(o.Price, 10))
}

// GetOffer returns an open offer; a closed or unknown ID aborts.
func GetOffer(id string) Offer {
	o, _ := mustOffer(id)
	return *o
}

// EscrowOf is the total of open offers in a currency.
func EscrowOf(currencyKey string) int64 { return escrow[currencyKey] }

package market

import (
	"chain"
	"chain/banker"
	"strconv"

	"gno.land/p/samcrew/launchpad/currency/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

// escrow is, per currency, the total of open offers: everything this realm
// owes. Currencies are few (config allows sixteen), so a map is enough.
var escrow = map[string]int64{}

// terms is what this realm needs from config.
type terms struct {
	treasury address
	feeBPS   int64 // protocol share of each sale price
}

// policy returns the current terms after checking that the market lane is
// open for the currency. It is a variable only so that unit tests can stand in
// for the config realm, whose admin cannot be set from another package's tests.
var policy = func(currencyKey string) terms {
	config.AssertLaneOpen(config.LaneNFTMarket, currencyKey)
	p := config.GetVersion(config.GetCurrentVersion())
	return terms{treasury: p.Treasury, feeBPS: p.NFTSecondaryFeeBPS}
}

func balance(cur realm, key string) int64 {
	if key == config.NativeCurrency {
		return banker.NewReadonlyBanker().GetCoin(cur.Address(), key)
	}
	return grc20reg.MustGet(key).BalanceOf(cur.Address())
}

// surplus is what the realm holds beyond its open offers. Every entry point
// must leave it exactly as it found it.
func surplus(cur realm, key string) int64 { return sm.Sub(balance(cur, key), escrow[key]) }

// take collects exactly amount from the direct caller, attached for native
// coins and pulled for a token, and returns the surplus before the payment.
func take(cur realm, key string, amount int64) int64 {
	if key == config.NativeCurrency {
		currency.CollectNative(0, cur, amount)
		return sm.Sub(surplus(cur, key), amount)
	}
	before := surplus(cur, key)
	currency.CollectToken(0, cur, grc20reg.MustGet(key), amount)
	return before
}

// untouched is take for an entry point that receives nothing.
func untouched(cur realm, key string) int64 {
	currency.AssertNoCoins(0, cur)
	return surplus(cur, key)
}

func pay(cur realm, key string, to address, amount int64) {
	if amount == 0 {
		return
	}
	if key == config.NativeCurrency {
		currency.PayNative(0, cur, to, amount)
	} else {
		currency.PayToken(0, cur, grc20reg.MustGet(key), to, amount)
	}
}

// settle splits a sale price: the protocol fee to the treasury, each royalty
// to its receiver, the rest, rounding included, to the seller.
func settle(cur realm, key, collection string, price, feeBPS int64, seller, treasury address) {
	fee := sm.BPS(price, feeBPS)
	rest := sm.Sub(price, fee)
	pay(cur, key, treasury, fee)
	var royalties int64
	for _, r := range nft.RoyaltyQuote(collection, price) {
		pay(cur, key, r.Account, r.Amount)
		rest = sm.Sub(rest, r.Amount)
		royalties += r.Amount
	}
	pay(cur, key, seller, rest)
	chain.Emit("Settled", "collection", collection, "currency", key,
		"price", strconv.FormatInt(price, 10), "seller", strconv.FormatInt(rest, 10),
		"fee", strconv.FormatInt(fee, 10), "royalties", strconv.FormatInt(royalties, 10))
}

// settled aborts the transaction unless the realm holds exactly its open
// offers plus the surplus it had before the call: nothing taken is left
// behind, and nothing owed has been spent.
func settled(cur realm, key string, before int64) {
	if surplus(cur, key) != before {
		panic("launchpad/market: payment not fully settled")
	}
}

package market

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/nft/v1"
)

func num(n int64) string { return meta.JSONString(strconv.FormatInt(n, 10)) }

// splitJSON is how a price would be divided at a protocol fee: what the
// seller keeps, the treasury's fee and each royalty.
func splitJSON(collection string, price, feeBPS int64) string {
	fee := sm.BPS(price, feeBPS)
	seller := sm.Sub(price, fee)
	var b strings.Builder
	for i, r := range nft.RoyaltyQuote(collection, price) {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"account":` + meta.JSONString(r.Account.String()) +
			`,"amount":` + num(r.Amount) + "}")
		seller = sm.Sub(seller, r.Amount)
	}
	return `{"seller":` + num(seller) + `,"fee":` + num(fee) +
		`,"royalties":[` + b.String() + "]}"
}

func listingJSON(l *Listing) string {
	return "{" +
		`"id":` + meta.JSONString(l.ID) +
		`,"collection":` + meta.JSONString(l.Collection) +
		`,"number":` + num(l.Number) +
		`,"seller":` + meta.JSONString(l.Seller.String()) +
		`,"price":` + num(l.Price) +
		`,"currency":` + meta.JSONString(l.Currency) +
		`,"createdAt":` + num(l.CreatedAt) +
		`,"expiresAt":` + num(l.ExpiresAt) +
		`,"feeBPS":` + num(l.FeeBPS) +
		`,"buyable":` + strconv.FormatBool(live(l)) +
		`,"split":` + splitJSON(l.Collection, l.Price, l.FeeBPS) + "}"
}

func offerJSON(o *Offer) string {
	return "{" +
		`"id":` + meta.JSONString(o.ID) +
		`,"kind":` + meta.JSONString(o.Kind) +
		`,"collection":` + meta.JSONString(o.Collection) +
		`,"number":` + num(o.Number) +
		`,"trait":` + meta.JSONString(o.Trait) +
		`,"buyer":` + meta.JSONString(o.Buyer.String()) +
		`,"price":` + num(o.Price) +
		`,"currency":` + meta.JSONString(o.Currency) +
		`,"createdAt":` + num(o.CreatedAt) +
		`,"expiresAt":` + num(o.ExpiresAt) +
		`,"feeBPS":` + num(o.FeeBPS) +
		`,"split":` + splitJSON(o.Collection, o.Price, o.FeeBPS) + "}"
}

// ListingJSON is an open listing, or "null" once it is closed.
func ListingJSON(id string) string {
	if l := findListing(id); l != nil {
		return listingJSON(l)
	}
	return "null"
}

// OfferJSON is an open offer, or "null" once it is closed. An open offer can
// be past its expiry: it then only waits for its refund.
func OfferJSON(id string) string {
	if o, _ := findOffer(id); o != nil {
		return offerJSON(o)
	}
	return "null"
}

// Lists are read in slices of 1 to maxSlice entries that start after a
// cursor: what identifies the last entry already read, or nothing to start
// from the beginning. Orders come and go between two reads, and a cursor
// never skips or repeats one that stayed. A slice costs the same wherever it
// starts.
const maxSlice = 50

// sliceJSON renders up to size entries of tree whose keys lie in [from, to),
// in key order, or from the last key down when reverse.
func sliceJSON(tree *avl.Tree, from, to string, reverse bool, size int64, render func(v any) string) string {
	if size < 1 || size > maxSlice {
		panic("launchpad/market: invalid slice size")
	}
	var b strings.Builder
	b.WriteByte('[')
	visit := func(_ string, v any) bool {
		if b.Len() > 1 {
			b.WriteByte(',')
		}
		b.WriteString(render(v))
		size--
		return size == 0
	}
	if reverse {
		tree.ReverseIterate(from, to, visit)
	} else {
		tree.Iterate(from, to, visit)
	}
	b.WriteByte(']')
	return b.String()
}

// cursorKey reads an order cursor: the ID of the last order already read.
func cursorKey(prefix byte, cursor string) seqid.ID {
	key, ok := orderKey(prefix, cursor)
	if !ok {
		panic("launchpad/market: invalid cursor")
	}
	n, _ := seqid.FromString(key)
	return n
}

// after is the first key an oldest-first slice may hold: the one following
// the cursor, or "" with no cursor.
func after(prefix byte, cursor string) string {
	if cursor == "" {
		return ""
	}
	return (cursorKey(prefix, cursor) + 1).String()
}

// below is the last key a newest-first slice may hold: the one preceding the
// cursor, or "" with no cursor. No order has key zero, so the first order's
// ID leaves nothing below it.
func below(prefix byte, cursor string) string {
	if cursor == "" {
		return ""
	}
	return (cursorKey(prefix, cursor) - 1).String()
}

func renderListing(v any) string { return listingJSON(v.(*Listing)) }
func renderOffer(v any) string   { return offerJSON(v.(*Offer)) }

// ListingsJSON reads every open listing, newest first, starting below the
// listing ID before ("" starts from the newest).
func ListingsJSON(before string, size int64) string {
	// A descending range includes its upper bound.
	return sliceJSON(&listings, "", below('L', before), true, size, renderListing)
}

// CollectionListingsJSON reads a collection's open listings in token number
// order, starting after the token number afterNumber (0 starts from the
// first).
func CollectionListingsJSON(collection string, afterNumber, size int64) string {
	if afterNumber < 0 {
		panic("launchpad/market: invalid cursor")
	}
	// "0" is the byte after "/": the range ends with this collection's keys.
	return sliceJSON(&listed, tokenKey(collection, sm.Add(afterNumber, 1)), collection+"0", false, size, renderListing)
}

// account checks an address argument of a view.
func account(who string) string {
	if !meta.ValidAddress(address(who)) {
		panic("launchpad/market: invalid account")
	}
	return who
}

// SellerListingsJSON reads an account's open listings, oldest first, starting
// after the listing ID afterID ("" starts from the oldest).
func SellerListingsJSON(seller, afterID string, size int64) string {
	return sliceJSON(&bySeller, account(seller)+"/"+after('L', afterID), seller+"0", false, size, renderListing)
}

// OffersJSON reads every open offer, newest first, starting below the offer
// ID before ("" starts from the newest).
func OffersJSON(before string, size int64) string {
	return sliceJSON(&offers, "", below('O', before), true, size, renderOffer)
}

// CollectionOffersJSON reads a collection's open offers of every kind, oldest
// first, starting after the offer ID afterID ("" starts from the oldest).
func CollectionOffersJSON(collection, afterID string, size int64) string {
	return sliceJSON(&open, collection+"/"+after('O', afterID), collection+"0", false, size, renderOffer)
}

// BuyerOffersJSON reads an account's open offers, oldest first, starting
// after the offer ID afterID ("" starts from the oldest).
func BuyerOffersJSON(buyer, afterID string, size int64) string {
	return sliceJSON(&byBuyer, account(buyer)+"/"+after('O', afterID), buyer+"0", false, size, renderOffer)
}

// TokenListingJSON is the open listing of a token, or "null".
func TokenListingJSON(collection string, number int64) string {
	if l := listingOf(collection, number); l != nil {
		return listingJSON(l)
	}
	return "null"
}

// TermsJSON is what a sale costs now: the protocol fee a new listing would
// pin, and how a price would split for the collection. A fee of
// -1 means the lane is closed; config's ActionStatusJSON tells whether the
// market lane accepts new orders right now.
func TermsJSON(collection string, price int64) string {
	p := config.GetVersion(config.GetCurrentVersion())
	split := "null"
	if p.NFTSecondaryFeeBPS >= 0 && p.NFTSecondaryFeeBPS <= maxSecondaryFeeBPS {
		split = splitJSON(collection, price, p.NFTSecondaryFeeBPS)
	}
	return "{" +
		`"feeBPS":` + num(p.NFTSecondaryFeeBPS) +
		`,"maxFeeBPS":` + num(maxSecondaryFeeBPS) +
		`,"treasury":` + meta.JSONString(p.Treasury.String()) +
		`,"split":` + split + "}"
}

package sales

import (
	"strconv"
	"strings"

	"chain"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/merkle/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/tokens/v1"
)

const maxAirdropProofBytes = merkle.MaxDepth*64 + merkle.MaxDepth - 1

// AirdropRecord keeps the whole funded allocation encumbered until recipients
// claim. Claims never expire, and nothing sweeps or returns an unclaimed
// remainder.
type AirdropRecord struct {
	Root    string
	Total   int64
	Claimed int64
}

func requireAirdropRoot(root string) {
	h, err := merkle.ParseHash(root)
	if err != nil || merkle.FormatHash(h) != root || h == (merkle.Hash{}) {
		panic("launchpad/sales: invalid airdrop root")
	}
}

// CreateAirdrop funds one immutable campaign for a token from its creator's
// allowance. Its Merkle leaves are sha256(0x00 ||
// "launchpad-airdrop-v1|<token-id>|<index>|<beneficiary>|<amount>").
// The token ID in every leaf prevents a proof from authorizing a claim on a
// different launch, even if two creators publish the same tree shape.
func CreateAirdrop(cur realm, id, root string, total int64) {
	creator := directCaller(cur)
	currency.AssertNoCoins(0, cur)
	info := tokens.GetInfo(id)
	if info.Creator != creator || total <= 0 || airdropOf(id).Total != 0 {
		panic("launchpad/sales: creator airdrop only")
	}
	requireAirdropRoot(root)
	config.AssertLaneOpen(config.LaneAirdrop, info.CurrencyKey)
	tokens.TransferFrom(cross(cur), id, creator, chain.PackageAddress(salesPath), total)
	airdrops.Set(id, AirdropRecord{Root: root, Total: total})
	setTokenOwed(id, sm.Add(tokenOwed(id), total))
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	chain.Emit("LaunchpadAirdropCreated", "id", id, "creator", creator.String(),
		"root", root, "total", strconv.FormatInt(total, 10))
}

func GetAirdrop(id string) AirdropRecord {
	r := airdropOf(id)
	if r.Total == 0 {
		panic("launchpad/sales: airdrop not found")
	}
	return r
}

func AirdropClaimed(id string, index int) bool {
	if index < 0 {
		panic("launchpad/sales: invalid airdrop index")
	}
	return airdropClaims.Has(indexKey(id, index))
}

// ClaimAirdrop remains available while the airdrop lane is paused. Anyone can
// submit a proof; the destination is always the leaf's beneficiary. A leaf
// whose beneficiary is not written as the chain writes a caller's address can
// never be claimed: the token ledger would credit a balance no caller can
// reach.
func ClaimAirdrop(cur realm, id string, index int, beneficiary address, amount int64, proof string) {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	if index < 0 || amount <= 0 || len(proof) > maxAirdropProofBytes ||
		!meta.ValidAddress(beneficiary) ||
		beneficiary == chain.PackageAddress(salesPath) {
		panic("launchpad/sales: invalid airdrop claim")
	}
	r := GetAirdrop(id)
	key := indexKey(id, index)
	if airdropClaims.Has(key) {
		panic("launchpad/sales: airdrop already claimed")
	}
	h, _ := merkle.ParseHash(r.Root)
	p, err := merkle.ParseProof(proof)
	if err != nil {
		panic("launchpad/sales: invalid airdrop proof")
	}
	if proof != "" {
		parts := strings.Split(proof, ",")
		for i, sibling := range p {
			if merkle.FormatHash(sibling) != parts[i] {
				panic("launchpad/sales: invalid airdrop proof")
			}
		}
	}
	leaf := merkle.Leaf([]byte("launchpad-airdrop-v1|" + id + "|" +
		strconv.Itoa(index) + "|" + beneficiary.String() + "|" +
		strconv.FormatInt(amount, 10)))
	if !merkle.Verify(h, leaf, p) || sm.Add(r.Claimed, amount) > r.Total {
		panic("launchpad/sales: airdrop proof or allocation denied")
	}
	r.Claimed = sm.Add(r.Claimed, amount)
	airdropClaims.Set(key, true)
	airdrops.Set(id, r)
	setTokenOwed(id, sm.Sub(tokenOwed(id), amount))
	tokens.Transfer(cross(cur), id, beneficiary, amount)
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	chain.Emit("LaunchpadAirdropClaimed", "id", id,
		"index", strconv.Itoa(index), "beneficiary", beneficiary.String(),
		"amount", strconv.FormatInt(amount, 10))
}

package sales

import (
	"strconv"
	"strings"

	"chain"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/p/samcrew/launchpad/vesting/v1"
)

const (
	maxAllocationBytes = 8192
	maxAllocations     = 50
)

type allocation struct {
	beneficiary address
	amount      int64
	start       int64
	cliff       int64
	duration    int64
	revocable   bool
}

func decimal(s string) int64 {
	if s == "" || (len(s) > 1 && s[0] == '0') {
		panic("launchpad/sales: noncanonical allocation decimal")
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			panic("launchpad/sales: noncanonical allocation decimal")
		}
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("launchpad/sales: allocation decimal out of range")
	}
	return v
}

// parseAllocations accepts a single bounded, canonical MsgCall argument.
// Each record is address:amount:start:cliff:duration:revocable, with the
// address order providing both a stable encoding and duplicate rejection.
func parseAllocations(encoded string) ([]allocation, int64) {
	if len(encoded) > maxAllocationBytes {
		panic("launchpad/sales: allocations too large")
	}
	if encoded == "" {
		return nil, 0
	}
	records := strings.Split(encoded, ";")
	if len(records) > maxAllocations {
		panic("launchpad/sales: too many allocations")
	}
	out := make([]allocation, 0, len(records))
	var total int64
	previous := ""
	for _, record := range records {
		fields := strings.Split(record, ":")
		if len(fields) != 6 || fields[0] <= previous {
			panic("launchpad/sales: invalid allocation order or fields")
		}
		who := address(fields[0])
		if !meta.ValidAddress(who) || who == chain.PackageAddress(salesPath) {
			panic("launchpad/sales: invalid allocation address")
		}
		a := allocation{
			beneficiary: who,
			amount:      decimal(fields[1]),
			start:       decimal(fields[2]),
			cliff:       decimal(fields[3]),
			duration:    decimal(fields[4]),
		}
		if a.amount == 0 || (fields[5] != "0" && fields[5] != "1") {
			panic("launchpad/sales: invalid allocation amount or revocability")
		}
		a.revocable = fields[5] == "1"
		if a.duration == 0 {
			if a.start != 0 || a.cliff != 0 || a.revocable {
				panic("launchpad/sales: invalid immediate allocation")
			}
		} else {
			vesting.Schedule{Total: a.amount, Start: a.start, Cliff: a.cliff, Duration: a.duration}.Validate()
		}
		total = sm.Add(total, a.amount)
		out = append(out, a)
		previous = fields[0]
	}
	return out, total
}

package sales

import (
	"strconv"
	"strings"

	"gno.land/p/samcrew/launchpad/merkle/v1"
	"gno.land/r/samcrew/launchpad/tokens/v1"
)

const maxFairHoldingGateBytes = 256
const maxFairProofBytes = merkle.MaxDepth*64 + merkle.MaxDepth - 1

type fairHoldingGate struct {
	TokenID string
	Minimum int64
}

// Gates are at most three canonical, strictly token-ID-ordered records:
// token:T<n>:<positive base units>. Collection gates remain unavailable until
// the collection realm and its BalanceOf interface are implemented.
func parseFairHoldingGates(spec string) []fairHoldingGate {
	if spec == "" {
		return nil
	}
	if len(spec) > maxFairHoldingGateBytes {
		panic("launchpad/sales: invalid fair holding gates")
	}
	parts := strings.Split(spec, ";")
	if len(parts) > 3 {
		panic("launchpad/sales: invalid fair holding gates")
	}
	gates := make([]fairHoldingGate, len(parts))
	previous := ""
	for i, part := range parts {
		fields := strings.Split(part, ":")
		if len(fields) != 3 || fields[0] != "token" || fields[1] == "" ||
			(previous != "" && fields[1] <= previous) {
			panic("launchpad/sales: invalid fair holding gates")
		}
		minimum, err := strconv.ParseInt(fields[2], 10, 64)
		if err != nil || minimum <= 0 || strconv.FormatInt(minimum, 10) != fields[2] {
			panic("launchpad/sales: invalid fair holding gates")
		}
		tokens.GetInfo(fields[1])
		gates[i] = fairHoldingGate{TokenID: fields[1], Minimum: minimum}
		previous = fields[1]
	}
	return gates
}

func validateFairEligibility(root, gates string) {
	if root != "" {
		h, err := merkle.ParseHash(root)
		if err != nil || merkle.FormatHash(h) != root || h == (merkle.Hash{}) {
			panic("launchpad/sales: invalid fair allowlist root")
		}
	}
	parseFairHoldingGates(gates)
}

// The leaf is sha256(0x00 || "launchpad-fair-v1|<token-id>|<buyer>").
// The token ID prevents a valid proof from being reused for a different sale.
func requireFairEligibility(id string, r FairSaleRecord, buyer address, proof string) {
	if r.AllowlistRoot == "" {
		if proof != "" {
			panic("launchpad/sales: fair proof not expected")
		}
	} else {
		if len(proof) > maxFairProofBytes {
			panic("launchpad/sales: invalid fair allowlist proof")
		}
		parsed, err := merkle.ParseProof(proof)
		if err != nil {
			panic("launchpad/sales: invalid fair allowlist proof")
		}
		if proof != "" {
			parts := strings.Split(proof, ",")
			for i, sibling := range parsed {
				if merkle.FormatHash(sibling) != parts[i] {
					panic("launchpad/sales: invalid fair allowlist proof")
				}
			}
		}
		root, _ := merkle.ParseHash(r.AllowlistRoot)
		leaf := merkle.Leaf([]byte("launchpad-fair-v1|" + id + "|" + buyer.String()))
		if !merkle.Verify(root, leaf, parsed) {
			panic("launchpad/sales: fair allowlist denied")
		}
	}
	for _, gate := range parseFairHoldingGates(r.HoldingGates) {
		if tokens.BalanceOf(gate.TokenID, buyer) < gate.Minimum {
			panic("launchpad/sales: fair holding gate denied")
		}
	}
}

package sales

import (
	"strconv"
	"strings"
	"time"

	"chain"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/fairmath/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/tokens/v1"
)

// FairSaleRecord fixes the sale terms and records funded whole-lot orders.
// Settlement splits GrossQuote into the primary fee, owed to the protocol, and
// CreatorQuote, owed to the creator: the fee is GrossQuote minus CreatorQuote.
// RefundPaid and TokensClaimed count what buyer claims have taken out of this
// sale, so no claim can pay more than the sale itself owes.
type FairSaleRecord struct {
	Creator          address
	QuoteCurrency    string
	ConfigVersion    int64
	PrimaryFeeBPS    int64
	Allocation       int64
	LotSize          int64
	WalletCapLots    int64
	Caps             fairmath.Caps
	Schedule         fairmath.Schedule
	AllowlistRoot    string
	HoldingGates     string
	TotalLots        int64
	TotalDeposits    int64
	HardClosedAt     int64
	Cancelled        bool
	Settled          bool
	Succeeded        bool
	CloseAt          int64
	ClosePrice       int64
	SoldTokens       int64
	GrossQuote       int64
	CreatorQuote     int64
	ProceedsReleased bool
	RefundQuote      int64
	UnsoldTokens     int64
	RefundPaid       int64
	TokensClaimed    int64
}

type FairBuyerRecord struct {
	Lots    int64
	Deposit int64
	Claimed bool
}

var (
	fairEscrowLiability   = map[string]int64{}
	fairRefundLiability   = map[string]int64{}
	fairProceedsLiability = map[string]int64{}
)

// openFairSale gates a new sale on the live config, pins its primary fee,
// bounds the most quote it can ever hold in escrow, and collects its creation
// fee, which it returns.
func openFairSale(cur realm, r *FairSaleRecord) int64 {
	config.AssertNewAction(config.LaneFairSale, r.QuoteCurrency, r.ConfigVersion)
	p := config.GetVersion(r.ConfigVersion)
	for _, c := range p.Currencies {
		if c.Key == r.QuoteCurrency {
			if sm.Mul(r.Caps.HardLots, r.Schedule.StartPrice) > c.FairSaleRaiseCap {
				panic("launchpad/sales: fair sale exceeds raise cap")
			}
			r.PrimaryFeeBPS = p.PrimaryFeeBPS
			collectCreationFee(cur, r.QuoteCurrency, c.FairSaleCreationFee)
			return c.FairSaleCreationFee
		}
	}
	panic("launchpad/sales: currency has no fair-sale terms")
}

func fairTerms(creator address, saleAllocation, lotSize, hardLots,
	walletCapLots, softQuote int64, quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64) FairSaleRecord {
	if strings.HasPrefix(quoteCurrency, launchpadTokenRegistryPrefix) {
		panic("launchpad/sales: launchpad token cannot be quote currency")
	}
	schedule := fairmath.Schedule{
		Start: start, End: end, StartPrice: startPrice,
		FloorPrice: floorPrice, Decrement: decrement,
		IntervalSeconds: intervalSeconds,
	}
	schedule.Validate()
	if start <= time.Now().Unix() {
		panic("launchpad/sales: fair sale must start in the future")
	}
	caps := fairmath.Caps{HardLots: hardLots, SoftQuote: softQuote}
	caps.Validate(saleAllocation, lotSize, startPrice)
	if walletCapLots <= 0 || walletCapLots > hardLots {
		panic("launchpad/sales: invalid fair wallet cap")
	}
	return FairSaleRecord{
		Creator: creator, QuoteCurrency: quoteCurrency,
		ConfigVersion: expectedVersion, Allocation: saleAllocation,
		LotSize: lotSize, WalletCapLots: walletCapLots,
		Caps: caps, Schedule: schedule,
	}
}

func emitFairCreated(id, funding string, r FairSaleRecord, fee int64) {
	chain.Emit("LaunchpadFairSaleCreated", "id", id,
		"creator", r.Creator.String(), "currency", r.QuoteCurrency,
		"allocation", strconv.FormatInt(r.Allocation, 10),
		"lot_size", strconv.FormatInt(r.LotSize, 10),
		"hard_lots", strconv.FormatInt(r.Caps.HardLots, 10),
		"wallet_cap_lots", strconv.FormatInt(r.WalletCapLots, 10),
		"soft_quote", strconv.FormatInt(r.Caps.SoftQuote, 10),
		"allowlist_root", r.AllowlistRoot,
		"holding_gates", r.HoldingGates,
		"primary_fee_bps", strconv.FormatInt(r.PrimaryFeeBPS, 10),
		"funding", funding, "fee", strconv.FormatInt(fee, 10))
}

// CreateFairSale mints a fixed-supply fair-sale token and encumbers its whole-
// lot allocation in sales custody. The creator receives the initial supply
// remainder.
func CreateFairSale(cur realm, name, ticker string, decimals int,
	initialSupply, saleAllocation, lotSize, hardLots, walletCapLots, softQuote int64,
	quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64,
	description, image, website, xHandle, telegram string) string {
	return createFairSale(cur, name, ticker, decimals,
		initialSupply, saleAllocation, lotSize, hardLots, walletCapLots, softQuote,
		quoteCurrency, expectedVersion,
		start, end, startPrice, floorPrice, decrement, intervalSeconds,
		description, image, website, xHandle, telegram, "", "", "")
}

// CreateGatedFairSale binds a precomputed token ID to a Merkle root and/or
// token-holding gates. The expected ID prevents an intervening creation from
// silently attaching the root to a different token.
func CreateGatedFairSale(cur realm, name, ticker string, decimals int,
	initialSupply, saleAllocation, lotSize, hardLots, walletCapLots, softQuote int64,
	quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64,
	description, image, website, xHandle, telegram,
	expectedID, allowlistRoot, holdingGates string) string {
	return createFairSale(cur, name, ticker, decimals,
		initialSupply, saleAllocation, lotSize, hardLots, walletCapLots, softQuote,
		quoteCurrency, expectedVersion,
		start, end, startPrice, floorPrice, decrement, intervalSeconds,
		description, image, website, xHandle, telegram,
		expectedID, allowlistRoot, holdingGates)
}

func createFairSale(cur realm, name, ticker string, decimals int,
	initialSupply, saleAllocation, lotSize, hardLots, walletCapLots, softQuote int64,
	quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64,
	description, image, website, xHandle, telegram,
	expectedID, allowlistRoot, holdingGates string) string {
	creator := directCaller(cur)
	r := fairTerms(creator, saleAllocation, lotSize, hardLots,
		walletCapLots, softQuote, quoteCurrency, expectedVersion,
		start, end, startPrice, floorPrice, decrement, intervalSeconds)
	validateFairEligibility(allowlistRoot, holdingGates)
	if allowlistRoot != "" && expectedID == "" {
		panic("launchpad/sales: fair allowlist token ID required")
	}
	if expectedID != "" && expectedID != "T"+strconv.FormatInt(sm.Add(tokens.Count(), 1), 10) {
		panic("launchpad/sales: fair token ID changed")
	}
	r.AllowlistRoot = allowlistRoot
	r.HoldingGates = holdingGates
	if initialSupply <= 0 || saleAllocation > initialSupply {
		panic("launchpad/sales: fair allocation exceeds supply")
	}
	fee := openFairSale(cur, &r)
	id := tokens.Create(cross(cur), creator, tokens.ModeFairSale, name, ticker,
		decimals, initialSupply, initialSupply, quoteCurrency, expectedVersion,
		description, image, website, xHandle, telegram)
	if expectedID != "" && id != expectedID {
		panic("launchpad/sales: fair token ID changed")
	}
	remainder := sm.Sub(initialSupply, saleAllocation)
	if remainder > 0 {
		tokens.Transfer(cross(cur), id, creator, remainder)
	}
	fairSales.Set(id, r)
	setTokenOwed(id, sm.Add(tokenOwed(id), saleAllocation))
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) != tokenOwed(id) {
		panic("launchpad/sales: token custody mismatch")
	}
	emitFairCreated(id, "minted", r, fee)
	return id
}

// CreateFairSaleFromToken locks an existing direct token's exact creator-funded
// allocation. Other token liabilities remain encumbered in the same custody
// balance. One token can have at most one fair sale.
func CreateFairSaleFromToken(cur realm, id string,
	saleAllocation, lotSize, hardLots, walletCapLots, softQuote int64,
	quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64) {
	createFairSaleFromToken(cur, id,
		saleAllocation, lotSize, hardLots, walletCapLots, softQuote,
		quoteCurrency, expectedVersion,
		start, end, startPrice, floorPrice, decrement, intervalSeconds, "", "")
}

func CreateGatedFairSaleFromToken(cur realm, id string,
	saleAllocation, lotSize, hardLots, walletCapLots, softQuote int64,
	quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64,
	allowlistRoot, holdingGates string) {
	createFairSaleFromToken(cur, id,
		saleAllocation, lotSize, hardLots, walletCapLots, softQuote,
		quoteCurrency, expectedVersion,
		start, end, startPrice, floorPrice, decrement, intervalSeconds,
		allowlistRoot, holdingGates)
}

func createFairSaleFromToken(cur realm, id string,
	saleAllocation, lotSize, hardLots, walletCapLots, softQuote int64,
	quoteCurrency string, expectedVersion int64,
	start, end, startPrice, floorPrice, decrement, intervalSeconds int64,
	allowlistRoot, holdingGates string) {
	creator := directCaller(cur)
	info := tokens.GetInfo(id)
	if info.Creator != creator ||
		(info.Mode != tokens.ModeDirectFixed && info.Mode != tokens.ModeDirectCap) ||
		fairSales.Has(id) {
		panic("launchpad/sales: existing fair token denied")
	}
	r := fairTerms(creator, saleAllocation, lotSize, hardLots,
		walletCapLots, softQuote, quoteCurrency, expectedVersion,
		start, end, startPrice, floorPrice, decrement, intervalSeconds)
	validateFairEligibility(allowlistRoot, holdingGates)
	r.AllowlistRoot = allowlistRoot
	r.HoldingGates = holdingGates
	fee := openFairSale(cur, &r)
	tokens.TransferFrom(cross(cur), id, creator,
		chain.PackageAddress(salesPath), saleAllocation)
	fairSales.Set(id, r)
	setTokenOwed(id, sm.Add(tokenOwed(id), saleAllocation))
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	emitFairCreated(id, "deposited", r, fee)
}

func GetFairSale(id string) FairSaleRecord {
	r, ok := fairSales.Get(id).(FairSaleRecord)
	if !ok {
		panic("launchpad/sales: fair sale not found")
	}
	return r
}

func GetFairBuyer(id string, buyer address) FairBuyerRecord {
	if !meta.ValidAddress(buyer) {
		panic("launchpad/sales: invalid address")
	}
	GetFairSale(id)
	b, _ := fairBuyers.Get(buyerKey(id, buyer)).(FairBuyerRecord)
	return b
}

// assertWithinSale runs on every exit of a settled sale. Quote and tokens sit
// in balances pooled across sales, and the custody checks compare a balance
// with totals only: an exit that overpaid one sale while lowering the totals
// by as much would pass them, paid with other sales' money. Settlement
// asserted GrossQuote + RefundQuote = TotalDeposits, so with these bounds a
// sale never pays out more quote than it took in, nor more tokens than it
// sold. Settlement also sets CreatorQuote to GrossQuote minus the fee, so the
// last bound cannot fail on a record settlement wrote; it stays as a defence
// should a later change break that.
func assertWithinSale(r FairSaleRecord) {
	if r.RefundPaid > r.RefundQuote || r.TokensClaimed > r.SoldTokens ||
		r.CreatorQuote > r.GrossQuote {
		panic("launchpad/sales: fair sale overpaid")
	}
}

// SettleFair closes a sale at its recorded hard-cap fill or scheduled end.
// It returns every unsold token to the creator and partitions deposits into
// buyer refunds, the creator's proceeds and the protocol's primary fee. The
// fee joins the bucket SweepFees pays; nothing is paid out here, so neither
// receiver can hold up settlement or buyer claims.
func SettleFair(cur realm, id string) {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	r := GetFairSale(id)
	if r.Cancelled {
		panic("launchpad/sales: fair settlement unavailable")
	}
	if r.Settled {
		return
	}
	if r.HardClosedAt == 0 && time.Now().Unix() < r.Schedule.End {
		panic("launchpad/sales: fair settlement unavailable")
	}
	closeAt := r.Schedule.End
	if r.HardClosedAt != 0 {
		closeAt = r.HardClosedAt
	}
	price := r.Schedule.PriceAt(closeAt)
	result := fairmath.Clear(r.Caps, r.Allocation, r.LotSize,
		r.TotalLots, r.TotalDeposits, price)
	if sm.Add(result.GrossQuote, result.RefundQuote) != r.TotalDeposits ||
		sm.Add(result.SoldTokens, result.UnsoldTokens) != r.Allocation {
		panic("launchpad/sales: fair settlement partition mismatch")
	}
	r.Settled = true
	r.Succeeded = result.Succeeded
	r.CloseAt = closeAt
	r.ClosePrice = price
	r.SoldTokens = result.SoldTokens
	r.GrossQuote = result.GrossQuote
	primaryFee := sm.BPS(result.GrossQuote, r.PrimaryFeeBPS)
	r.CreatorQuote = sm.Sub(result.GrossQuote, primaryFee)
	r.RefundQuote = result.RefundQuote
	r.UnsoldTokens = result.UnsoldTokens
	fairSales.Set(id, r)
	key := r.QuoteCurrency
	fairEscrowLiability[key] = sm.Sub(fairEscrowLiability[key], r.TotalDeposits)
	fairRefundLiability[key] = sm.Add(fairRefundLiability[key], result.RefundQuote)
	fairProceedsLiability[key] = sm.Add(fairProceedsLiability[key], r.CreatorQuote)
	feeLiability[key] = sm.Add(feeLiability[key], primaryFee)
	setTokenOwed(id, sm.Sub(tokenOwed(id), result.UnsoldTokens))
	if result.UnsoldTokens > 0 {
		tokens.Transfer(cross(cur), id, r.Creator, result.UnsoldTokens)
	}
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	assertQuoteCovered(cur, key)
	chain.Emit("LaunchpadFairSettled", "id", id, "currency", key,
		"succeeded", strconv.FormatBool(result.Succeeded),
		"close_price", strconv.FormatInt(price, 10),
		"gross_quote", strconv.FormatInt(result.GrossQuote, 10),
		"primary_fee_quote", strconv.FormatInt(primaryFee, 10),
		"creator_quote", strconv.FormatInt(r.CreatorQuote, 10),
		"refund_quote", strconv.FormatInt(result.RefundQuote, 10),
		"unsold_tokens", strconv.FormatInt(result.UnsoldTokens, 10))
}

// ClaimFair lets anyone release a buyer's recorded tokens and quote refund
// to that buyer. Claims never expire and ignore current pause/listing.
func ClaimFair(cur realm, id string, buyer address) {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	r := GetFairSale(id)
	b := GetFairBuyer(id, buyer)
	if !r.Settled || b.Lots <= 0 || b.Claimed {
		panic("launchpad/sales: fair claim unavailable")
	}
	claim := fairmath.Claim(r.Succeeded, b.Lots, b.Deposit,
		r.LotSize, r.ClosePrice)
	r.RefundPaid = sm.Add(r.RefundPaid, claim.RefundQuote)
	r.TokensClaimed = sm.Add(r.TokensClaimed, claim.Tokens)
	assertWithinSale(r)
	fairSales.Set(id, r)
	b.Claimed = true
	fairBuyers.Set(buyerKey(id, buyer), b)
	key := r.QuoteCurrency
	fairRefundLiability[key] = sm.Sub(fairRefundLiability[key], claim.RefundQuote)
	setTokenOwed(id, sm.Sub(tokenOwed(id), claim.Tokens))
	if claim.Tokens > 0 {
		tokens.Transfer(cross(cur), id, buyer, claim.Tokens)
	}
	if claim.RefundQuote > 0 {
		payQuote(cur, key, buyer, claim.RefundQuote)
	}
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	assertQuoteCovered(cur, key)
	chain.Emit("LaunchpadFairClaimed", "id", id, "buyer", buyer.String(),
		"tokens", strconv.FormatInt(claim.Tokens, 10),
		"refund_quote", strconv.FormatInt(claim.RefundQuote, 10))
}

// ReleaseFairProceeds pays a succeeded sale's creator what settlement
// recorded for them, once, and returns the amount. Anyone can call it; the
// receiver is always the recorded creator. It stays open while the lane is
// paused or the currency delisted.
func ReleaseFairProceeds(cur realm, id string) int64 {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	r := GetFairSale(id)
	if !r.Settled || !r.Succeeded || r.ProceedsReleased {
		panic("launchpad/sales: fair proceeds unavailable")
	}
	r.ProceedsReleased = true
	assertWithinSale(r)
	fairSales.Set(id, r)
	key := r.QuoteCurrency
	fairProceedsLiability[key] = sm.Sub(fairProceedsLiability[key], r.CreatorQuote)
	// A succeeded sale raised at least its soft cap and the fee is at most 5%,
	// so there is always something to pay.
	payQuote(cur, key, r.Creator, r.CreatorQuote)
	assertQuoteCovered(cur, key)
	chain.Emit("LaunchpadFairProceedsReleased", "id", id,
		"creator", r.Creator.String(), "currency", key,
		"creator_quote", strconv.FormatInt(r.CreatorQuote, 10),
		"actor", cur.Previous().Address().String())
	return r.CreatorQuote
}

// ContributeFair escrows exact quote atoms for whole token lots at this
// transaction's schedule price. The direct caller is both payer and buyer,
// and maxDeposit is the most the order may cost. A native order attaches
// exactly maxDeposit and gets maxDeposit minus the cost back in the same
// transaction; a token order pulls only the cost from the buyer's allowance.
func ContributeFair(cur realm, id string, lots, maxDeposit int64) {
	contributeFair(cur, id, lots, maxDeposit, "")
}

// ContributeFairWithProof verifies the recorded allowlist and holding gates
// against the direct buyer's live address and balances before collecting quote.
func ContributeFairWithProof(cur realm, id string, lots, maxDeposit int64, proof string) {
	contributeFair(cur, id, lots, maxDeposit, proof)
}

func contributeFair(cur realm, id string, lots, maxDeposit int64, proof string) {
	buyer := directCaller(cur)
	r := GetFairSale(id)
	now := time.Now().Unix()
	if r.Cancelled || r.Settled || r.HardClosedAt != 0 || now < r.Schedule.Start || now >= r.Schedule.End {
		panic("launchpad/sales: fair sale closed")
	}
	// The sale's own terms are pinned in its record and the buyer bounds the
	// price with maxDeposit, so no config version is involved here.
	config.AssertLaneOpen(config.LaneFairSale, r.QuoteCurrency)
	if lots <= 0 || maxDeposit <= 0 {
		panic("launchpad/sales: invalid fair order")
	}
	b := GetFairBuyer(id, buyer)
	nextBuyerLots := sm.Add(b.Lots, lots)
	if nextBuyerLots > r.WalletCapLots {
		panic("launchpad/sales: fair wallet cap exceeded")
	}
	requireFairEligibility(id, r, buyer, proof)
	nextTotalLots, hardClosed := r.Caps.AddLots(r.TotalLots, lots)
	order := fairmath.QuoteOrder(lots, r.LotSize, r.Schedule.PriceAt(now))
	if order.Deposit > maxDeposit {
		panic("launchpad/sales: fair quote exceeds buyer bound")
	}
	if r.QuoteCurrency == config.NativeCurrency {
		// Coins are attached when the buyer signs, and a falling price can step
		// down before the block: the buyer attaches its bound, exactly, and gets
		// back at once what the order does not cost.
		currency.CollectNative(0, cur, maxDeposit)
		if change := maxDeposit - order.Deposit; change > 0 {
			currency.PayNative(0, cur, buyer, change)
		}
	} else {
		collectQuote(cur, r.QuoteCurrency, order.Deposit)
	}
	b.Lots = nextBuyerLots
	b.Deposit = sm.Add(b.Deposit, order.Deposit)
	fairBuyers.Set(buyerKey(id, buyer), b)
	r.TotalLots = nextTotalLots
	r.TotalDeposits = sm.Add(r.TotalDeposits, order.Deposit)
	if hardClosed {
		r.HardClosedAt = now
	}
	fairSales.Set(id, r)
	fairEscrowLiability[r.QuoteCurrency] = sm.Add(fairEscrowLiability[r.QuoteCurrency], order.Deposit)
	// The admin's brake on what the realm may hold in a currency. Only an
	// inflow reads it; exits never do.
	if owedIn(r.QuoteCurrency) > config.GetSalesOwedCeiling(r.QuoteCurrency) {
		panic("launchpad/sales: sales owed ceiling reached")
	}
	assertQuoteCovered(cur, r.QuoteCurrency)
	chain.Emit("LaunchpadFairContribution", "id", id, "buyer", buyer.String(),
		"lots", strconv.FormatInt(lots, 10),
		"price", strconv.FormatInt(order.Deposit/lots, 10),
		"deposit", strconv.FormatInt(order.Deposit, 10),
		"total_lots", strconv.FormatInt(r.TotalLots, 10))
	if hardClosed {
		chain.Emit("LaunchpadFairHardClosed", "id", id,
			"closed_at", strconv.FormatInt(now, 10))
	}
}

// CancelFairSale returns the entire unsold allocation to its creator while
// there are no contributions. It remains callable if the new-sale lane is
// paused or the quote currency has since been delisted. The creation fee is
// not returned.
func CancelFairSale(cur realm, id string) {
	creator := directCaller(cur)
	currency.AssertNoCoins(0, cur)
	r := GetFairSale(id)
	if r.Creator != creator || r.Cancelled || r.Settled || r.TotalLots != 0 || r.TotalDeposits != 0 {
		panic("launchpad/sales: fair cancellation denied")
	}
	r.Cancelled = true
	fairSales.Set(id, r)
	setTokenOwed(id, sm.Sub(tokenOwed(id), r.Allocation))
	tokens.Transfer(cross(cur), id, creator, r.Allocation)
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	chain.Emit("LaunchpadFairSaleCancelled", "id", id,
		"creator", creator.String(),
		"returned", strconv.FormatInt(r.Allocation, 10))
}

// Package sales owns launch token custody, direct-creation allocations, fair
// sales and airdrops. Quote that reaches it through its entry points is owed
// to someone on record: buyers (escrow and refunds), creators (settled
// proceeds) or the protocol (fees). Coins sent to it any other way are owed
// to no one and never leave. It has no admin and no emergency withdrawal path.
package sales

import (
	"strconv"
	"strings"
	"time"

	"chain"
	"chain/banker"
	"gno.land/p/samcrew/launchpad/currency/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	sm "gno.land/p/samcrew/launchpad/safemath/v1"
	"gno.land/p/samcrew/launchpad/vesting/v1"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/tokens/v1"
)

const salesPath = "gno.land/r/samcrew/launchpad/sales/v1"
const launchpadTokenRegistryPrefix = "gno.land/r/samcrew/launchpad/tokens/v1.T"

type VestingRecord struct {
	Beneficiary        address
	PendingBeneficiary address
	Total              int64
	Claimed            int64
	Start              int64
	Cliff              int64
	Duration           int64
	Revocable          bool
	Revoked            bool
	RevokedVested      int64
}

var feeLiability = map[string]int64{}

func directCaller(cur realm) address {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("launchpad/sales: direct user call required")
	}
	return cur.Previous().Address()
}

func directFee(version int64, key string) int64 {
	p := config.GetVersion(version)
	for _, c := range p.Currencies {
		if c.Key == key {
			if c.DirectCreationFee < 0 {
				panic("launchpad/sales: direct fee disabled")
			}
			return c.DirectCreationFee
		}
	}
	panic("launchpad/sales: currency has no direct terms")
}

func collectCreationFee(cur realm, key string, amount int64) {
	// A Launchpad token held here for vesting, airdrops or sales cannot also
	// back a fee or quote liability without a combined same-asset ledger.
	if strings.HasPrefix(key, launchpadTokenRegistryPrefix) {
		panic("launchpad/sales: launchpad token cannot be quote currency")
	}
	if amount == 0 {
		currency.AssertNoCoins(0, cur)
		return
	}
	collectQuote(cur, key, amount)
	feeLiability[key] = sm.Add(feeLiability[key], amount)
	assertQuoteCovered(cur, key)
}

// collectQuote takes amount from the immediate caller, as attached coins or
// from a token allowance. Both routes pay from that caller and no one else.
func collectQuote(cur realm, key string, amount int64) {
	if key == config.NativeCurrency {
		currency.CollectNative(0, cur, amount)
	} else {
		currency.CollectToken(0, cur, grc20reg.MustGet(key), amount)
	}
}

func quoteBalance(self address, key string) int64 {
	if key == config.NativeCurrency {
		return banker.NewReadonlyBanker().GetCoin(self, key)
	}
	return grc20reg.MustGet(key).BalanceOf(self)
}

// owedIn is everything the realm owes in one currency: fees, escrow, refunds
// and proceeds.
func owedIn(key string) int64 {
	owed := sm.Add(feeLiability[key], fairEscrowLiability[key])
	owed = sm.Add(owed, fairRefundLiability[key])
	return sm.Add(owed, fairProceedsLiability[key])
}

// assertQuoteCovered follows every movement of quote: the realm must still
// hold everything it owes in that currency. An exit ends with it; a creation
// runs it right after collecting its fee.
func assertQuoteCovered(cur realm, key string) {
	if quoteBalance(cur.Address(), key) < owedIn(key) {
		panic("launchpad/sales: quote custody shortfall")
	}
}

func payQuote(cur realm, key string, to address, amount int64) {
	if key == config.NativeCurrency {
		currency.PayNative(0, cur, to, amount)
	} else {
		currency.PayToken(0, cur, grc20reg.MustGet(key), to, amount)
	}
}

// SweepFees pays every fee recorded in one currency, creation fees and
// fair-sale primary fees alike, to the treasury of the current config, and
// returns the amount. Anyone can call it; the caller chooses neither the
// receiver nor the amount. A fee is only ever recorded once a treasury is
// named, and config never lets the treasury be removed.
func SweepFees(cur realm, currencyKey string) int64 {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	amount := feeLiability[currencyKey]
	if amount <= 0 {
		panic("launchpad/sales: no fees to sweep")
	}
	treasury := config.GetVersion(config.GetCurrentVersion()).Treasury
	// Config refuses to name this realm as treasury. If it ever did, a native
	// sweep would pay the realm itself: the fees would stop being owed and
	// stay here for good, and anyone could trigger it. So it is refused here
	// as well.
	if treasury == cur.Address() {
		panic("launchpad/sales: treasury is this realm")
	}
	feeLiability[currencyKey] = 0
	payQuote(cur, currencyKey, treasury, amount)
	assertQuoteCovered(cur, currencyKey)
	chain.Emit("LaunchpadFeesSwept", "currency", currencyKey,
		"treasury", treasury.String(), "amount", strconv.FormatInt(amount, 10),
		"actor", cur.Previous().Address().String())
	return amount
}

// CreateDirect creates a direct token without an initial airdrop. The
// allocation string is parsed and the whole amount partitioned before any
// payment. The caller, payer and initial mint's creator are the same live
// direct user.
func CreateDirect(cur realm, mode, name, ticker string, decimals int,
	initialSupply, maxSupply int64, currencyKey string, expectedVersion int64,
	description, image, website, xHandle, telegram, allocations string) string {
	return createDirect(cur, mode, name, ticker, decimals, initialSupply,
		maxSupply, currencyKey, expectedVersion, description, image, website,
		xHandle, telegram, allocations, "", "", 0)
}

// CreateDirectWithAirdrop reserves part of the initial mint for one Merkle
// campaign. The caller commits to the next token ID used in every leaf. If
// another launch takes that ID first, this transaction rejects before payment.
func CreateDirectWithAirdrop(cur realm, mode, name, ticker string, decimals int,
	initialSupply, maxSupply int64, currencyKey string, expectedVersion int64,
	description, image, website, xHandle, telegram, allocations,
	expectedID, airdropRoot string, airdropTotal int64) string {
	return createDirect(cur, mode, name, ticker, decimals, initialSupply,
		maxSupply, currencyKey, expectedVersion, description, image, website,
		xHandle, telegram, allocations, expectedID, airdropRoot, airdropTotal)
}

func createDirect(cur realm, mode, name, ticker string, decimals int,
	initialSupply, maxSupply int64, currencyKey string, expectedVersion int64,
	description, image, website, xHandle, telegram, allocations,
	expectedID, airdropRoot string, airdropTotal int64) string {
	creator := directCaller(cur)
	if mode != tokens.ModeDirectFixed && mode != tokens.ModeDirectCap {
		panic("launchpad/sales: direct mode required")
	}
	if airdropTotal > 0 {
		requireAirdropRoot(airdropRoot)
		nextID := "T" + strconv.FormatInt(sm.Add(tokens.Count(), 1), 10)
		if expectedID != nextID {
			panic("launchpad/sales: airdrop token ID changed")
		}
	} else if airdropTotal != 0 || expectedID != "" || airdropRoot != "" {
		panic("launchpad/sales: invalid airdrop allocation")
	}
	parsed, allocated := parseAllocations(allocations)
	committed := sm.Add(allocated, airdropTotal)
	if initialSupply <= 0 || committed > initialSupply {
		panic("launchpad/sales: allocations exceed supply")
	}
	config.AssertNewAction(config.LaneDirect, currencyKey, expectedVersion)
	if airdropTotal > 0 {
		config.AssertNewAction(config.LaneAirdrop, currencyKey, expectedVersion)
	}
	fee := directFee(expectedVersion, currencyKey)
	collectCreationFee(cur, currencyKey, fee)
	id := tokens.Create(cross(cur), creator, mode, name, ticker,
		decimals, initialSupply, maxSupply, currencyKey, expectedVersion,
		description, image, website, xHandle, telegram)
	if airdropTotal > 0 && id != expectedID {
		panic("launchpad/sales: airdrop token ID changed")
	}
	retained := airdropTotal
	for _, a := range parsed {
		if a.duration == 0 {
			tokens.Transfer(cross(cur), id, a.beneficiary, a.amount)
			continue
		}
		appendVesting(id, VestingRecord{
			Beneficiary: a.beneficiary, Total: a.amount,
			Start: a.start, Cliff: a.cliff, Duration: a.duration,
			Revocable: a.revocable,
		})
		retained = sm.Add(retained, a.amount)
	}
	if airdropTotal > 0 {
		airdrops.Set(id, AirdropRecord{Root: airdropRoot, Total: airdropTotal})
		chain.Emit("LaunchpadAirdropCreated", "id", id, "creator", creator.String(),
			"root", airdropRoot, "total", strconv.FormatInt(airdropTotal, 10))
	}
	remainder := sm.Sub(initialSupply, committed)
	if remainder > 0 {
		tokens.Transfer(cross(cur), id, creator, remainder)
	}
	setTokenOwed(id, retained)
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) != retained {
		panic("launchpad/sales: token custody mismatch")
	}
	chain.Emit("LaunchpadDirectCreated", "id", id, "creator", creator.String(),
		"currency", currencyKey, "fee", strconv.FormatInt(fee, 10),
		"retained", strconv.FormatInt(retained, 10))
	return id
}

// MintCappedAllocated requires the token's current mint authority to be the
// immediate user or realm caller. Every new unit is assigned to an immediate or vested
// allocation; there is no implicit receiver or unrecorded sales balance.
// No additional creation fee is charged, and attached native coins are
// rejected. Pausing the direct lane stops new mints without blocking claims.
func MintCappedAllocated(cur realm, id string, amount int64, allocations string) {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	previous := cur.Previous()
	authority := previous.Address()
	if !authority.IsValid() || (!previous.IsUserCall() &&
		(previous.PkgPath() == "" || authority != chain.PackageAddress(previous.PkgPath()))) {
		panic("launchpad/sales: immediate authority call required")
	}
	parsed, allocated := parseAllocations(allocations)
	if amount <= 0 || allocated != amount {
		panic("launchpad/sales: capped mint must be fully allocated")
	}
	// The original creator owns existing revocation rights. A successor mint
	// authority must not create a schedule the former authority can claw back.
	for _, a := range parsed {
		if a.revocable {
			panic("launchpad/sales: later mint vesting cannot be revocable")
		}
	}
	info := tokens.GetInfo(id)
	if info.Mode != tokens.ModeDirectCap || info.MintRenounced || info.MintAuthority != authority {
		panic("launchpad/sales: current mint authority only")
	}
	config.AssertLaneOpen(config.LaneDirect, info.CurrencyKey)
	tokens.MintCapped(cross(cur), id, authority, amount)
	retained := int64(0)
	for _, a := range parsed {
		if a.duration == 0 {
			tokens.Transfer(cross(cur), id, a.beneficiary, a.amount)
			continue
		}
		appendVesting(id, VestingRecord{
			Beneficiary: a.beneficiary, Total: a.amount,
			Start: a.start, Cliff: a.cliff, Duration: a.duration,
			Revocable: a.revocable,
		})
		retained = sm.Add(retained, a.amount)
	}
	setTokenOwed(id, sm.Add(tokenOwed(id), retained))
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	chain.Emit("LaunchpadCappedMintAllocated", "id", id,
		"authority", authority.String(), "amount", strconv.FormatInt(amount, 10),
		"retained", strconv.FormatInt(retained, 10))
}

func VestingCount(id string) int { return vestingCount(id) }

func GetVesting(id string, index int) VestingRecord {
	if index < 0 || index >= vestingCount(id) {
		panic("launchpad/sales: vesting record not found")
	}
	return vestingAt(id, index)
}

func TokenLiability(id string) int64 { return tokenOwed(id) }

// ClaimVested remains open even when the direct-launch lane is paused. Anyone
// may trigger release, but the destination is always the recorded beneficiary.
// This also permits a realm beneficiary to receive its vested tokens.
func ClaimVested(cur realm, id string, index int) int64 {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	if index < 0 || index >= vestingCount(id) {
		panic("launchpad/sales: vesting record not found")
	}
	r := vestingAt(id, index)
	if r.PendingBeneficiary != "" {
		panic("launchpad/sales: beneficiary move pending")
	}
	s := vesting.Schedule{Total: r.Total, Start: r.Start, Cliff: r.Cliff, Duration: r.Duration}
	amount := int64(0)
	if r.Revoked {
		amount = sm.Sub(r.RevokedVested, r.Claimed)
	} else {
		amount = s.Releasable(time.Now().Unix(), r.Claimed)
	}
	if amount <= 0 {
		panic("launchpad/sales: nothing vested to claim")
	}
	r.Claimed = sm.Add(r.Claimed, amount)
	setVesting(id, index, r)
	setTokenOwed(id, sm.Sub(tokenOwed(id), amount))
	tokens.Transfer(cross(cur), id, r.Beneficiary, amount)
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	chain.Emit("LaunchpadVestingClaimed", "id", id,
		"index", strconv.Itoa(index), "beneficiary", r.Beneficiary.String(),
		"actor", cur.Previous().Address().String(),
		"amount", strconv.FormatInt(amount, 10))
	return amount
}

// RevokeVesting returns only unvested tokens to the original creator. The
// beneficiary retains its accrued vested entitlement and claim right.
func RevokeVesting(cur realm, id string, index int) int64 {
	creator := directCaller(cur)
	currency.AssertNoCoins(0, cur)
	if tokens.GetInfo(id).Creator != creator || index < 0 || index >= vestingCount(id) {
		panic("launchpad/sales: creator vesting only")
	}
	r := vestingAt(id, index)
	if !r.Revocable || r.Revoked {
		panic("launchpad/sales: vesting is not revocable")
	}
	s := vesting.Schedule{Total: r.Total, Start: r.Start, Cliff: r.Cliff, Duration: r.Duration}
	vested := s.VestedAt(time.Now().Unix())
	unvested := sm.Sub(r.Total, vested)
	r.Revoked = true
	r.RevokedVested = vested
	setVesting(id, index, r)
	setTokenOwed(id, sm.Sub(tokenOwed(id), unvested))
	if unvested > 0 {
		tokens.Transfer(cross(cur), id, creator, unvested)
	}
	if tokens.BalanceOf(id, chain.PackageAddress(salesPath)) < tokenOwed(id) {
		panic("launchpad/sales: token custody shortfall")
	}
	chain.Emit("LaunchpadVestingRevoked", "id", id,
		"index", strconv.Itoa(index), "creator", creator.String(),
		"unvested", strconv.FormatInt(unvested, 10),
		"vested", strconv.FormatInt(vested, 10))
	return unvested
}

func vestingCaller(cur realm) address {
	if !cur.IsCurrent() {
		panic("launchpad/sales: stale realm context")
	}
	currency.AssertNoCoins(0, cur)
	return cur.Previous().Address()
}

// ProposeVestingBeneficiary is callable by the current beneficiary, including
// a beneficiary realm. A pending move freezes claims until acceptance or
// cancellation, so the old beneficiary cannot drain accrued entitlement.
func ProposeVestingBeneficiary(cur realm, id string, index int, next address) {
	who := vestingCaller(cur)
	r := GetVesting(id, index)
	if who != r.Beneficiary || !meta.ValidAddress(next) || next == who ||
		next == chain.PackageAddress(salesPath) {
		panic("launchpad/sales: beneficiary proposal denied")
	}
	r.PendingBeneficiary = next
	setVesting(id, index, r)
	chain.Emit("LaunchpadVestingBeneficiaryProposed", "id", id,
		"index", strconv.Itoa(index), "from", who.String(), "to", next.String())
}

func CancelVestingBeneficiary(cur realm, id string, index int) {
	who := vestingCaller(cur)
	r := GetVesting(id, index)
	if who != r.Beneficiary || r.PendingBeneficiary == "" {
		panic("launchpad/sales: beneficiary cancellation denied")
	}
	r.PendingBeneficiary = ""
	setVesting(id, index, r)
	chain.Emit("LaunchpadVestingBeneficiaryCancelled", "id", id,
		"index", strconv.Itoa(index), "beneficiary", who.String())
}

func AcceptVestingBeneficiary(cur realm, id string, index int) {
	who := vestingCaller(cur)
	r := GetVesting(id, index)
	if r.PendingBeneficiary == "" || who != r.PendingBeneficiary {
		panic("launchpad/sales: pending beneficiary only")
	}
	old := r.Beneficiary
	r.Beneficiary = who
	r.PendingBeneficiary = ""
	setVesting(id, index, r)
	chain.Emit("LaunchpadVestingBeneficiaryAccepted", "id", id,
		"index", strconv.Itoa(index), "from", old.String(), "to", who.String())
}

package sales

import (
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// Per-token, per-buyer and per-claim state lives in AVL trees: a write touches
// one entry and the path to it. A realm-level Go map is stored as one object,
// so each write would cost gas in proportion to everything the map holds, and
// a busy sale could price its own buyers out of their claims. The four
// per-currency liabilities stay maps: they hold one entry per currency, and
// only the config admin gives a currency terms.
var (
	vestings         = avl.NewTree() // "<token id>:<index>" -> VestingRecord
	vestingCounts    = avl.NewTree() // token id -> int
	tokenLiabilities = avl.NewTree() // token id -> int64
	airdrops         = avl.NewTree() // token id -> AirdropRecord
	airdropClaims    = avl.NewTree() // "<token id>:<index>" -> true
	fairSales        = avl.NewTree() // token id -> FairSaleRecord
	fairBuyers       = avl.NewTree() // "<token id>:<buyer>" -> FairBuyerRecord
)

// A token id is "T" and digits, so ":" separates it from what follows.
func indexKey(id string, index int) string { return id + ":" + strconv.Itoa(index) }
func buyerKey(id string, buyer address) string { return id + ":" + string(buyer) }

func vestingCount(id string) int {
	n, _ := vestingCounts.Get(id).(int)
	return n
}

// vestingAt returns record index of a token, which the caller has checked
// to be below vestingCount.
func vestingAt(id string, index int) VestingRecord {
	return vestings.Get(indexKey(id, index)).(VestingRecord)
}

func setVesting(id string, index int, r VestingRecord) { vestings.Set(indexKey(id, index), r) }

func appendVesting(id string, r VestingRecord) {
	n := vestingCount(id)
	vestings.Set(indexKey(id, n), r)
	vestingCounts.Set(id, n+1)
}

func tokenOwed(id string) int64 {
	v, _ := tokenLiabilities.Get(id).(int64)
	return v
}

// A token that is owed nothing has no entry.
func setTokenOwed(id string, amount int64) {
	if amount == 0 {
		tokenLiabilities.Remove(id)
		return
	}
	tokenLiabilities.Set(id, amount)
}

// airdropOf returns the zero record for a token without a campaign.
func airdropOf(id string) AirdropRecord {
	r, _ := airdrops.Get(id).(AirdropRecord)
	return r
}

package sales

import (
	"strconv"

	"chain"
	"gno.land/p/samcrew/launchpad/fairmath/v1"
	"gno.land/p/samcrew/launchpad/meta/v1"
	"gno.land/r/samcrew/launchpad/config/v1"
	"gno.land/r/samcrew/launchpad/tokens/v1"
)

// Read views for launch clients. Every int64, base units and timestamps alike,
// is a decimal string so JavaScript keeps it exact; booleans stay booleans and
// counts that fit in an int are numbers. They change no state.

func jsonInt(v int64) string { return meta.JSONString(strconv.FormatInt(v, 10)) }

// fairRecordJSON reports a sale's terms and outcome. Once settled, the primary
// fee is what was raised minus the creator's share.
func fairRecordJSON(r FairSaleRecord) string {
	s := r.Schedule
	return "{" +
		`"creator":` + meta.JSONString(r.Creator.String()) +
		`,"quoteCurrency":` + meta.JSONString(r.QuoteCurrency) +
		`,"configVersion":` + jsonInt(r.ConfigVersion) +
		`,"primaryFeeBps":` + jsonInt(r.PrimaryFeeBPS) +
		`,"allocation":` + jsonInt(r.Allocation) +
		`,"lotSize":` + jsonInt(r.LotSize) +
		`,"walletCapLots":` + jsonInt(r.WalletCapLots) +
		`,"hardCapLots":` + jsonInt(r.Caps.HardLots) +
		`,"softCapQuote":` + jsonInt(r.Caps.SoftQuote) +
		`,"start":` + jsonInt(s.Start) +
		`,"end":` + jsonInt(s.End) +
		`,"startPrice":` + jsonInt(s.StartPrice) +
		`,"floorPrice":` + jsonInt(s.FloorPrice) +
		`,"decrement":` + jsonInt(s.Decrement) +
		`,"intervalSeconds":` + jsonInt(s.IntervalSeconds) +
		`,"allowlistRoot":` + meta.JSONString(r.AllowlistRoot) +
		`,"holdingGates":` + meta.JSONString(r.HoldingGates) +
		`,"totalLots":` + jsonInt(r.TotalLots) +
		`,"totalDeposits":` + jsonInt(r.TotalDeposits) +
		`,"hardClosedAt":` + jsonInt(r.HardClosedAt) +
		`,"cancelled":` + strconv.FormatBool(r.Cancelled) +
		`,"settled":` + strconv.FormatBool(r.Settled) +
		`,"succeeded":` + strconv.FormatBool(r.Succeeded) +
		`,"closeAt":` + jsonInt(r.CloseAt) +
		`,"closePrice":` + jsonInt(r.ClosePrice) +
		`,"soldTokens":` + jsonInt(r.SoldTokens) +
		`,"grossQuote":` + jsonInt(r.GrossQuote) +
		`,"primaryFeeQuote":` + jsonInt(r.GrossQuote-r.CreatorQuote) +
		`,"creatorQuote":` + jsonInt(r.CreatorQuote) +
		`,"proceedsReleased":` + strconv.FormatBool(r.ProceedsReleased) +
		`,"refundQuote":` + jsonInt(r.RefundQuote) +
		`,"unsoldTokens":` + jsonInt(r.UnsoldTokens) +
		`,"refundPaid":` + jsonInt(r.RefundPaid) +
		`,"tokensClaimed":` + jsonInt(r.TokensClaimed) + "}"
}

func airdropRecordJSON(r AirdropRecord) string {
	return "{" +
		`"root":` + meta.JSONString(r.Root) +
		`,"total":` + jsonInt(r.Total) +
		`,"claimed":` + jsonInt(r.Claimed) + "}"
}

// TermsJSON is what launching a token in a currency costs under the current
// config version: the fee a direct creation and a fair-sale creation attach,
// exactly; the most one fair sale may raise; and the primary fee a new sale
// pins. A fee of -1 means the currency has no terms. A creation names this
// version, so if the terms change before it lands it fails with "config
// changed" and takes nothing. Whether a lane takes new launches now is
// config's ActionStatusJSON.
func TermsJSON(currencyKey string) string {
	if currencyKey == "" || len(currencyKey) > 200 {
		panic("launchpad/sales: invalid currency")
	}
	version := config.GetCurrentVersion()
	p := config.GetVersion(version)
	direct, fair, raiseCap := int64(-1), int64(-1), int64(0)
	for _, c := range p.Currencies {
		if c.Key == currencyKey {
			direct, fair, raiseCap = c.DirectCreationFee, c.FairSaleCreationFee, c.FairSaleRaiseCap
		}
	}
	return "{" +
		`"schema":"launchpad-sales-terms-v1"` +
		`,"version":` + jsonInt(version) +
		`,"currency":` + meta.JSONString(currencyKey) +
		`,"directCreationFee":` + jsonInt(direct) +
		`,"fairSaleCreationFee":` + jsonInt(fair) +
		`,"fairSaleRaiseCap":` + jsonInt(raiseCap) +
		`,"primaryFeeBps":` + jsonInt(p.PrimaryFeeBPS) + "}"
}

// SolvencyJSON is the realm's books in one currency: the balance it holds and
// what it owes, in total and by liability. fees is what SweepFees would pay
// now. Every movement of quote ends with balance >= owed, so a watcher that
// sees otherwise has found a fault; what the balance holds above owed was
// sent outside the entry points and is owed to no one. An empty key or one
// over 200 bytes panics "invalid currency"; a key that is neither ugnot nor a
// registered GRC20 aborts in the registry ("unknown token").
func SolvencyJSON(currencyKey string) string {
	if currencyKey == "" || len(currencyKey) > 200 {
		panic("launchpad/sales: invalid currency")
	}
	return "{" +
		`"schema":"launchpad-sales-solvency-v1"` +
		`,"currency":` + meta.JSONString(currencyKey) +
		`,"balance":` + jsonInt(quoteBalance(chain.PackageAddress(salesPath), currencyKey)) +
		`,"owed":` + jsonInt(owedIn(currencyKey)) +
		`,"fees":` + jsonInt(feeLiability[currencyKey]) +
		`,"escrow":` + jsonInt(fairEscrowLiability[currencyKey]) +
		`,"refunds":` + jsonInt(fairRefundLiability[currencyKey]) +
		`,"proceeds":` + jsonInt(fairProceedsLiability[currencyKey]) + "}"
}

// LaunchJSON is a token's launch state: the ledger's record of the token, what
// sales still owes in it, how many vesting records it has, and its fair sale
// and airdrop campaign, each null when the token has none.
func LaunchJSON(id string) string {
	token := tokens.TokenJSON(id)
	fair := "null"
	if r, ok := fairSales.Get(id).(FairSaleRecord); ok {
		fair = fairRecordJSON(r)
	}
	airdrop := "null"
	if r, ok := airdrops.Get(id).(AirdropRecord); ok {
		airdrop = airdropRecordJSON(r)
	}
	return "{" +
		`"schema":"launchpad-sales-v1"` +
		`,"token":` + token +
		`,"tokenLiability":` + jsonInt(tokenOwed(id)) +
		`,"vestingCount":` + strconv.Itoa(vestingCount(id)) +
		`,"fairSale":` + fair +
		`,"airdrop":` + airdrop + "}"
}

// FairBuyerJSON is one buyer's record in a sale and, once the sale is settled
// and until the buyer is paid, what ClaimFair would send them. Before
// settlement both amounts are 0 and settled is false: settle first.
func FairBuyerJSON(id string, buyer address) string {
	r := GetFairSale(id)
	b := GetFairBuyer(id, buyer)
	claimTokens, claimRefund := int64(0), int64(0)
	if r.Settled && b.Lots > 0 && !b.Claimed {
		c := fairmath.Claim(r.Succeeded, b.Lots, b.Deposit, r.LotSize, r.ClosePrice)
		claimTokens, claimRefund = c.Tokens, c.RefundQuote
	}
	return "{" +
		`"buyer":` + meta.JSONString(buyer.String()) +
		`,"lots":` + jsonInt(b.Lots) +
		`,"deposit":` + jsonInt(b.Deposit) +
		`,"claimableTokens":` + jsonInt(claimTokens) +
		`,"claimableRefund":` + jsonInt(claimRefund) +
		`,"settled":` + strconv.FormatBool(r.Settled) +
		`,"claimed":` + strconv.FormatBool(b.Claimed) + "}"
}

// VestingJSON is one vesting record: its schedule, who holds the claim right
// and who has been proposed to take it.
func VestingJSON(id string, index int) string {
	r := GetVesting(id, index)
	return "{" +
		`"index":` + strconv.Itoa(index) +
		`,"beneficiary":` + meta.JSONString(r.Beneficiary.String()) +
		`,"pendingBeneficiary":` + meta.JSONString(r.PendingBeneficiary.String()) +
		`,"total":` + jsonInt(r.Total) +
		`,"claimed":` + jsonInt(r.Claimed) +
		`,"start":` + jsonInt(r.Start) +
		`,"cliff":` + jsonInt(r.Cliff) +
		`,"duration":` + jsonInt(r.Duration) +
		`,"revocable":` + strconv.FormatBool(r.Revocable) +
		`,"revoked":` + strconv.FormatBool(r.Revoked) +
		`,"revokedVested":` + jsonInt(r.RevokedVested) + "}"
}
